/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"통칙(법원·신의성실의 원칙)":{"묶음":[{"머리":"법원(法源)의 순서","줄":[{"t":"제1조: 민사에 관하여 법률에 규정이 없으면 관습법에 의하고, 관습법이 없으면 조리에 의한다.","src":"민법 제1조"},{"t":"제1조의 「법률」은 형식적 의미의 민법만이 아니라 민사에 관한 모든 성문법이다. 조약, 일반적으로 승인된 국제법규, 지방의회의 민사 조례, 대법원규칙(부동산등기규칙 등)도 포함한다.","src":"기출 2023-1, 2024-3, 2026-1"},{"t":"판례는 제1조가 법원으로 규정하지 않는다. 조리는 제1조에 법원으로 규정되어 있다.","src":"기출 2026-1"},{"t":"관습법: 성문법에 반하지 않는 경우에 한해 보충적 법원이 된다.","src":"기출 2024-3"},{"t":"관습법 성립 요건: 사회의 거듭된 관행으로 생성된 사회생활규범이 법적 규범으로 승인되어야 하고 전체 법질서에 반하지 않아야 한다.","src":"기출 2024-3"},{"t":"관습법은 당사자의 주장·증명을 기다리지 않고 법원(法院)이 직권으로 확정한다.","src":"기출 2023-1, 2026-1"},{"t":"사실인 관습: 법령으로서의 효력이 없는 단순한 관행이며 법률행위 당사자의 의사를 보충함에 그친다.","src":"기출 2024-3"},{"t":"사실인 관습의 존재는 당사자가 주장·증명하여야 한다(관습법과 구별).","src":"보충(원문 미확인)"}]},{"머리":"신의성실의 원칙(제2조)","줄":[{"t":"제2조 제1항: 권리의 행사와 의무의 이행은 신의에 좇아 성실히 하여야 한다.","src":"민법 제2조"},{"t":"제2조 제2항: 권리는 남용하지 못한다.","src":"민법 제2조"},{"t":"신의칙 위반 여부와 권리남용 여부는 당사자의 주장이 없어도 법원이 직권으로 판단할 수 있다.","src":"기출 2021-9, 2022-9, 2023-4"},{"t":"강행법규를 위반한 자가 스스로 그 약정의 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 반하지 않는다.","src":"기출 2022-9, 2023-4"},{"t":"수익보장약정이 투자신탁회사의 먼저 한 제의로 체결되었더라도 그 회사가 스스로 약정의 무효를 주장하는 것은 신의칙에 반하지 않는다.","src":"보충(원문 미확인)"},{"t":"실효의 원칙은 항소권과 같은 소송법상의 권리에도 적용될 수 있다.","src":"기출 2022-9"},{"t":"소멸시효 완성의 항변권 행사도 신의칙의 적용을 받는다(채무자의 시효 주장이 신의칙에 반하면 허용되지 않는다).","src":"기출 2023-4"},{"t":"임대차에서 차임불증액 특약이 있어도 신의칙에 반할 정도의 사정변경이 있으면 형평의 원칙상 임대인의 차임 증액청구를 인정할 수 있다.","src":"기출 2022-9"},{"t":"회사 이사가 재직 중 채무액과 변제기가 특정된 회사채무를 보증한 경우, 이사직 사임이라는 사정변경만으로 일방적으로 보증계약을 해지할 수 없다.","src":"기출 2022-9"},{"t":"사정변경으로 인한 계약해제·해지에서 「사정」은 계약의 기초가 된 객관적 사정이다. 합리적 사람이 예견할 수 있었던 사정변경이면 해지할 수 없다.","src":"보충(원문 미확인)"},{"t":"숙박업 등 공중접객업자는 고객의 생명·신체 안전을 배려할 신의칙상 보호의무를 진다.","src":"기출 2023-4"},{"t":"신의칙 위반 판례(2021-2): 고의 불법행위자가 피해자의 부주의를 이유로 책임 감경을 주장하는 것(ㄱ)과 취득시효 완성 후 권리를 주장하지 않기로 하고 이에 반해 시효를 주장하는 것(ㄴ)은 신의칙 위반이다.","src":"보충(원문 미확인)"},{"t":"신의칙 위반이 아닌 판례(2021-2): 상속포기를 약정한 상속인이 상속개시 후 상속권을 주장하는 것(ㄷ), 동의 없이 신용구매계약을 한 미성년자가 동의 없음을 이유로 취소하는 것(ㄹ). 정답 5.","src":"보충(원문 미확인)"}]}],"함정":[{"x":"판례는 사실인 관습에 대해 법령으로서의 효력을 인정한다.","o":"사실인 관습은 법령으로서의 효력이 없고 당사자 의사 보충에 그친다.","src":"기출 2023-1"},{"x":"민법의 법원(法源)은 민사에 관하여 재판을 할 때 적용되는 기준으로서 형식적 의미의 민법만이 이에 해당한다.","o":"민사에 관한 조약·국제법규·조례·특별법 등 모든 성문법이 포함된다.","src":"기출 2023-1"},{"x":"대법원이 제정한 부동산등기규칙은 민법의 법원이 아니다.","o":"민사에 관한 것이므로 법원이 될 수 있다.","src":"기출 2023-1"},{"x":"민사에 관하여 일반적으로 승인된 국제법규라도 국회가 비준하지 않으면 민법의 법원이 될 수 없음이 원칙이다.","o":"일반적으로 승인된 국제법규는 비준 없이도 법원이 될 수 있다.","src":"기출 2023-1"},{"x":"민법 제1조는 판례를 민법의 법원으로 규정하고 있다.","o":"제1조는 법률, 관습법, 조리를 규정하며 판례는 규정하지 않는다.","src":"기출 2026-1"},{"x":"관습법은 당사자가 그 존재를 주장ㆍ증명하여야 법원(法院)이 이를 확정할 수 있다.","o":"관습법은 직권으로 확정한다.","src":"기출 2024-3"},{"x":"강행법규를 위반한 자가 스스로 그 약정의 무효를 주장하는 것은 특별한 사정이 없는 한 신의칙에 위반된다.","o":"신의칙에 반하지 않는다.","src":"기출 2022-9, 2023-4"},{"x":"소멸시효를 이유로 한 항변권의 행사는 원칙적으로 신의칙의 적용을 받지 않는다.","o":"신의칙의 적용을 받는다.","src":"기출 2023-4"}]},"권리의 주체(자연인·법인·비법인사단)":{"묶음":[{"머리":"자연인의 권리능력","줄":[{"t":"제3조: 사람은 생존한 동안 권리와 의무의 주체가 된다.","src":"민법 제3조"},{"t":"권리능력은 출생한 때(전부노출) 취득한다. 출생신고 시가 아니다.","src":"기출 2023-3"},{"t":"태아: 손해배상의 청구권에 관하여는 이미 출생한 것으로 본다.","src":"민법 제762조"},{"t":"태아의 법적 지위에 관한 판례는 정지조건설(살아서 출생하면 문제된 시점으로 소급해 권리능력을 인정)이다.","src":"기출 2023-3"},{"t":"태아는 법정대리인을 통한 수증행위도 할 수 없다(판례).","src":"기출 2023-3"},{"t":"동물은 위자료 청구권의 귀속주체가 될 수 없다.","src":"기출 2021-1"},{"t":"동시사망: 2인 이상이 동일한 위난으로 사망한 경우 동시에 사망한 것으로 추정한다.","src":"민법 제30조"}]},{"머리":"부재자·실종선고","줄":[{"t":"부재자 재산관리: 종래 주소·거소를 떠난 자가 재산관리인을 정하지 않으면 법원은 이해관계인이나 검사의 청구로 필요한 처분을 명하여야 한다.","src":"민법 제22조"},{"t":"법원이 선임한 재산관리인이 제118조의 권한을 넘는 행위를 하려면 법원의 허가를 얻어야 한다.","src":"민법 제25조"},{"t":"법원이 선임한 재산관리인은 관리할 재산목록을 작성하여야 한다.","src":"민법 제24조"},{"t":"법원은 선임한 재산관리인에게 상당한 담보를 제공하게 할 수 있고 부재자의 재산으로 상당한 보수를 지급할 수 있다.","src":"민법 제26조"},{"t":"실종선고 요건: 부재자의 생사가 5년간 분명하지 아니한 때. 법원은 이해관계인이나 검사의 청구에 의하여 실종선고를 하여야 한다.","src":"민법 제27조"},{"t":"특별실종: 전지에 임한 자, 침몰한 선박·추락한 항공기 중에 있던 자 기타 위난을 당한 자는 전쟁 종지 후 또는 위난이 종료한 후 1년간 생사가 분명하지 아니한 때.","src":"민법 제27조"},{"t":"실종선고를 받은 자는 위 기간이 만료한 때에 사망한 것으로 본다.","src":"민법 제28조"},{"t":"실종선고의 취소: 실종자의 생존 또는 다른 시점의 사망 증명이 있으면 법원이 본인·이해관계인·검사의 청구로 취소하여야 한다. 실종선고 후 취소 전에 선의로 한 행위의 효력에는 영향이 없다.","src":"민법 제29조"},{"t":"취소 시 반환범위: 직접원인으로 재산을 취득한 자가 선의이면 현존이익 한도, 악의이면 이익에 이자를 붙여 반환하고 손해가 있으면 배상한다.","src":"민법 제29조"},{"t":"실종선고는 생환만으로 당연히 효력을 잃지 않고 취소 심판이 있어야 한다.","src":"보충(원문 미확인)"},{"t":"실종선고 청구권자인 이해관계인은 법률상 이해관계를 가진 자다. 선순위 상속인이 있으면 후순위 상속인은 이해관계인이 아니다.","src":"보충(원문 미확인)"}]},{"머리":"행위능력: 미성년자","줄":[{"t":"성년: 19세.","src":"민법 제4조"},{"t":"미성년자가 법률행위를 함에는 법정대리인의 동의를 얻어야 한다. 다만 권리만을 얻거나 의무만을 면하는 행위는 동의가 필요 없다.","src":"민법 제5조"},{"t":"동의 없이 한 행위는 취소할 수 있다.","src":"민법 제5조"},{"t":"부담부증여계약, 경매절차의 매수인 지위는 의무를 지는 행위여서 법정대리인의 동의가 필요하다.","src":"기출 2024-2"},{"t":"법정대리인이 범위를 정하여 처분을 허락한 재산은 미성년자가 임의로 처분할 수 있다.","src":"민법 제6조"},{"t":"법정대리인은 미성년자가 아직 법률행위를 하기 전에는 제5조·제6조의 동의와 허락을 취소할 수 있다.","src":"민법 제7조"},{"t":"영업의 허락: 미성년자가 법정대리인으로부터 허락을 얻은 특정한 영업에 관하여는 성년자와 동일한 행위능력이 있다.","src":"민법 제8조"},{"t":"법정대리인은 영업허락을 취소 또는 제한할 수 있으나 선의의 제3자에게 대항하지 못한다.","src":"민법 제8조"},{"t":"특정한 영업에 관한 허락이 있으면 그 영업에 관해서는 법정대리인의 대리권이 소멸한다.","src":"기출 2022-6"},{"t":"미성년자가 타인의 대리인으로 한 법률행위는 법정대리인의 동의 없이도 유효하다(대리인은 행위능력자임을 요하지 않음, 제117조).","src":"기출 2021-12"}]},{"머리":"행위능력: 성년후견·한정후견·특정후견","줄":[{"t":"성년후견개시 대상: 정신적 제약으로 사무를 처리할 능력이 지속적으로 결여된 사람.","src":"민법 제9조"},{"t":"성년후견개시 청구권자: 본인, 배우자, 4촌 이내의 친족, 미성년후견인·미성년후견감독인, 한정후견인·한정후견감독인, 특정후견인·특정후견감독인, 검사, 지방자치단체의 장.","src":"민법 제9조"},{"t":"가정법원은 성년후견개시 심판을 할 때 본인의 의사를 고려하여야 한다.","src":"민법 제9조"},{"t":"피성년후견인의 법률행위는 취소할 수 있다. 가정법원은 취소할 수 없는 법률행위의 범위를 정할 수 있다.","src":"민법 제10조"},{"t":"일용품의 구입 등 일상생활에 필요하고 대가가 과도하지 않은 법률행위는 성년후견인이 취소할 수 없다.","src":"민법 제10조"},{"t":"성년후견인은 대리권과 취소권을 가지며 재산상 법률행위에 대한 동의권은 없다.","src":"기출 2022-6"},{"t":"한정후견개시 대상: 정신적 제약으로 사무를 처리할 능력이 부족한 사람. 개시 시 본인의 의사를 고려한다(제9조 제2항 준용).","src":"민법 제12조"},{"t":"가정법원이 정한 범위에서 한정후견인의 동의가 필요하다. 동의 없이 한 행위는 취소할 수 있으나 일용품 구입 등 일상생활에 필요하고 대가가 과도하지 않은 행위는 제외된다.","src":"민법 제13조"},{"t":"한정후견인이 피한정후견인의 이익 침해 염려에도 동의하지 않으면 가정법원은 피한정후견인의 청구에 의하여 동의를 갈음하는 허가를 할 수 있다.","src":"민법 제13조"},{"t":"특정후견 대상: 일시적 후원 또는 특정한 사무에 관한 후원이 필요한 사람.","src":"민법 제14조의2"},{"t":"특정후견 청구권자: 본인, 배우자, 4촌 이내의 친족, 미성년후견인·미성년후견감독인, 검사, 지방자치단체의 장.","src":"민법 제14조의2"},{"t":"특정후견은 본인의 의사에 반하여 할 수 없다. 심판을 할 때는 특정후견의 기간 또는 사무의 범위를 정하여야 한다.","src":"민법 제14조의2"},{"t":"피특정후견인은 행위능력이 제한되지 않는다. 특정후견인에게 법정대리권이 부여되어도 피특정후견인은 스스로 그 법률행위를 할 수 있다.","src":"기출 2025-1"},{"t":"법인도 성년후견인이 될 수 있고 성년후견인은 여러 명일 수 있다.","src":"기출 2025-1"},{"t":"가정법원이 피한정후견인·피특정후견인에 대하여 성년후견개시 심판을 할 때에는 종전의 한정후견·특정후견의 종료 심판을 한다(한정후견개시 때도 같은 방식).","src":"민법 제14조의3"}]},{"머리":"제한능력자의 상대방 보호","줄":[{"t":"확답을 촉구할 권리: 상대방은 능력자가 된 후의 제한능력자에게 1개월 이상의 기간을 정하여 추인 여부의 확답을 촉구할 수 있다. 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다.","src":"민법 제15조"},{"t":"아직 능력자가 되지 못한 경우에는 법정대리인에게 촉구한다. 확답이 없으면 추인한 것으로 본다.","src":"민법 제15조"},{"t":"특별한 절차가 필요한 행위는 기간 내에 그 절차를 밟은 확답을 발송하지 않으면 취소한 것으로 본다.","src":"민법 제15조"},{"t":"철회권: 제한능력자가 맺은 계약은 추인이 있을 때까지 상대방이 그 의사표시를 철회할 수 있다. 상대방이 계약 당시 제한능력자임을 알았으면 철회할 수 없다.","src":"민법 제16조"},{"t":"거절권: 제한능력자의 단독행위는 추인이 있을 때까지 상대방이 거절할 수 있다.","src":"민법 제16조"},{"t":"철회·거절의 의사표시는 제한능력자에게도 할 수 있다.","src":"민법 제16조"},{"t":"속임수: 제한능력자가 속임수로써 자기를 능력자로 믿게 한 경우 그 행위를 취소할 수 없다.","src":"민법 제17조"},{"t":"미성년자나 피한정후견인이 속임수로써 법정대리인의 동의가 있는 것으로 믿게 한 경우에도 취소할 수 없다. 제2항의 대상은 이 둘뿐이고 피성년후견인은 포함되지 않는다.","src":"민법 제17조"},{"t":"제한능력을 이유로 취소된 경우 선의·악의를 묻지 않고 받은 이익이 현존하는 한도에서 반환한다.","src":"기출 2025-1"}]},{"머리":"법인의 설립","줄":[{"t":"법인은 법률의 규정에 의함이 아니면 성립하지 못한다(법인법정주의).","src":"민법 제31조"},{"t":"학술·종교·자선·기예·사교 기타 영리 아닌 사업을 목적으로 하는 사단 또는 재단은 주무관청의 허가를 얻어 법인으로 할 수 있다.","src":"민법 제32조"},{"t":"허가 여부는 주무관청의 재량에 속한다.","src":"기출 2024-6"},{"t":"법인은 그 주된 사무소의 소재지에서 설립등기를 함으로써 성립한다.","src":"민법 제33조"},{"t":"영리를 목적으로 하는 사단은 상사회사 설립의 조건에 좇아 법인으로 할 수 있고, 이 사단법인에는 상사회사에 관한 규정을 준용한다.","src":"민법 제39조"},{"t":"설립허가가 있으면 3주간 내에 주된 사무소 소재지에서 설립등기를 하여야 한다.","src":"민법 제49조"},{"t":"설립등기 사항: 목적, 명칭, 사무소, 설립허가의 연월일, 존립시기나 해산이유(정한 때), 자산의 총액, 출자의 방법(정한 때), 이사의 성명·주소, 이사의 대표권 제한(제한한 때). 감사는 등기사항이 아니다.","src":"민법 제49조"},{"t":"설립등기 이외의 등기사항은 등기 후가 아니면 제3자에게 대항하지 못한다. 등기사항을 변경한 때는 3주간 내에 변경등기를 한다.","src":"민법 제52조, 제54조"},{"t":"주무관청의 허가취소 사유: 목적 이외의 사업을 한 때, 설립허가의 조건에 위반한 때, 기타 공익을 해하는 행위를 한 때.","src":"민법 제38조"},{"t":"법인의 사무는 주무관청이 검사·감독한다. 법인의 해산 및 청산은 법원이 검사·감독한다.","src":"민법 제37조, 제95조"},{"t":"법인의 주소는 주된 사무소의 소재지에 있는 것으로 한다.","src":"민법 제36조"},{"t":"법인의 권리능력: 법률의 규정에 좇아 정관으로 정한 목적의 범위 내에서 권리와 의무의 주체가 된다.","src":"민법 제34조"}]},{"머리":"정관","줄":[{"t":"사단법인 정관 필요적 기재사항: 목적, 명칭, 사무소의 소재지, 자산에 관한 규정, 이사의 임면에 관한 규정, 사원자격의 득실에 관한 규정, 존립시기나 해산사유(정하는 때에 한함).","src":"민법 제40조"},{"t":"재단법인: 설립자가 일정한 재산을 출연하고 제40조 제1호 내지 제5호(목적, 명칭, 사무소 소재지, 자산, 이사 임면)를 기재한 정관을 작성하여 기명날인한다.","src":"민법 제43조"},{"t":"자산에 관한 규정은 사단법인·재단법인 모두 정관의 필요적 기재사항이다.","src":"민법 제40조, 제43조"},{"t":"이사의 대표권 제한은 정관에 기재하지 아니하면 효력이 없고, 등기하지 아니하면 제3자에게 대항하지 못한다.","src":"민법 제41조, 제60조"},{"t":"사단법인 정관변경: 총사원 3분의 2 이상의 동의(정수에 관하여 정관에 다른 규정이 있으면 그에 따름)와 주무관청의 허가.","src":"민법 제42조"},{"t":"정관변경 권한은 사원총회의 전속적 권한이어서 정관으로도 박탈할 수 없다.","src":"기출 2023-6"},{"t":"재단법인 정관은 변경방법을 정관에 정한 때에 한하여 변경할 수 있고 주무관청의 허가가 있어야 효력이 있다. 변경방법을 정관에 정한 때에도 허가가 필요하다.","src":"민법 제45조"},{"t":"재단법인의 목적 달성 또는 재산 보전을 위해 적당한 때에는 정관 변경방법의 규정에 불구하고 명칭 또는 사무소 소재지를 변경할 수 있다(허가 필요).","src":"민법 제45조"},{"t":"재단법인의 목적을 달성할 수 없는 때에는 설립자나 이사가 주무관청의 허가를 얻어 설립 취지를 참작하여 목적 기타 정관 규정을 변경할 수 있다.","src":"민법 제46조"},{"t":"재단법인 기본재산에 저당권을 설정하는 행위는 특별한 사정이 없는 한 주무관청의 허가를 얻을 필요가 없다는 것이 기출의 정답 문장이다.","src":"기출 2022-5"},{"t":"재단법인 기본재산을 새로 편입하는 행위는 정관 변경에 해당하여 주무관청의 허가가 있어야 유효하다.","src":"기출 2025-4"},{"t":"재단법인 설립자가 명칭·사무소 소재지·이사 임면 방법을 정하지 않고 사망한 때에는 이해관계인 또는 검사의 청구로 법원이 정한다.","src":"민법 제44조"},{"t":"생전처분으로 재단법인을 설립하면 증여에 관한 규정을, 유언으로 설립하면 유증에 관한 규정을 준용한다.","src":"민법 제47조"},{"t":"출연재산 귀속시기: 생전처분은 법인이 성립된 때, 유언은 유언의 효력이 발생한 때.","src":"민법 제48조"}]},{"머리":"법인의 기관","줄":[{"t":"이사는 법인의 필수기관이다(법인은 이사를 두어야 한다). 감사는 정관 또는 총회의 결의로 둘 수 있는 임의기관이다. 이사회는 민법에 규정이 없다.","src":"민법 제57조, 제66조"},{"t":"이사는 법인의 사무를 집행한다. 이사가 수인이면 정관에 다른 규정이 없는 한 과반수로 결정한다.","src":"민법 제58조"},{"t":"이사는 법인의 사무에 관하여 각자 법인을 대표한다. 정관에 규정한 취지에 위반할 수 없고 사단법인은 총회의 의결에 의하여야 한다.","src":"민법 제59조"},{"t":"이사는 선량한 관리자의 주의로 직무를 행하여야 한다. 임무를 해태한 이사는 법인에 대하여 연대하여 손해배상책임이 있다.","src":"민법 제61조, 제65조"},{"t":"이사는 정관 또는 총회의 결의로 금지하지 아니한 사항에 한하여 타인으로 하여금 특정한 행위를 대리하게 할 수 있다. 그 대리인은 법인의 대표기관이 아니다.","src":"민법 제62조, 기출 2025-4"},{"t":"임시이사: 이사가 없거나 결원이 있어 손해가 생길 염려가 있는 때 법원은 이해관계인이나 검사의 청구에 의하여 선임하여야 한다.","src":"민법 제63조"},{"t":"특별대리인: 법인과 이사의 이익이 상반하는 사항에 관하여 이사는 대표권이 없고, 제63조에 따라 특별대리인을 선임하여야 한다.","src":"민법 제64조"},{"t":"직무집행정지·직무대행자 선임 가처분은 주사무소 소재지의 등기소에서 등기한다.","src":"민법 제52조의2"},{"t":"직무대행자는 가처분명령에 다른 정함이 있는 경우 외에는 법인의 통상사무에 속하지 아니한 행위를 하지 못한다(법원 허가 시 예외). 위반 행위라도 법인은 선의의 제3자에 대하여 책임을 진다.","src":"민법 제60조의2"},{"t":"법원의 직무집행정지 가처분으로 대표권이 정지된 대표이사가 정지기간 중 체결한 계약은 절대적으로 무효이다.","src":"기출 2022-5"},{"t":"감사의 직무: 재산상황 감사, 이사 업무집행 감사, 부정·불비를 발견한 때 총회 또는 주무관청에 보고, 보고를 위해 필요한 때 총회 소집.","src":"민법 제67조"}]},{"머리":"사단법인의 총회","줄":[{"t":"사단법인의 사무는 정관으로 이사 또는 기타 임원에게 위임한 사항 외에는 총회의 결의에 의한다.","src":"민법 제68조"},{"t":"통상총회: 이사는 매년 1회 이상 소집하여야 한다.","src":"민법 제69조"},{"t":"임시총회: 이사가 필요하다고 인정한 때 소집할 수 있다. 총사원의 5분의 1 이상이 회의 목적사항을 제시하여 청구한 때에는 소집하여야 한다. 이 정수는 정관으로 증감할 수 있다.","src":"민법 제70조"},{"t":"청구 후 2주간 내에 이사가 소집절차를 밟지 않으면 청구한 사원이 법원의 허가를 얻어 소집할 수 있다.","src":"민법 제70조"},{"t":"총회 소집은 1주간 전에 회의의 목적사항을 기재한 통지를 발하고 기타 정관에 정한 방법에 의한다.","src":"민법 제71조"},{"t":"총회는 통지한 사항에 관하여서만 결의할 수 있다. 정관에 다른 규정이 있으면 그에 따른다.","src":"민법 제72조"},{"t":"각 사원의 결의권은 평등하다. 사원은 서면이나 대리인으로 결의권을 행사할 수 있다. 정관에 다른 규정이 있으면 적용하지 않는다.","src":"민법 제73조"},{"t":"사단법인과 어느 사원의 관계사항을 의결하는 경우 그 사원은 결의권이 없다.","src":"민법 제74조"},{"t":"결의 정족수: 법 또는 정관에 다른 규정이 없으면 사원 과반수의 출석과 출석사원 결의권의 과반수. 서면·대리인으로 결의권을 행사하는 사원은 출석한 것으로 본다.","src":"민법 제75조"},{"t":"총회의 의사에 관하여 의사록을 작성하고 의사의 경과·요령·결과를 기재해 의장 및 출석한 이사가 기명날인한다. 이사는 의사록을 주된 사무소에 비치한다.","src":"민법 제76조"},{"t":"사단법인 사원의 지위는 양도·상속할 수 없다(제56조). 다만 정관에 정함이 있으면 양도할 수 있다는 것이 기출의 정답 문장이다.","src":"민법 제56조, 기출 2022-5"},{"t":"사단법인은 성립한 때 및 매년 3월 내에 재산목록을 작성해 사무소에 비치하고 사원명부를 비치하여 사원 변경 시 기재한다.","src":"민법 제55조"},{"t":"사원총회가 정관의 규범적 의미와 다른 해석을 결의로 표명해도 그 해석은 법원을 구속하지 않는다.","src":"보충(원문 미확인)"}]},{"머리":"법인의 불법행위(제35조)","줄":[{"t":"법인은 이사 기타 대표자가 직무에 관하여 타인에게 가한 손해를 배상할 책임이 있다. 대표자는 이로 인한 자기의 손해배상책임을 면하지 못한다.","src":"민법 제35조"},{"t":"대표권이 없는 이사의 행위로는 법인의 불법행위책임이 성립하지 않는다.","src":"기출 2023-5, 2025-5"},{"t":"법인을 실질적으로 운영하며 사실상 대표하여 사무를 집행하는 사람도 대표자에 포함된다.","src":"기출 2023-5"},{"t":"대표자가 사리를 도모할 의도였더라도 외관상 객관적으로 직무에 관한 행위로 인정되면 직무에 관한 행위다. 법령 규정에 위배된다는 사정은 이를 막지 못한다.","src":"기출 2025-5"},{"t":"직무에 관한 행위가 아님을 피해자가 알았다면 법인에 책임을 물을 수 없다(중대한 과실로 알지 못한 경우도 같다는 것이 판례).","src":"기출 2025-5"},{"t":"법인은 대표기관의 선임·감독에 과실이 없음을 증명해도 제35조 책임을 면하지 못한다.","src":"기출 2023-5"},{"t":"제35조 책임이 성립하는 경우 법인은 제756조 사용자책임을 지지 않는다.","src":"보충(원문 미확인)"},{"t":"목적범위 외의 행위로 손해를 가한 때에는 그 사항의 의결에 찬성하거나 의결을 집행한 사원·이사·대표자가 연대하여 배상하여야 한다.","src":"민법 제35조"},{"t":"대표자가 법인의 목적 범위 외의 행위로 손해를 가한 경우 대표자는 제750조 불법행위책임을 진다.","src":"기출 2025-5"}]},{"머리":"해산과 청산","줄":[{"t":"해산사유: 존립기간 만료, 목적 달성 또는 달성 불능 기타 정관에 정한 해산사유 발생, 파산, 설립허가 취소. 사단법인은 사원이 없게 되거나 총회의 결의로도 해산한다.","src":"민법 제77조"},{"t":"사단법인의 해산결의: 총사원 4분의 3 이상의 동의가 있어야 한다(정관에 다른 규정이 있으면 그에 따름).","src":"민법 제78조"},{"t":"법인이 채무를 완제하지 못하게 된 때 이사는 지체없이 파산신청을 하여야 한다.","src":"민법 제79조"},{"t":"잔여재산: 정관으로 지정한 자에게 귀속한다. 지정이 없으면 이사·청산인이 주무관청의 허가를 얻어 유사한 목적으로 처분할 수 있고 사단법인은 총회의 결의가 있어야 한다. 처분되지 않은 재산은 국고에 귀속한다.","src":"민법 제80조"},{"t":"해산한 법인(청산법인)은 청산의 목적범위 내에서만 권리가 있고 의무를 부담한다.","src":"민법 제81조"},{"t":"청산인은 파산의 경우를 제하고 이사가 되는 것이 원칙이다. 정관 또는 총회의 결의로 달리 정할 수 있다.","src":"민법 제82조"},{"t":"청산인이 될 자가 없거나 결원으로 손해가 생길 염려가 있는 때 법원은 직권 또는 이해관계인·검사의 청구로 청산인을 선임할 수 있다. 중요한 사유가 있으면 해임할 수 있다.","src":"민법 제83조, 제84조"},{"t":"청산인은 파산의 경우가 아니면 취임 후 3주일 내에 해산 사유·연월일, 청산인의 성명·주소, 대표권 제한을 주사무소 소재지에서 등기하고 주무관청에 신고한다.","src":"민법 제85조, 제86조"},{"t":"청산인의 직무: 현존사무의 종결, 채권의 추심 및 채무의 변제, 잔여재산의 인도.","src":"민법 제87조"},{"t":"채권신고 공고: 취임한 날로부터 2월 내에 3회 이상 공고하고 신고기간은 2월 이상이어야 한다. 알고 있는 채권자에게는 개별 최고하며 청산에서 제외하지 못한다.","src":"민법 제88조, 제89조"},{"t":"채권신고기간 내에는 변제하지 못하나 지연손해배상 의무는 면하지 못한다. 청산 중에도 변제기에 이르지 않은 채권을 변제할 수 있다.","src":"민법 제90조, 제91조"},{"t":"청산 중 재산이 채무를 완제하기에 부족함이 분명하면 청산인은 지체없이 파산선고를 신청하고 공고한다.","src":"민법 제93조"},{"t":"청산이 종결한 때 청산인은 3주간 내에 등기하고 주무관청에 신고한다. 청산종결등기가 되어도 청산사무가 남아 있으면 청산법인은 소멸하지 않는다.","src":"민법 제94조"}]},{"머리":"비법인사단","줄":[{"t":"비법인사단의 사원이 집합체로서 물건을 소유할 때에는 총유로 한다.","src":"민법 제275조"},{"t":"총유물의 관리 및 처분은 사원총회의 결의에 의한다. 각 사원은 정관 기타 규약에 좇아 사용·수익할 수 있다.","src":"민법 제276조"},{"t":"비법인사단이 타인 간의 금전채무를 보증하는 행위는 총유물 그 자체의 관리·처분행위가 아니다.","src":"기출 2022-8, 2024-4, 2025-6"},{"t":"총유재산에 대한 보존행위로서의 소송에도 사원총회의 결의가 필요하고, 구성원 개인은 대표자이거나 총회 결의를 거쳤어도 당사자가 될 수 없다.","src":"기출 2022-8"},{"t":"비법인사단의 대표자가 정관상 대표권 제한을 위반한 경우, 상대방이 제한 사실을 알았거나 알 수 있었던 경우가 아니면 법률행위는 유효하다.","src":"기출 2022-8"},{"t":"대표자는 비법인사단의 업무처리를 포괄적으로 타인에게 위임할 수 없고, 포괄적 수임인의 대행행위는 사단에 효력이 미치지 않는다.","src":"기출 2024-4"},{"t":"임시이사 선임에 관한 제63조는 비법인사단에 유추적용된다. 법원이 선임한 임시이사는 원칙적으로 정식이사와 동일한 권한이 있다.","src":"기출 2021-5, 2024-4"},{"t":"비법인사단의 대표자가 그 직무에 관하여 타인에게 가한 손해는 사단이 배상할 책임이 있다.","src":"기출 2021-5"},{"t":"다른 정함이 없는 한 총회에서는 소집 1주간 전에 통지된 회의 목적사항에 관하여만 결의할 수 있다.","src":"기출 2021-5"},{"t":"비법인사단은 사원이 존재하지 않게 되어도 청산사무가 완료될 때까지 청산 목적범위 내에서 권리의무의 주체이다.","src":"기출 2022-8"},{"t":"소집절차에 하자가 있는 종중총회의 결의도 후에 적법하게 소집된 총회에서 추인하면 처음부터 유효하다.","src":"기출 2022-8"},{"t":"종중을 대표할 권한 없는 자의 소송행위도 후에 총회 결의로 추인하면 행위 시로 소급하여 유효하다.","src":"기출 2025-6"},{"t":"종중총회의 결의방법에 종중규약에 다른 규정이 없으면 종원은 서면으로 결의권을 행사할 수 있다.","src":"기출 2025-6"},{"t":"비법인사단을 당사자로 하는 화해조서의 효력은 그 구성원들에게 미치지 않는다.","src":"기출 2025-6"},{"t":"비법인사단의 대표자가 권한 없이 행한 총유물의 처분행위에는 제126조 표현대리 규정이 준용되지 않는다.","src":"기출 2025-6"}]}],"함정":[{"x":"실종선고의 취소가 있을 때에 실종선고를 직접원인으로 하여 재산을 취득한 자는 선의인 경우에도 그 받은 이익에 이자를 붙여서 반환해야 한다.","o":"선의이면 현존하는 이익의 한도에서 반환한다. 이자 가산은 악의의 경우다.","src":"민법 제29조"},{"x":"제한능력자와 맺은 계약의 상대방은 철회의 의사표시를 법정대리인에게만 하여야 한다.","o":"제한능력자에게도 철회의 의사표시를 할 수 있다.","src":"민법 제16조"},{"x":"비법인사단의 대표자가 행한 타인에 대한 업무의 포괄적 위임과 그에 따른 포괄적 수임인의 대행행위는 비법인사단에 대하여 그 효력이 미친다.","o":"포괄적 위임은 허용되지 않아 효력이 미치지 않는다.","src":"기출 2021-5"},{"x":"법인의 사무는 법원이 검사, 감독한다.","o":"법인의 사무는 주무관청이 검사·감독한다. 법원이 하는 것은 해산·청산이다.","src":"민법 제37조, 제95조"},{"x":"사단법인의 사원들이 정관의 규범적 의미ㆍ내용과 다른 해석을 사원총회의 결의라는 방법으로 표명한 경우, 그 결의에 의한 해석은 그 사단법인의 사원들과 법원을 구속한다.","o":"그 결의에 의한 해석은 법원을 구속하지 않는다.","src":"보충(원문 미확인)"},{"x":"미성년자는 법정대리인의 동의 없이 부동산 경매절차에서 매수인이 될 수 있다.","o":"법정대리인의 동의 없이는 매수인이 될 수 없다.","src":"기출 2022-6"},{"x":"법정대리인이 재산의 범위를 정하여 미성년자에게 처분을 허락한 경우, 법정대리인은 그 재산의 처분에 관하여 미성년자를 대리할 수 없다.","o":"처분을 허락해도 법정대리인의 대리권은 소멸하지 않는다(영업허락과 다르다).","src":"보충(원문 미확인)"},{"x":"미성년자는 법정대리인의 동의가 없으면 타인의 대리인으로서 유효한 법률행위를 할 수 없다.","o":"대리인은 행위능력자임을 요하지 않아 동의 없이도 유효하다.","src":"민법 제117조"},{"x":"성년후견인은 피성년후견인의 재산상 법률행위에 대하여 동의권을 갖는다.","o":"성년후견인에게는 동의권이 없고 대리권·취소권이 있다.","src":"보충(원문 미확인)"},{"x":"비법인사단의 구성원 개인은 그가 사단의 대표자이거나 사원총회의 결의를 거친 경우에는 총유재산의 보존행위를 위한 소송의 당사자가 될 수 있다.","o":"구성원 개인은 당사자가 될 수 없다.","src":"기출 2022-8"},{"x":"태아는 법정대리인을 통하여 수증행위를 할 수 있다.","o":"판례는 태아의 수증행위를 인정하지 않는다.","src":"기출 2023-3"},{"x":"2인 이상이 동일한 위난으로 사망한 경우에는 동시에 사망한 것으로 본다.","o":"동시에 사망한 것으로 추정한다.","src":"민법 제30조"},{"x":"태아의 법적 지위에 관하여 판례는 해제조건설을 따르고 있다.","o":"판례는 정지조건설을 따른다.","src":"기출 2023-3"},{"x":"자연인은 출생신고 시로부터 권리능력을 취득한다.","o":"출생한 때(전부노출) 권리능력을 취득한다.","src":"민법 제3조"},{"x":"법인은 그 대표기관의 선임 및 감독에 과실이 없음을 증명하여 민법 제35조제1항에 기한 불법행위책임을 면할 수 있다.","o":"선임·감독상 무과실을 증명해도 책임을 면하지 못한다.","src":"기출 2023-5"},{"x":"임시총회 소집 요건의 기준인 ‘총사원의 5분의 1 이상’이라는 정족수는 정관으로 늘릴 수 없다.","o":"정관으로 증감할 수 있다.","src":"민법 제70조"},{"x":"미성년자가 법정대리인으로부터 특정한 영업을 허락받은 경우, 그 영업에 관한 법정 대리인의 대리권은 소멸하지 않는다.","o":"그 영업에 관해서는 대리권이 소멸한다.","src":"기출 2024-2"},{"x":"비법인사단이 그 총유재산에 대한 보존행위로서 소송을 하는 경우, 특별한 사정이 없는 한 사원총회의 결의를 요하지 않는다.","o":"사원총회의 결의가 필요하다.","src":"기출 2024-4"},{"x":"사단법인의 사원은 정관에 다른 규정이 없는 한 서면이나 대리인으로 결의권을 행사할 수 없다.","o":"서면이나 대리인으로 결의권을 행사할 수 있다.","src":"민법 제73조"},{"x":"피성년후견인이 속임수로써 법정대리인의 동의가 있는 것으로 믿게 하고 체결한 부동산 매매계약은 제한능력을 이유로 취소할 수 없다.","o":"제17조 제2항은 미성년자·피한정후견인만 해당하여 피성년후견인은 취소할 수 있다.","src":"민법 제17조"},{"x":"감사의 성명과 주소는 설립등기사항이다.","o":"설립등기사항은 이사의 성명·주소이고 감사는 아니다.","src":"민법 제49조"},{"x":"법인의 청산종결등기가 경료되었다면 청산사무가 종료되지 않았더라도 청산법인은 소멸한다.","o":"청산사무가 남아 있으면 청산법인은 소멸하지 않는다.","src":"기출 2025-4"},{"x":"재단법인의 기본재산으로 새롭게 편입하는 행위는 주무관청의 허가가 없어도 유효하다.","o":"주무관청의 허가가 있어야 유효하다.","src":"기출 2025-4"},{"x":"법인과 이사의 이익이 상반되는 사항에 대하여 법원은 이해관계인 또는 검사의 청구로 임시이사를 선임하여야 한다.","o":"이익상반 시에는 특별대리인을 선임한다. 임시이사는 이사의 결원 시 선임한다.","src":"민법 제63조, 제64조"},{"x":"대표자의 행위가 외관상, 객관적으로 직무에 관한 행위로 인정되더라도 그 행위가 법령의 규정에 위배된다면 민법 제35조의 직무에 관한 행위로 볼 수 없다.","o":"법령 위배 여부와 무관하게 외관상 직무행위이면 직무에 관한 행위다.","src":"기출 2025-5"},{"x":"비법인사단의 대표자가 권한 없이 행한 총유물의 처분행위에 대하여는 민법 제126조의 표현대리에 관한 규정이 준용된다.","o":"준용되지 않는다.","src":"기출 2025-6"},{"x":"甲의 이해관계인은 위난이 종료한 때로부터 5년이 경과하지 않으면 실종선고를 청구할 수 없다.","o":"위난 종료 후 1년이 지나면 청구할 수 있다(특별실종).","src":"민법 제27조"},{"x":"甲의 실종선고로 인한 재산상속에 있어서 제1순위의 상속인이 있더라도 제2순위의 상속인은 특별한 사정이 없는 한 법원에 甲의 실종선고를 청구할 수 있다.","o":"선순위 상속인이 있으면 후순위 상속인은 이해관계인이 아니다.","src":"보충(원문 미확인)"},{"x":"법원으로부터 실종선고를 받은 甲이 2026. 3. 1. 생환하였다면 甲에 대한 실종선고는 그때부터 별도의 절차없이 효력을 상실한다.","o":"가정법원의 실종선고 취소가 있어야 효력을 잃는다.","src":"민법 제29조"},{"x":"피성년후견인이 속임수로써 법정대리인의 동의가 있는 것으로 믿게 한 경우, 법정대 리인은 그 행위를 취소할 수 없다.","o":"제17조 제2항은 피성년후견인에 적용되지 않아 취소할 수 있다.","src":"민법 제17조"},{"x":"‘자산에 관한 규정’은 재단법인에는 정관의 필요적 기재사항이지만, 사단법인에는 임의적 기재사항이다.","o":"사단·재단 모두 필요적 기재사항이다.","src":"민법 제40조, 제43조"},{"x":"이사회는 사단법인 및 재단법인에 두어야 하는 필수기관이다.","o":"필수기관은 이사이고 이사회는 민법에 규정이 없다.","src":"민법 제57조"},{"x":"감사는 사단법인에는 임의기관이지만 재단법인에는 필수기관이다.","o":"사단·재단 모두 임의기관이다.","src":"민법 제66조"},{"x":"이사가 없거나 결원이 있는 경우에 이로 인하여 손해가 생길 염려 있는 때에는 법원은 특별대리인을 선임하여야 한다.","o":"임시이사를 선임한다.","src":"민법 제63조"},{"x":"법인과 이사의 이익이 상반하는 경우에는 법원은 임시이사를 선임하여야 한다.","o":"특별대리인을 선임한다.","src":"민법 제64조"}]},"물건":{"묶음":[{"머리":"물건의 개념과 부동산·동산","줄":[{"t":"물건: 유체물 및 전기 기타 관리할 수 있는 자연력.","src":"민법 제98조"},{"t":"관리할 수 있는 자연력(전기 등)은 물건이며 동산이다.","src":"민법 제98조, 제99조, 기출 2021-4, 2024-8"},{"t":"토지 및 그 정착물은 부동산이고, 부동산 이외의 물건은 동산이다.","src":"민법 제99조"},{"t":"가설건축물은 특별한 사정이 없는 한 토지의 정착물로 볼 수 없다.","src":"기출 2025-8"},{"t":"명인방법을 갖춘 수목은 토지와 독립한 부동산으로서 저당권의 객체가 될 수 있다.","src":"보충(원문 미확인)"},{"t":"분묘에 안치된 선조의 유체·유골은 매장·관리·제사·공양의 대상이 되는 유체물로서 제사주재자에게 승계된다.","src":"기출 2022-3"}]},{"머리":"주물과 종물","줄":[{"t":"종물의 요건: 물건의 소유자가 그 물건의 상용에 공하기 위하여 자기 소유인 다른 물건을 이에 부속하게 한 때의 그 부속물.","src":"민법 제100조"},{"t":"종물은 주물의 처분에 따른다.","src":"민법 제100조"},{"t":"종물은 원칙적으로 주물의 소유자 소유에 속하는 물건이어야 한다(타인 소유 물건은 종물이 될 수 없다).","src":"기출 2022-3"},{"t":"주물의 소유자나 이용자의 사용에 공여되더라도 주물 그 자체의 효용과 직접 관계가 없으면 종물이 아니다.","src":"기출 2023-7, 2025-8"},{"t":"종물이 되려면 주된 건물의 경제적 효용을 보조하기 위하여 계속적으로 이바지하는 관계가 있어야 한다.","src":"기출 2023-7"},{"t":"횟집으로 쓸 점포에 거의 붙여 신축한 횟감용 수족관 건물은 그 점포의 종물이다.","src":"기출 2023-7"},{"t":"동산뿐만 아니라 부동산도 종물이 될 수 있다.","src":"보충(원문 미확인)"},{"t":"주물을 처분할 때 당사자는 특약으로 종물을 제외할 수 있고, 종물만을 별도로 처분할 수도 있다.","src":"기출 2021-4, 2024-8, 2025-8"},{"t":"「종물은 주물의 처분에 따른다」는 법리는 주물의 권리관계가 공법상 처분인 경우에도 적용된다.","src":"기출 2022-3"},{"t":"주물에 설정된 저당권의 효력은 원칙적으로 종물에도 미치며, 설정 후의 종물에도 미친다.","src":"기출 2023-7"},{"t":"건물저당권의 효력은 특별한 사정이 없는 한 건물 소유를 위한 토지임차권에도 미친다.","src":"기출 2022-3, 2022-25"}]},{"머리":"천연과실과 법정과실","줄":[{"t":"천연과실: 물건의 용법에 의하여 수취하는 산출물.","src":"민법 제101조"},{"t":"법정과실: 물건의 사용대가로 받는 금전 기타의 물건(임료, 이자 등).","src":"민법 제101조"},{"t":"천연과실은 그 원물로부터 분리하는 때에 이를 수취할 권리자에게 속한다.","src":"민법 제102조"},{"t":"법정과실은 수취할 권리의 존속기간일수의 비율로 취득한다.","src":"민법 제102조"},{"t":"국립공원 입장료는 토지의 사용대가가 아니어서 과실이 아니다.","src":"기출 2024-8"},{"t":"매매계약 후 목적물이 인도되지 않고 대금도 완납되지 않았으면 목적물에서 생긴 과실은 매도인에게 속한다. 대금을 완납했는데 목적물을 인도받지 못한 경우의 과실은 매수인에게 속한다(제587조).","src":"기출 2022-3"}]}],"함정":[{"x":"당사자가 주물을 처분할 때에는 특약으로 종물을 제외할 수 없다.","o":"특약으로 종물을 제외할 수 있다.","src":"기출 2021-4"},{"x":"‘종물은 주물의 처분에 따른다’는 법리는 주물의 권리관계가 공법상 처분인 경우에는 적용되지 않는다.","o":"공법상 처분의 경우에도 적용된다.","src":"기출 2022-3"},{"x":"주물의 소유자가 아닌 다른 사람의 소유에 속하는 물건도 종물이 될 수 있다.","o":"종물은 주물 소유자의 소유여야 한다.","src":"민법 제100조"},{"x":"국립공원의 입장료는 토지의 사용대가로서 과실에 해당한다.","o":"토지의 사용대가가 아니어서 과실이 아니다.","src":"기출 2024-8"},{"x":"주물의 소유자의 사용에 공여되는 물건은 주물 그 자체의 효용과 직접 관계가 없더라도 종물이 된다.","o":"주물 자체의 효용과 직접 관계가 있어야 종물이다.","src":"기출 2025-8"}]},"법률행위(법률행위의 목적·조건과 기한)":{"묶음":[{"머리":"법률행위의 종류","줄":[{"t":"단독행위: 상대방 있는 단독행위(취소, 해제, 추인, 채무면제, 상계 등)와 상대방 없는 단독행위(소유권 포기, 유언, 재단법인 설립행위, 공유지분 포기 등)로 나뉜다.","src":"보충(원문 미확인)"},{"t":"법률행위의 취소는 상대방 있는 단독행위, 동산소유권의 포기는 상대방 없는 단독행위로서 출연행위가 아니다(비출연행위).","src":"보충(원문 미확인)"},{"t":"법인(사단법인)의 설립행위는 정관 작성을 요하는 요식행위이다. 사용대차는 무상계약이다. 저당권설정계약은 피담보채권에 종된 행위이다.","src":"기출 2025-37"},{"t":"대물변제는 계약이므로 단독행위가 아니다. 공유지분의 포기, 무효행위의 추인, 법률행위의 취소, 재단법인 설립행위는 단독행위이다.","src":"기출 2024-1"},{"t":"저당권의 설정은 물권행위이고 준물권행위(채권양도, 채무면제 등)가 아니다. 임대차계약 체결은 채권행위, 사단법인 설립은 요식행위, 소유권 포기는 상대방 없는 단독행위, 채무면제는 상대방 있는 단독행위이다.","src":"기출 2025-3"}]},{"머리":"강행·임의규정과 사실인 관습","줄":[{"t":"법률행위의 당사자가 선량한 풍속 기타 사회질서에 관계없는 규정(임의규정)과 다른 의사를 표시한 때에는 그 의사에 의한다.","src":"민법 제105조"},{"t":"임의규정과 다른 관습이 있는 경우 당사자의 의사가 명확하지 아니한 때에는 그 관습에 의한다.","src":"민법 제106조"},{"t":"계약을 해석할 때는 형식적인 문구에만 얽매이지 않고 당사자 쌍방의 진정한 의사가 무엇인가를 탐구하여야 한다.","src":"기출 2021-14"},{"t":"개업공인중개사의 직접거래를 금지한 공인중개사법 규정은 단속규정이고 사법상 효력까지 부인하는 강행규정이 아니다.","src":"보충(원문 미확인)"},{"t":"부동산등기특별조치법을 위반한 중간생략등기의 합의는 무효가 되지 아니한다.","src":"기출 2021-9"},{"t":"매매에서 목적물과 대금은 계약체결 당시에 구체적으로 특정되어 있을 필요는 없고 사후에 구체적으로 특정할 수 있는 기준이 있으면 충분하다.","src":"기출 2026-9"}]},{"머리":"반사회질서 법률행위(제103조)","줄":[{"t":"선량한 풍속 기타 사회질서에 위반한 사항을 내용으로 하는 법률행위는 무효로 한다.","src":"민법 제103조"},{"t":"반사회적 법률행위인지는 특별한 사정이 없는 한 법률행위를 한 때를 기준으로 판단한다.","src":"기출 2024-7"},{"t":"반사회질서 법률행위에 해당하는 것: 오로지 보험사고를 가장하여 생명보험금을 취득할 목적의 보험계약, 다수의 보험계약을 통해 보험금을 부정 취득할 목적의 보험계약 체결, 행정기관에 진정서를 제출해 상대방을 궁지에 빠뜨린 뒤 취하를 조건으로 거액의 급부를 받기로 한 약정.","src":"보충(원문 미확인)"},{"t":"소송에서의 증언을 조건으로 통상 용인되는 수준을 넘는 대가를 받기로 한 약정, 변호사 아닌 자가 승소를 조건으로 소송물의 일부를 양도받기로 한 약정, 부첩관계 종료를 해제조건으로 한 증여, 과도하게 무거운 위약벌 약정은 반사회적 법률행위로 무효로 보는 것이 기출 구성이다.","src":"기출 2023-8"},{"t":"강제집행을 면할 목적으로 부동산에 허위의 근저당권·저당권설정등기를 한 행위는 반사회적 법률행위가 아니다.","src":"기출 2021-9, 2024-7"},{"t":"양도소득세 면탈 목적으로 소유권이전등기를 일정 기간 후에 넘겨받기로 한 특약, 양도소득세 일부 회피를 위해 실제보다 낮은 매매대금을 기재한 행위, 반사회적 행위로 조성된 비자금을 소극적으로 은닉하기 위한 임치, 부첩관계를 해소하며 희생 배상과 장래 생활대책으로 금전을 지급하기로 한 약정은 반사회질서 행위가 아니다.","src":"보충(원문 미확인)"}]},{"머리":"불공정한 법률행위(제104조)","줄":[{"t":"당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다.","src":"민법 제104조"},{"t":"궁박·경솔·무경험 중 하나만 충족되어도 성립할 수 있다.","src":"기출 2024-7"},{"t":"무경험은 어느 특정영역의 경험부족이 아니라 거래일반에 대한 경험부족을 뜻한다.","src":"기출 2022-1"},{"t":"폭리자(상대방)에게 폭리행위에 대한 악의가 있어야 한다. 악의가 없으면 불공정한 법률행위는 성립하지 않는다.","src":"기출 2023-9"},{"t":"급부와 반대급부 사이의 현저한 불균형 여부는 법률행위(계약) 당시를 기준으로 판단한다(변제기 기준이 아님).","src":"보충(원문 미확인)"},{"t":"법률행위가 현저하게 공정을 잃었더라도 곧 궁박·경솔·무경험으로 인한 것으로 추정되지 않는다.","src":"기출 2021-14"},{"t":"폭리행위 요건의 증명책임은 무효를 주장하는 자에게 있다.","src":"기출 2025-10"},{"t":"대리인에 의한 법률행위에서 궁박 상태는 본인을 기준으로, 경솔·무경험은 대리인을 기준으로 판단한다.","src":"기출 2021-9"},{"t":"불공정한 법률행위로서 무효이면 추인해도 유효가 될 수 없다. 무효행위의 전환(제138조)은 적용될 수 있다.","src":"기출 2023-9"},{"t":"무효인 불공정한 법률행위의 불공정성을 다투지 않기로 하는 부제소 합의도 무효이다.","src":"기출 2022-1"},{"t":"불공정한 법률행위의 무효는 절대적 무효여서 선의의 제3자에게도 대항할 수 있다.","src":"기출 2022-1"},{"t":"부담 없는 증여, 경매(공경매)에는 불공정한 법률행위 규정이 적용되지 않는다.","src":"기출 2021-9, 2023-9, 2025-10"}]},{"머리":"법률행위의 일부무효","줄":[{"t":"법률행위의 일부분이 무효인 때에는 그 전부를 무효로 한다. 다만 그 무효부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다.","src":"민법 제137조"},{"t":"무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 무효를 알았더라면 다른 법률행위를 의욕하였으리라고 인정될 때에는 다른 법률행위로서 효력을 가진다.","src":"민법 제138조"}]},{"머리":"조건","줄":[{"t":"정지조건 있는 법률행위는 조건이 성취한 때로부터 효력이 생긴다. 해제조건 있는 법률행위는 조건이 성취한 때로부터 효력을 잃는다.","src":"민법 제147조"},{"t":"당사자가 조건성취의 효력을 그 성취 전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다.","src":"민법 제147조"},{"t":"조건 있는 법률행위의 당사자는 조건의 성부가 미정한 동안에 조건 성취로 생길 상대방의 이익을 해하지 못한다.","src":"민법 제148조"},{"t":"조건의 성취가 미정한 권리의무는 일반규정에 의하여 처분, 상속, 보존 또는 담보로 할 수 있다.","src":"민법 제149조"},{"t":"조건성취로 불이익을 받을 당사자가 신의성실에 반하여 조건 성취를 방해한 때 상대방은 조건이 성취한 것으로 주장할 수 있다.","src":"민법 제150조"},{"t":"조건성취로 이익을 받을 당사자가 신의성실에 반하여 조건을 성취시킨 때 상대방은 조건이 성취하지 아니한 것으로 주장할 수 있다.","src":"민법 제150조"},{"t":"불법조건: 조건이 선량한 풍속 기타 사회질서에 위반한 것이면 그 조건만이 아니라 법률행위 전부가 무효이다.","src":"민법 제151조"},{"t":"기성조건: 법률행위 당시 이미 성취한 조건이 정지조건이면 조건 없는 법률행위, 해제조건이면 무효.","src":"민법 제151조"},{"t":"불능조건: 법률행위 당시 이미 성취할 수 없는 조건이 해제조건이면 조건 없는 법률행위, 정지조건이면 무효.","src":"민법 제151조"},{"t":"조건은 조건의사와 표시가 필요하며 표시되지 않으면 법률행위의 동기에 불과하다.","src":"기출 2023-15"},{"t":"조건부 법률행위는 조건 성취 시 성립하는 것이 아니라 성립은 되어 있고 효력만 조건 성취에 걸린다.","src":"보충(원문 미확인)"}]},{"머리":"기한","줄":[{"t":"시기 있는 법률행위는 기한이 도래한 때로부터 효력이 생긴다. 종기 있는 법률행위는 기한이 도래한 때로부터 효력을 잃는다.","src":"민법 제152조"},{"t":"기한은 채무자의 이익을 위한 것으로 추정한다.","src":"민법 제153조"},{"t":"기한의 이익은 포기할 수 있으나 상대방의 이익을 해하지 못한다.","src":"민법 제153조"},{"t":"기한의 이익 상실 특약은 유효하다. 조건 있는 권리 규정(제148조, 제149조)은 기한 있는 법률행위에 준용되어 기한 도래가 미정한 권리의무도 처분·담보할 수 있다.","src":"민법 제154조"},{"t":"정지조건부 기한이익 상실 특약: 상실 사유가 발생하면 곧바로 이행기가 도래한다. 기한이익 상실 특약은 특별한 사정이 없는 한 형성권적(채권자의 청구 등 필요) 기한이익 상실 특약으로 추정되고, 정지조건부로 추정되지 않는다.","src":"기출 2021-7, 2023-15"},{"t":"채무자가 담보를 손상·감소·멸실하게 한 때 또는 담보제공의무를 이행하지 아니한 때에는 기한의 이익을 주장하지 못한다(제388조).","src":"기출 2021-7"},{"t":"불확정한 사실의 발생을 이행기로 정한 경우 그 사실의 발생이 불가능하게 된 때에도 기한은 도래한 것으로 본다.","src":"기출 2023-15"}]},{"머리":"기간의 계산","줄":[{"t":"기간 계산 방법은 법령, 재판상 처분, 법률행위에 다른 정함이 없으면 민법의 규정에 의한다.","src":"민법 제155조"},{"t":"시·분·초로 정한 기간은 즉시로부터 기산한다. 일·주·월·연으로 정한 기간은 초일을 산입하지 않는다(오전 0시부터 시작하는 때는 산입).","src":"민법 제156조, 제157조"},{"t":"나이는 출생일을 산입하여 만 나이로 계산하고 연수로 표시한다(1세 미만은 월수로 표시 가능).","src":"민법 제158조"},{"t":"일·주·월·연으로 정한 기간은 기간 말일의 종료로 만료한다. 주·월·연은 역에 의하여 계산하고, 최종 월에 해당일이 없으면 그 월의 말일로 만료한다.","src":"민법 제159조, 제160조"},{"t":"기간의 말일이 토요일 또는 공휴일에 해당한 때에는 기간은 그 익일로 만료한다.","src":"민법 제161조"}]}],"함정":[{"x":"기한이익 상실의 특약은 특별한 사정이 없는 한 정지조건부 기한이익 상실의 특약으로 추정된다.","o":"형성권적 기한이익 상실 특약으로 추정된다.","src":"기출 2021-7, 2023-15"},{"x":"강제집행을 면할 목적으로 부동산에 허위의 근저당설정등기를 한 행위는 사회질서에 위반한 행위로 볼 수 있다.","o":"반사회질서 행위로 보지 않는다.","src":"기출 2021-9"},{"x":"불공정한 법률행위의 무효는 선의의 제3자에게 대항할 수 없다.","o":"절대적 무효여서 선의의 제3자에게도 대항할 수 있다.","src":"기출 2022-1"},{"x":"정지조건이 법률행위 당시 이미 성취한 것인 경우에 그 법률행위는 무효로 한다.","o":"정지조건이 기성이면 조건 없는 법률행위가 된다. 해제조건이 기성이면 무효다.","src":"민법 제151조"},{"x":"법률행위가 대리인에 의해 행해진 경우에 궁박ㆍ경솔ㆍ무경험의 상태는 대리인을 기준으로 판단하여야 한다.","o":"궁박은 본인 기준이고 경솔·무경험은 대리인 기준이다.","src":"기출 2023-9"},{"x":"개업공인중개사가 중개의뢰인과 직접 거래를 하는 행위를 금지하는 「공인중개사법」 제33조 제1항 제6호는 그 위반행위의 사법상 효력까지 부인하는 강행규정이다.","o":"단속규정이어서 사법상 효력은 유효하다.","src":"기출 2024-7"},{"x":"급부와 반대급부 사이에 현저한 불균형이 존재하는지는 특별한 사정이 없는 한 변제기를 기준으로 판단하여야 한다.","o":"법률행위 당시를 기준으로 판단한다.","src":"기출 2025-10"},{"x":"조건이 선량한 풍속 기타 사회질서에 위반한 경우, 그 조건만 무효이고 법률행위는 유효하다.","o":"법률행위 전부가 무효다.","src":"민법 제151조"},{"x":"조건부 법률행위는 조건이 성취되었을 때에 비로소 법률행위가 성립한다.","o":"법률행위는 성립해 있고 효력만 조건 성취에 걸린다.","src":"민법 제147조"},{"x":"기한은 채무자의 이익을 위한 것으로 의제되므로 당사자 사이에 기한이익 상실에 관한 특약을 하여도 그 효력이 없다.","o":"「추정」이므로 반대 특약이 유효하다.","src":"민법 제153조"},{"x":"기한의 도래가 미정한 권리의무는 일반규정에 의하여 처분하거나 담보로 할 수 없다.","o":"제154조에 의해 제148조·제149조가 준용되어 처분·담보가 가능하다.","src":"민법 제154조"},{"x":"매매계약에서 매매목적물과 대금은 반드시 계약체결 당시에 구체적으로 특정되어 있어야 그 효력이 인정된다.","o":"사후에 구체적으로 특정할 수 있는 방법과 기준이 있으면 충분하다.","src":"보충(원문 미확인)"},{"x":"기한이익 상실의 특약은 특별한 사정이 없는 한 정지조건부 기한이익 상실의 특약으로 추정한다.","o":"형성권적 기한이익 상실 특약으로 추정한다.","src":"기출 2023-15"}]},"의사표시":{"묶음":[{"머리":"진의 아닌 의사표시(제107조)","줄":[{"t":"의사표시는 표의자가 진의 아님을 알고 한 것이라도 효력이 있다. 상대방이 진의 아님을 알았거나 알 수 있었을 경우에는 무효로 한다.","src":"민법 제107조"},{"t":"진의 아닌 의사표시의 무효는 선의의 제3자에게 대항하지 못한다.","src":"민법 제107조"},{"t":"진의란 표의자가 진정으로 마음속에서 바라는 사항이 아니라 특정한 내용의 의사표시를 하고자 하는 표의자의 생각이다.","src":"기출 2023-10"},{"t":"당시 상황에서 최선이라고 판단하여 한 의사표시는 진의 아닌 의사표시가 아니다.","src":"보충(원문 미확인)"},{"t":"진의 아닌 의사표시는 상대방과 통정이 없다는 점에서 통정허위표시와 구분되고, 상대방 있는 단독행위에도 적용된다.","src":"기출 2023-10"},{"t":"비진의표시의 무효를 주장하는 자가 상대방의 악의·과실, 비진의 사실을 증명하여야 한다.","src":"기출 2024-10"},{"t":"대리인이 한 의사표시의 진의 여부는 대리인을 기준으로 판단한다. 대리인의 진의가 본인에 대하여 배임적임을 상대방이 알았다면 본인에게 효과가 미치지 않는다.","src":"민법 제116조"}]},{"머리":"통정허위표시(제108조)","줄":[{"t":"상대방과 통정한 허위의 의사표시는 무효로 한다. 무효는 선의의 제3자에게 대항하지 못한다.","src":"민법 제108조"},{"t":"성립요건: 진의와 표시의 불일치에 관하여 표의자와 상대방 사이에 합의가 있어야 한다.","src":"기출 2025-7"},{"t":"제3자는 선의이면 족하고 무과실은 요건이 아니다. 제3자의 악의는 허위표시의 무효를 주장하는 자가 증명한다.","src":"기출 2024-10"},{"t":"악의의 제3자로부터 취득한 전득자가 선의이면 선의의 제3자로 보호된다.","src":"보충(원문 미확인)"},{"t":"제3자에 해당하는 경우: 허위 전세권설정등기에 기해 저당권을 취득한 자, 허위 근저당권의 피담보채권을 가압류한 자, 가장채권을 가압류한 압류권자, 파산관재인(파산채권자 모두가 악의가 아닌 한).","src":"보충(원문 미확인)"},{"t":"제3자에 해당하지 않는 경우: 채권의 가장양도에서의 채무자, 허위 소비대차계약상의 지위를 이전받은 자.","src":"기출 2022-10, 2025-7"},{"t":"통정허위표시를 한 채무자의 법률행위도 채권자취소권의 대상이 되며 요건을 갖추면 무효이다.","src":"기출 2024-10, 2025-7, 2026-10"}]},{"머리":"착오로 인한 의사표시(제109조)","줄":[{"t":"법률행위 내용의 중요부분에 착오가 있으면 취소할 수 있다. 착오가 표의자의 중대한 과실로 인한 때에는 취소하지 못한다.","src":"민법 제109조"},{"t":"착오 취소는 선의의 제3자에게 대항하지 못한다.","src":"민법 제109조"},{"t":"중대한 과실의 증명책임은 취소를 막으려는 상대방에게 있다.","src":"보충(원문 미확인)"},{"t":"상대방이 표의자의 착오를 알고 이를 이용한 경우에는 표의자가 중과실이어도 취소할 수 있다.","src":"기출 2023-12, 2026-10"},{"t":"법률의 착오에도 착오 규정이 적용된다. 현재의 사실뿐 아니라 장래의 불확실한 사실에 관한 착오도 대상이 될 수 있다.","src":"기출 2023-12"},{"t":"동기의 착오는 동기가 상대방에게 표시되어 의사표시의 내용으로 인정되면 취소할 수 있다. 별도의 합의까지는 필요 없다.","src":"보충(원문 미확인)"},{"t":"대리에서 착오 유무는 대리인을 표준으로 결정한다.","src":"민법 제116조"},{"t":"매도인이 계약을 적법하게 해제한 후에도 매수인은 착오를 이유로 계약을 취소할 수 있다.","src":"기출 2023-12"},{"t":"건물과 그 부지를 현상대로 매수하면서 부지 지분이 근소하게 부족한 것은 중요부분의 착오가 아니다.","src":"기출 2021-10"},{"t":"재단법인 설립을 위한 재산 출연의 의사표시도 착오를 이유로 취소할 수 있다.","src":"보충(원문 미확인)"},{"t":"계약당사자 쌍방이 같은 물건을 목적물로 삼았는데 계약서에 착오로 다른 물건을 기재했으면 당사자 의사에 따라 합의한 물건에 계약이 성립한다(오표시 무해).","src":"기출 2021-14"}]},{"머리":"사기·강박에 의한 의사표시(제110조)","줄":[{"t":"사기나 강박에 의한 의사표시는 취소할 수 있다.","src":"민법 제110조"},{"t":"상대방 있는 의사표시에 관하여 제3자가 사기나 강박을 행한 경우 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 취소할 수 있다.","src":"민법 제110조"},{"t":"사기·강박 취소는 선의의 제3자에게 대항하지 못한다. 취소를 제3자에게 주장하려면 제3자의 악의를 취소권자가 증명한다.","src":"민법 제110조"},{"t":"상대방의 대리인의 사기는 제3자의 사기가 아니라 상대방 본인의 사기와 같이 취급되어 상대방의 선의·무과실와 무관하게 취소할 수 있다.","src":"보충(원문 미확인)"},{"t":"기망으로 동기에 착오를 일으킨 표의자는 동기가 표시되지 않았어도 사기를 이유로 취소할 수 있다.","src":"보충(원문 미확인)"},{"t":"착오와 사기 요건을 모두 갖춘 경우 사기 취소와 착오 취소를 선택하여 주장할 수 있다.","src":"보충(원문 미확인)"},{"t":"화해계약이 사기로 체결된 경우 분쟁 사항에 착오가 있어도 사기를 이유로 취소할 수 있다.","src":"기출 2025-35"},{"t":"토지거래허가를 받지 않아 유동적 무효 상태인 계약도 강박을 이유로 허가 신청 전에 취소할 수 있다.","src":"기출 2022-7"},{"t":"제3자의 사기로 계약을 체결한 표의자는 계약을 취소하지 않아도 제3자에게 불법행위로 인한 손해배상을 청구할 수 있다.","src":"기출 2022-7"},{"t":"소송행위에는 사기·강박 취소 규정이 적용되지 않는다.","src":"기출 2021-9"},{"t":"강박행위의 위법성: 해악의 내용이 법질서에 위배된 경우 인정된다. 해악 고지 없이 각서에 서명날인을 강력히 요구한 행위는 강박이 아니다.","src":"기출 2025-2"}]},{"머리":"의사표시의 효력발생","줄":[{"t":"상대방 있는 의사표시는 상대방에게 도달한 때에 효력이 생긴다(도달주의).","src":"민법 제111조"},{"t":"의사표시자가 발송 후 사망하거나 제한능력자가 되어도 효력에 영향이 없다.","src":"민법 제111조"},{"t":"청약의 의사표시도 도달 전에는 철회할 수 있다. 계약해제의 의사표시는 상대방에게 도달한 때 효력이 생긴다.","src":"기출 2022-10, 2022-26, 2026-11"},{"t":"내용증명우편으로 발송되고 반송되지 않은 우편물은 특별한 사정이 없으면 그 무렵 송달된 것으로 본다.","src":"기출 2021-11"},{"t":"의사표시를 받은 상대방이 받은 때 제한능력자이면 의사표시자는 대항할 수 없다. 다만 법정대리인이 도달 사실을 안 후에는 대항할 수 있다.","src":"민법 제112조"},{"t":"표의자가 과실 없이 상대방 또는 상대방의 소재를 알지 못하는 경우 민사소송법의 공시송달 규정에 의하여 송달할 수 있다.","src":"민법 제113조"},{"t":"격지자 간의 계약은 승낙의 통지를 발송한 때에 성립한다(제531조).","src":"기출 2021-11, 2026-24"},{"t":"무권대리인의 상대방이 본인에게 한 추인 여부 확답의 최고는 도달한 때 효력이 생기고, 기간 내 확답이 없으면 추인을 거절한 것으로 본다.","src":"기출 2021-11, 2026-11"}]}],"함정":[{"x":"파산관재인은 통정허위표시의 무효에 대항할 수 있는 선의의 제3자가 될 수 없다.","o":"선의의 제3자가 될 수 있다.","src":"기출 2021-10"},{"x":"건물과 그 부지를 현상대로 매수하는 경우에 부지의 지분이 근소하게 부족하더라도 이를 그 매매계약의 중요부분의 착오로 본다.","o":"중요부분의 착오로 보지 않는다.","src":"기출 2021-10"},{"x":"법률의 착오에는 착오로 인한 의사표시에 관한 규정이 적용되지 않는다.","o":"법률의 착오도 적용될 수 있다.","src":"기출 2021-10"},{"x":"법률행위의 내용으로 표시되지 아니한 의사결정의 동기에 관하여 상대방의 기망행위로 인하여 착오를 일으킨 경우에는 표의자는 그 법률행위를 사기에 의한 의사표시로 취소할 수 없다.","o":"사기를 이유로 취소할 수 있다.","src":"기출 2021-10"},{"x":"무권대리인의 상대방이 본인에게 추인여부의 확답을 최고한 경우, 그 최고는 이를 발한 때 효력이 발생한다.","o":"도달한 때 효력이 발생한다.","src":"민법 제111조"},{"x":"계약당사자 쌍방이 모두 동일한 물건을 계약 목적물로 삼았으나 계약서에는 착오로 다른 물건을 목적물로 기재한 경우에는 계약서에 기재된 물건에 관하여 계약이 성립한다.","o":"당사자가 합의한 물건에 관하여 계약이 성립한다.","src":"기출 2021-14"},{"x":"강박에 의해 체결된 거래계약이 토지거래허가를 받지 않아 유동적 무효상태에 있는 경우, 표의자는 허가 신청 전에 강박을 이유로 그 계약을 취소할 수 없다.","o":"허가 신청 전에도 취소할 수 있다.","src":"기출 2022-7"},{"x":"제3자에 의한 사기로 계약을 체결한 경우, 표의자는 그 계약을 취소하지 않으면 그 제3자에 대하여 불법행위로 인한 손해배상을 청구할 수 없다.","o":"취소하지 않아도 손해배상을 청구할 수 있다.","src":"기출 2022-7"},{"x":"표의자가 상대방의 기망행위로 인해 법률행위 중요부분에 착오를 일으킨 경우, 표의자는 사기를 이유로 그 법률행위를 취소할 수 있을 뿐 착오를 이유로 취소할 수는 없다.","o":"사기와 착오를 선택하여 주장할 수 있다.","src":"기출 2022-7"},{"x":"소송행위가 강박에 의해 이루어진 경우, 표의자는 특별한 사정이 없는 한 강박을 이유로 그 소송행위를 취소할 수 있다.","o":"소송행위에는 취소 규정이 적용되지 않는다.","src":"기출 2022-7"},{"x":"청약의 의사표시는 상대방에게 도달하기 전이라도 이를 철회할 수 없다.","o":"도달 전에는 철회할 수 있다.","src":"민법 제111조"},{"x":"대리행위에서 진의 아닌 의사표시인지 여부는 원칙적으로 본인을 기준으로 판단하여야 한다.","o":"대리인을 기준으로 판단한다.","src":"민법 제116조"},{"x":"통정허위표시의 무효로 대항할 수 없는 제3자는 선의이고 무과실일 것을 요한다.","o":"선의이면 족하고 무과실은 요건이 아니다.","src":"기출 2022-10"},{"x":"채권의 가장양도에 있어서 채무자는 통정허위표시의 제3자에 해당한다.","o":"채무자는 제3자에 해당하지 않는다.","src":"기출 2022-10"},{"x":"진의 아닌 의사표시의 상대방이 그 의사표시가 표의자의 진의 아님을 알았을 경우, 표의자는 그 의사표시를 취소할 수 있다.","o":"취소가 아니라 무효다.","src":"민법 제107조"},{"x":"표의자의 중과실 유무에 관한 주장 및 증명책임은 상대방이 아니라 착오자에게 있다.","o":"상대방에게 있다.","src":"기출 2023-12"},{"x":"당사자들 사이에 동기를 의사표시의 내용으로 삼기로 하는 별도의 합의가 있어야만 동기의 착오를 이유로 의사표시를 취소할 수 있다.","o":"동기가 표시되어 내용으로 인정되면 되고 별도의 합의가 필요한 것은 아니다.","src":"보충(원문 미확인)"},{"x":"착오한 표의자의 중대한 과실 유무에 관한 증명책임은 그 표의자에게 있다.","o":"상대방에게 있다.","src":"기출 2024-9"},{"x":"재단법인 설립을 위하여 서면에 의한 증여로 재산을 출연한 경우, 출연자는 착오를 이유로 출연의 의사표시를 취소할 수 없다.","o":"착오를 이유로 취소할 수 있다.","src":"기출 2024-9"},{"x":"매도인이 매수인의 중도금 지급채무불이행을 이유로 매매계약을 적법하게 해제한 후에는 매수인은 착오를 이유로 그 계약을 취소할 수 없다.","o":"해제 후에도 착오를 이유로 취소할 수 있다.","src":"기출 2024-9"},{"x":"파산관재인은 통정허위표시에서의 제3자에 해당하지 않는다.","o":"파산채권자 모두가 악의가 아닌 한 선의의 제3자에 해당한다.","src":"기출 2024-10"},{"x":"상대방의 대리인의 사기로 의사표시를 한 자는 상대방이 그 사실을 알았거나 알 수 있었을 경우에 한하여 그 의사표시를 취소할 수 있다.","o":"상대방 대리인의 사기는 제3자 사기가 아니어서 상대방의 인식 여부와 무관하게 취소할 수 있다.","src":"기출 2025-2"},{"x":"가장 소비대차계약상의 지위를 이전받은 자는 통정허위표시의 무효에 대항할 수 있는 제3자에 해당한다.","o":"제3자에 해당하지 않는다.","src":"기출 2025-7"},{"x":"채무자의 법률행위가 통정허위표시인 경우에는 채권자취소권의 대상이 될 수 없다.","o":"대상이 될 수 있다.","src":"기출 2024-10, 2026-10"},{"x":"의사표시자가 그 통지를 발송한 후 사망한 경우, 그 의사표시는 효력을 상실한다.","o":"효력에 영향이 없다.","src":"민법 제111조"}]},"대리":{"묶음":[{"머리":"대리의 요건과 효과","줄":[{"t":"대리인이 그 권한 내에서 본인을 위한 것임을 표시한 의사표시는 직접 본인에게 효력이 생긴다(현명주의). 대리인에 대한 제3자의 의사표시에도 준용한다.","src":"민법 제114조"},{"t":"대리인이 본인을 위한 것임을 표시하지 않으면 자기를 위한 것으로 본다. 다만 상대방이 대리인으로서 한 것임을 알았거나 알 수 있었을 때는 본인에게 효력이 생긴다.","src":"민법 제115조"},{"t":"대리행위의 하자(의사의 흠결, 사기, 강박, 악의·과실)는 대리인을 표준으로 결정한다. 강박으로 인한 효력 여부도 대리인을 기준으로 한다.","src":"민법 제116조 제1항"},{"t":"특정한 법률행위를 위임한 경우 대리인이 본인의 지시에 좇아 행위한 때 본인은 자기가 안 사정 또는 과실로 알지 못한 사정에 관하여 대리인의 부지를 주장하지 못한다.","src":"민법 제116조 제2항"},{"t":"대리행위의 하자로 인한 취소권은 원칙적으로 본인에게 귀속된다.","src":"기출 2025-11"},{"t":"대리인은 행위능력자임을 요하지 아니한다. 피한정후견인도 임의대리인이 될 수 있다.","src":"민법 제117조, 기출 2021-12, 2024-13"},{"t":"권한을 정하지 아니한 대리인은 보존행위, 그리고 대리의 목적인 물건이나 권리의 성질을 변하지 아니하는 범위에서 이용 또는 개량하는 행위만 할 수 있다.","src":"민법 제118조"},{"t":"대리인이 수인인 때에는 각자가 본인을 대리한다. 법률 또는 수권행위에 다른 정함이 있으면 그에 따른다.","src":"민법 제119조"},{"t":"자기계약·쌍방대리: 본인의 허락이 없으면 본인을 위하여 자기와 법률행위를 하거나 동일한 법률행위에 관하여 당사자 쌍방을 대리하지 못한다. 채무의 이행은 할 수 있다.","src":"민법 제124조"},{"t":"부동산 입찰에서 1인이 이해관계를 달리하는 2인 이상의 대리인이 되어 한 입찰행위는 원칙적으로 무효이다.","src":"기출 2025-11"},{"t":"불법행위 등 사실행위에는 대리가 적용되지 않는다(법률행위에 대리 적용).","src":"기출 2022-17"},{"t":"본인으로부터 계약체결 대리권을 받은 대리인은 특별한 사정이 없으면 계약을 해제할 수 없다(해제권은 별도의 수권이 필요).","src":"보충(원문 미확인)"},{"t":"계약체결과 이행에 관한 포괄적 대리권을 받은 대리인은 특별한 사정이 없으면 대금 지급기일을 연기해 줄 권한이 있고, 잔금을 수령하면 상대방의 채무는 소멸한다.","src":"기출 2025-12"},{"t":"상대방이 채무불이행을 이유로 계약을 해제하면 원상회복의무는 대리인이 아닌 본인이 부담한다. 대리인은 상대방의 이행지체를 이유로 해제할 수 없다.","src":"기출 2025-12"}]},{"머리":"복대리","줄":[{"t":"임의대리인(수권행위로 대리권 부여)은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다.","src":"민법 제120조"},{"t":"임의대리인이 복대리인을 선임한 때 본인에 대하여 선임감독에 관한 책임이 있다. 본인의 지명에 의한 선임이면 부적임·불성실을 알고 통지나 해임을 태만한 때만 책임이 있다.","src":"민법 제121조"},{"t":"법정대리인은 그 책임으로 복대리인을 선임할 수 있다. 부득이한 사유가 있는 때는 제121조 제1항의 선임감독 책임만 진다.","src":"민법 제122조"},{"t":"복대리인은 그 권한 내에서 본인을 대리한다. 본인이나 제3자에 대하여 대리인과 동일한 권리의무가 있다.","src":"민법 제123조"}]},{"머리":"대리권의 소멸","줄":[{"t":"대리권 소멸사유: 본인의 사망, 대리인의 사망·성년후견의 개시·파산.","src":"민법 제127조"},{"t":"본인의 성년후견 개시는 대리권 소멸사유가 아니다. 대리인이 성년후견개시 심판을 받으면 대리권은 소멸한다.","src":"민법 제127조"},{"t":"법률행위에 의하여 수여된 대리권은 그 원인된 법률관계의 종료로 소멸한다. 법률관계 종료 전에 본인이 수권행위를 철회한 경우에도 소멸한다.","src":"민법 제128조"}]},{"머리":"표현대리","줄":[{"t":"대리권수여의 표시에 의한 표현대리(제125조): 제3자에 대하여 타인에게 대리권을 수여함을 표시한 자는 그 대리권의 범위 내에서 책임이 있다. 제3자가 대리권 없음을 알았거나 알 수 있었을 때는 제외된다.","src":"민법 제125조"},{"t":"사회통념상 대리권을 추단할 수 있는 직함 사용을 본인이 묵인한 경우 대리권 수여의 표시가 있는 것으로 볼 수 있다.","src":"기출 2024-11"},{"t":"제125조의 상대방 과실 여부는 표현대리인의 주관적 사정을 제외하고 계약 성립 당시의 제반사정으로 판단한다.","src":"보충(원문 미확인)"},{"t":"제125조는 임의대리에만 적용되고 법정대리에는 적용되지 않는다. 소송행위에도 적용되지 않는다.","src":"보충(원문 미확인)"},{"t":"권한을 넘은 표현대리(제126조): 대리인이 권한 외의 법률행위를 한 경우 제3자가 권한이 있다고 믿을 만한 정당한 이유가 있는 때 본인이 책임을 진다.","src":"민법 제126조"},{"t":"제126조의 기본대리권이 필요하다. 기본대리권은 표현대리행위와 같은 종류일 필요는 없다.","src":"기출 2021-17"},{"t":"공법상 행위의 대리권, 부부 일상가사대리권, 등기신청 대리권도 기본대리권이 될 수 있다. 사실행위는 기본대리권이 될 수 없다.","src":"기출 2025-13"},{"t":"임의대리인이 사자(使者)를 이용해 권한 외의 법률행위를 한 경우에도 제126조의 기본대리권이 성립한다.","src":"기출 2021-17"},{"t":"제126조는 법정대리에도 적용된다.","src":"기출 2021-17"},{"t":"정당한 이유의 유무는 대리행위 당시를 기준으로 판단하고 그 증명책임은 상대방이 부담한다.","src":"보충(원문 미확인)"},{"t":"대리권소멸 후의 표현대리(제129조): 대리권의 소멸은 선의의 제3자에게 대항하지 못한다. 제3자가 과실로 알지 못한 때는 제외된다.","src":"민법 제129조"},{"t":"제129조는 법정대리에도 적용되고, 대리권 소멸 후 선임된 복대리인과의 행위에도 성립할 수 있다. 소멸 후 권한을 넘는 행위가 있으면 제126조가 중첩 성립할 수 있다.","src":"기출 2021-17"},{"t":"표현대리는 유권대리가 아니라 무권대리의 일종이다.","src":"기출 2022-17"},{"t":"표현대리가 성립하는 경우 상대방에게 과실이 있어도 과실상계 법리를 유추적용하여 본인의 책임을 경감할 수 없다.","src":"기출 2023-13, 2024-11, 2025-13, 2026-13"},{"t":"유권대리 주장에는 표현대리 주장이 당연히 포함되지 않는다. 대리행위가 강행법규 위반으로 무효인 경우에는 표현대리 법리가 적용되지 않는다.","src":"기출 2025-13, 2026-13"}]},{"머리":"무권대리","줄":[{"t":"대리권 없는 자가 타인의 대리인으로 한 계약은 본인이 추인하지 아니하면 본인에 대하여 효력이 없다.","src":"민법 제130조"},{"t":"상대방의 최고권: 상당한 기간을 정하여 본인에게 추인 여부의 확답을 최고할 수 있다. 본인이 기간 내에 확답을 발하지 아니하면 추인을 거절한 것으로 본다.","src":"민법 제131조"},{"t":"추인 또는 거절의 의사표시는 상대방에 대하여 하지 아니하면 상대방에게 대항하지 못한다. 상대방이 그 사실을 안 때는 제외된다.","src":"민법 제132조"},{"t":"추인은 무권대리인 또는 상대방의 동의나 승낙을 요하지 않고, 무권대리행위로 인한 권리·법률관계의 승계인에게도 할 수 있다.","src":"기출 2026-12"},{"t":"추인은 다른 의사표시가 없으면 계약 시에 소급하여 효력이 생기나 제3자의 권리를 해하지 못한다.","src":"민법 제133조"},{"t":"무권대리행위의 일부만 추인하면 상대방의 동의를 얻지 못하는 한 무효이다.","src":"기출 2026-12"},{"t":"본인이 무권대리인으로부터 매매대금의 일부를 받은 경우 특별한 사정이 없으면 추인한 것으로 볼 수 있다.","src":"기출 2026-12"},{"t":"상대방의 철회권: 본인의 추인이 있을 때까지 본인이나 그 대리인에 대하여 철회할 수 있다. 계약 당시 대리권 없음을 안 때에는 철회할 수 없다.","src":"민법 제134조"},{"t":"무권대리인의 책임: 대리권을 증명하지 못하고 본인의 추인을 받지 못한 경우 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다(무과실책임).","src":"민법 제135조 제1항"},{"t":"무권대리인의 책임이 배제되는 경우: 상대방이 대리권 없음을 알았거나 알 수 있었을 때, 또는 무권대리인이 제한능력자일 때.","src":"민법 제135조 제2항"},{"t":"단독행위의 무권대리는 행위 당시 상대방이 대리권 없는 행위에 동의하거나 대리권을 다투지 아니한 때에 한하여 제130조 이하를 준용한다.","src":"민법 제136조"}]}],"함정":[{"x":"대리인이 수인인 경우에는 대리인은 공동으로 본인을 대리하는 것이 원칙이다.","o":"각자가 본인을 대리하는 것이 원칙이다.","src":"민법 제119조"},{"x":"임의대리인이 사자(使者)를 이용해서 대리인의 권한 외의 법률행위를 한 경우에는 제126조의 기본대리권이 성립하지 않는다.","o":"기본대리권이 성립한다.","src":"기출 2021-17"},{"x":"제126조의 표현대리에서의 기본대리권은 표현대리행위와 같은 종류 내지는 유사한 것이어야 한다.","o":"같은 종류·유사할 필요가 없다.","src":"기출 2021-17"},{"x":"소송행위에도 제125조의 표현대리의 규정이 적용된다.","o":"소송행위에는 적용되지 않는다.","src":"기출 2021-17"},{"x":"공법상의 대리권은 제126조의 기본대리권이 될 수 없다.","o":"기본대리권이 될 수 있다.","src":"기출 2021-17"},{"x":"대리인이 대리권을 수여 받은 후 성년후견개시의 심판을 받더라도 대리권은 소멸하지 않는다.","o":"대리인이 성년후견개시 심판을 받으면 대리권이 소멸한다.","src":"민법 제127조"},{"x":"불법행위에 대하여도 대리가 적용될 수 있다.","o":"불법행위에는 대리가 적용되지 않는다.","src":"기출 2022-17"},{"x":"임의대리인은 자신의 권한의 범위 내에서 임의로 복대리인을 선임할 수 있다.","o":"본인의 승낙이 있거나 부득이한 사유가 있어야 한다.","src":"민법 제120조"},{"x":"본인이 무권대리행위의 상대방에 대하여 추인의 의사표시를 한 경우 특별한 사정이 없는 한 대리행위는 장래를 향하여 효력이 생긴다.","o":"계약 시에 소급하여 효력이 생긴다.","src":"민법 제133조"},{"x":"표현대리는 유권대리의 일종으로 보아야 한다.","o":"무권대리의 일종이다.","src":"기출 2022-17"},{"x":"유권대리에 관한 주장 속에는 표현대리의 주장이 포함된 것으로 볼 수 있다.","o":"포함되지 않는다.","src":"기출 2023-13"},{"x":"대리권 수여의 표시에 의한 표현대리는 임의대리뿐만 아니라 법정대리에도 적용된다.","o":"임의대리에만 적용된다.","src":"기출 2023-13"},{"x":"권한을 넘은 표현대리는 사실행위를 기본대리권으로 하여서도 성립한다.","o":"사실행위는 기본대리권이 될 수 없다.","src":"기출 2023-13"},{"x":"대리권 소멸 후 표현대리가 성립하는 경우, 그 표현대리의 권한을 넘은 대리행위가 있더라도 권한을 넘은 표현대리는 성립할 수 없다.","o":"권한을 넘은 표현대리가 성립할 수 있다.","src":"기출 2023-13"},{"x":"‘대리권 소멸 후의 표현대리’는 법정대리에 적용되지 않는다.","o":"법정대리에도 적용된다.","src":"기출 2024-11"},{"x":"법정대리인은 부득이한 사유 없이 복대리인을 선임할 수 없다.","o":"법정대리인은 자기 책임으로 언제든 복대리인을 선임할 수 있다.","src":"민법 제122조"},{"x":"丙이 乙과 계약을 체결할 당시에 대리권이 없음을 알았더라도 丙은 그 계약을 철회할 수 있다.","o":"대리권 없음을 안 상대방은 철회할 수 없다.","src":"민법 제134조"},{"x":"丙이 甲에게 상당한 기간을 정하여 계약의 추인 여부에 관한 확답을 최고한 경우, 甲이 그 기간 내에 확답을 발송하지 않으면 추인한 것으로 본다.","o":"추인을 거절한 것으로 본다.","src":"민법 제131조"},{"x":"본인은 임의대리권의 원인된 법률관계가 종료하기 전에는 수권행위를 철회하여 대리권을 소멸시킬 수 없다.","o":"법률관계 종료 전에도 수권행위를 철회하여 소멸시킬 수 있다.","src":"민법 제128조"},{"x":"丙이 채무불이행을 이유로 매매계약을 적법하게 해제한 경우, 乙은 丙에게 원상회복 의무를 부담한다.","o":"본인 甲이 원상회복 의무를 부담한다.","src":"기출 2025-12"},{"x":"표현대리가 성립하여 본인이 이행책임을 부담하는 경우, 상대방에게 과실이 있으면 과실상계의 법리가 적용된다.","o":"과실상계 법리를 유추적용할 수 없다.","src":"기출 2025-13"},{"x":"본인이 매매계약을 체결한 무권대리인으로부터 매매대금의 일부를 받은 경우, 특별한 사정이 없는 한 무권대리인의 매매계약을 추인한 것으로 볼 수 없다.","o":"추인한 것으로 볼 수 있다.","src":"기출 2026-12"},{"x":"대리권 수여의 표시에 의한 표현대리에 있어서 상대방의 과실이 있는지 여부는 표현대리인의 주관적 사정을 포함하여 계약 성립 당시의 제반사정을 종합적으로 고려하여 판단하여야 한다.","o":"표현대리인의 주관적 사정은 제외하고 판단한다.","src":"기출 2026-13"}]},"무효와 취소":{"묶음":[{"머리":"무효","줄":[{"t":"법률행위의 일부분이 무효인 때에는 그 전부를 무효로 하는 것이 원칙이다. 무효 부분이 없더라도 법률행위를 하였을 것이라고 인정될 때는 나머지 부분은 유효하다.","src":"민법 제137조"},{"t":"무효행위의 전환: 무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았다면 다른 법률행위를 의욕하였으리라고 인정될 때 다른 법률행위로서 효력을 가진다. 불공정한 법률행위에도 적용될 수 있다.","src":"민법 제138조, 기출 2023-9"},{"t":"무효인 법률행위는 추인하여도 효력이 생기지 않는다. 당사자가 무효임을 알고 추인한 때는 새로운 법률행위로 본다.","src":"민법 제139조"},{"t":"사회질서에 반하는 무효 행위, 불공정한 법률행위는 추인으로 유효가 될 수 없다.","src":"기출 2021-15"},{"t":"무효인 가등기를 유효한 등기로 전용하기로 약정해도 그 가등기가 소급하여 유효한 등기로 되지는 않는다.","src":"보충(원문 미확인)"},{"t":"무효인 법률행위에 따른 효과를 침해하는 것처럼 보이는 채무불이행이 있어도 그 손해배상을 청구할 수 없다.","src":"기출 2026-14"},{"t":"농지취득자격증명 없이 체결한 농지매매계약은 무효가 아니다(소유권이전등기 신청에 필요한 요건일 뿐 매매의 효력 요건이 아님).","src":"보충(원문 미확인)"},{"t":"법률행위의 취소를 당연한 전제로 한 소송상 이행청구에는 취소의 의사표시가 포함되어 있다고 볼 수 있다.","src":"기출 2026-14"},{"t":"토지거래허가구역 안의 토지 매매계약이 확정적으로 무효가 되면 누구나(과실 있는 자도) 그 무효를 주장할 수 있다.","src":"기출 2021-15"},{"t":"토지거래허가 전(유동적 무효): 채무불이행을 이유로 한 손해배상 청구 불가, 허가조건부 소유권이전등기 청구 불가. 허가 전에도 민법 제565조 해약금 규정에 의한 계약 해제는 가능하다. 허가를 배제하는 내용의 계약은 허가구역 지정이 해제되어도 유효로 되지 않는다.","src":"보충(원문 미확인)"}]},{"머리":"취소","줄":[{"t":"취소권자: 제한능력자, 착오로 인하거나 사기·강박에 의하여 의사표시를 한 자, 그의 대리인 또는 승계인.","src":"민법 제140조"},{"t":"취소된 법률행위는 처음부터 무효인 것으로 본다. 제한능력자는 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환할 책임이 있다(선의·악의 불문).","src":"민법 제141조"},{"t":"근로계약처럼 계속적 계약을 취소한 경우 그 효력이 계약 시로 소급하지 않는다는 것이 판례다.","src":"보충(원문 미확인)"},{"t":"취소의 상대방이 확정한 경우에는 그 상대방에 대한 의사표시로 하여야 한다.","src":"민법 제142조"},{"t":"추인: 취소할 수 있는 법률행위는 취소권자가 추인할 수 있고 추인 후에는 취소하지 못한다.","src":"민법 제143조"},{"t":"추인은 취소의 원인이 소멸된 후에 하여야 효력이 있다. 법정대리인 또는 후견인이 추인하는 경우는 예외다. 제한능력자는 능력자가 된 후에 추인한다.","src":"민법 제144조"},{"t":"유효하게 취소된 후에는 추인으로 확정적으로 유효하게 할 수 없다. 유효하게 추인된 후에는 다시 취소할 수 없다.","src":"보충(원문 미확인)"},{"t":"법정추인 사유(추인할 수 있는 후에 있어야 함, 이의를 보류하면 제외): 전부나 일부의 이행, 이행의 청구, 경개, 담보의 제공, 취소할 수 있는 행위로 취득한 권리의 전부나 일부의 양도, 강제집행.","src":"민법 제145조"},{"t":"이행의 청구는 취소권자가 상대방에게 청구하는 경우만 법정추인이다. 취소권자의 상대방이 이행을 청구한 경우에는 법정추인이 되지 않는다.","src":"기출 2021-15"},{"t":"취소권은 추인할 수 있는 날로부터 3년 내에, 법률행위를 한 날로부터 10년 내에 행사하여야 한다(제척기간).","src":"민법 제146조"}]}],"함정":[{"x":"토지거래허가구역 내의 토지에 관한 매매계약이 확정적으로 무효가 되면 과실이 있는 사람은 그 계약의 무효를 주장할 수 없다.","o":"누구든 무효를 주장할 수 있다.","src":"기출 2021-15"},{"x":"법률행위의 일부분이 무효인 때에는 원칙적으로 그 일부만을 무효로 한다.","o":"원칙은 전부 무효이다.","src":"민법 제137조"},{"x":"취소된 법률행위는 취소된 때로부터 무효인 것으로 본다.","o":"처음부터 무효인 것으로 본다.","src":"민법 제141조"},{"x":"제한능력자는 제한능력의 상태에서도 법률행위를 추인할 수 있다.","o":"능력자가 된 후(취소 원인이 소멸한 후)에 추인한다.","src":"민법 제144조"},{"x":"제한능력자는 유효하게 추인된 법률행위를 다시 취소할 수 있다.","o":"추인 후에는 취소하지 못한다.","src":"민법 제143조"},{"x":"강박에 의한 의사표시가 유효하게 취소된 후에도 취소할 수 있는 법률행위의 추인에 의하여 다시 확정적으로 유효하게 할 수 있다.","o":"취소된 행위는 처음부터 무효여서 추인으로 유효하게 할 수 없다.","src":"민법 제141조"}]},"소멸시효":{"묶음":[{"머리":"소멸시효의 기간","줄":[{"t":"채권은 10년, 채권 및 소유권 이외의 재산권은 20년간 행사하지 않으면 소멸시효가 완성한다.","src":"민법 제162조"},{"t":"3년 시효 채권: 1년 이내 기간으로 정한 금전·물건 지급채권(이자, 부양료, 급료, 사용료), 의사·조산사·간호사·약사의 치료·근로·조제 채권, 도급받은 자·기사·설계감독자의 공사 채권, 변호사·변리사·공증인·공인회계사·법무사의 직무상 보관서류 반환청구 채권, 그 직무에 관한 채권, 생산자·상인이 판매한 생산물·상품의 대가, 수공업자·제조자의 업무 채권.","src":"민법 제163조"},{"t":"1년 시효 채권: 여관·음식점·대석·오락장의 숙박료, 음식료, 대석료, 입장료, 소비물의 대가 및 체당금 채권, 의복·침구·장구 기타 동산의 사용료 채권, 노역인·연예인의 임금 및 공급한 물건의 대금 채권, 학생·수업자의 교육·의식·유숙에 관한 교주·숙주·교사의 채권.","src":"민법 제164조"},{"t":"수급인의 공사대금 채권은 3년이다(상거래 5년이 아님). 부동산공사 수급인의 제666조 저당권설정청구권도 3년 단기시효에 걸린다.","src":"보충(원문 미확인)"},{"t":"세무사의 직무 채권, 숙박료·음식료로 구성된 월 단위 리조트 사용료 채권은 3년 시효 대상으로 보지 않고, 의복 사용료 채권·오락장 입장료 채권은 1년이다.","src":"보충(원문 미확인)"},{"t":"판결에 의하여 확정된 채권은 단기시효에 해당하는 것이라도 10년이다. 파산절차·재판상 화해·조정 등으로 확정된 채권도 같다. 판결 확정 당시 변제기가 도래하지 않은 채권에는 적용하지 않는다.","src":"민법 제165조"}]},{"머리":"기산점과 소급효","줄":[{"t":"소멸시효는 권리를 행사할 수 있는 때로부터 진행한다. 부작위를 목적으로 하는 채권은 위반행위를 한 때부터 진행한다.","src":"민법 제166조"},{"t":"권리자가 주관적 사정으로 권리의 존재를 알지 못한 경우에도 시효는 진행한다.","src":"기출 2023-16"},{"t":"동시이행항변권이 붙어 있는 채권도 약정한 이행기부터 시효가 진행한다.","src":"기출 2025-16"},{"t":"불확정기한은 기한이 객관적으로 도래한 때부터 진행한다(안 때부터가 아님).","src":"보충(원문 미확인)"},{"t":"정지조건부 권리는 조건 미성취 동안 시효가 진행하지 않는다.","src":"기출 2026-17"},{"t":"부당이득반환청구권은 성립한 때부터 진행한다. 위임사무로 수임인 명의로 취득한 권리의 이전청구권은 위임계약이 종료된 때부터 진행한다.","src":"기출 2026-17"},{"t":"소멸시효는 그 기산일에 소급하여 효력이 생긴다.","src":"민법 제167조"},{"t":"실제 기산일과 당사자가 주장하는 기산일이 다르면 법원은 당사자가 주장하는 기산일을 기준으로 계산한다.","src":"기출 2025-16"},{"t":"공유물분할청구권은 공유관계가 존속하는 한 독립하여 소멸시효에 걸리지 않는다. 점유취득시효 완성으로 인한 소유권이전등기청구권도 점유가 계속되는 한 소멸하지 않는다.","src":"기출 2021-19, 2022-11, 2023-16, 2025-16"}]},{"머리":"시효의 중단","줄":[{"t":"중단사유: 청구, 압류·가압류·가처분, 승인.","src":"민법 제168조"},{"t":"시효의 중단은 당사자 및 그 승계인 간에만 효력이 있다(주채무자에 대한 중단은 보증인에게도 효력이 있다).","src":"민법 제169조, 기출 2024-23, 2026-16"},{"t":"재판상의 청구는 소송의 각하, 기각 또는 취하의 경우 시효중단의 효력이 없다. 6월 내에 재판상 청구, 파산절차참가, 압류·가압류·가처분을 한 때에는 최초의 재판상 청구로 중단된 것으로 본다.","src":"민법 제170조"},{"t":"파산절차참가는 채권자가 이를 취소하거나 청구가 각하된 때 중단의 효력이 없다.","src":"민법 제171조"},{"t":"지급명령은 채권자가 법정기간 내에 가집행신청을 하지 아니하여 효력을 잃은 때 중단의 효력이 없다.","src":"민법 제172조"},{"t":"화해를 위한 소환은 상대방이 출석하지 않거나 화해가 성립되지 않은 때 1월 내에 소를 제기하지 않으면 중단의 효력이 없다. 임의출석의 경우도 같다.","src":"민법 제173조"},{"t":"최고는 6월 내에 재판상 청구, 파산절차참가, 화해를 위한 소환, 임의출석, 압류·가압류·가처분을 하지 않으면 시효중단의 효력이 없다.","src":"민법 제174조"},{"t":"압류·가압류·가처분은 권리자의 청구 또는 법률 규정에 따르지 않아 취소된 때 중단의 효력이 없다. 시효이익을 받는 자에게 하지 않은 때는 그에게 통지한 후가 아니면 효력이 없다.","src":"민법 제175조, 제176조"},{"t":"승인에는 상대방의 권리에 관한 처분의 능력이나 권한 있음을 요하지 않는다.","src":"민법 제177조"},{"t":"시효가 중단되면 중단까지 경과한 시효기간은 산입하지 않고 중단사유가 종료한 때부터 새로 진행한다. 재판상 청구로 중단된 시효는 재판이 확정된 때부터 새로 진행한다.","src":"민법 제178조"},{"t":"채무자가 담보를 제공하는 것은 채무승인으로 시효가 중단된다. 타인이 실행한 경매절차에서 채권자가 배당을 요구하면 중단된다.","src":"보충(원문 미확인)"},{"t":"임차권등기명령에 따른 임차권등기, 이행청구의 소가 기각된 후 6개월간 아무 조치 없이 경과한 경우, 성년후견 개시심판, 피해자의 고소에 기초한 형사소송은 중단사유가 아니다.","src":"보충(원문 미확인)"},{"t":"지급명령에 의한 중단 효력은 이의신청으로 소송으로 이행되면 지급명령 신청 시에 발생한다. 가압류의 중단 효력은 가압류 신청 시로 소급한다.","src":"기출 2026-16"},{"t":"가압류에 의한 시효중단 효력은 본안 승소판결이 확정되어도 본안판결에 흡수되어 소멸하지 않고, 가압류 집행보전의 효력이 지속되는 동안 유지된다.","src":"기출 2022-12"},{"t":"채권자가 최고 후 6개월 내에 채무자가 채무를 승인하면 최고의 중단 효력이 발생한다.","src":"기출 2026-16"},{"t":"시효완성 전에 채무 일부를 변제하고 액수에 다툼이 없으면 채무승인으로서 중단 효력이 있다. 현존하지 않는 장래의 채권을 미리 승인해도 중단되지 않는다.","src":"기출 2021-13"},{"t":"피고로서 응소하여 적극적으로 권리를 주장해 받아들여지면 응소 시에 재판상 청구로서 중단 효력이 있다(원고의 소 제기 시로 소급하지 않는다). 물상보증인이 제기한 저당권말소등기 소송에서 채권자가 피담보채권 존재를 주장하며 응소한 것은 중단사유가 아니다.","src":"기출 2021-13"}]},{"머리":"시효의 정지","줄":[{"t":"제한능력자에게 법정대리인이 없는 경우, 시효 만료 전 6개월 내에 그가 능력자가 되거나 법정대리인이 취임한 때부터 6개월 내에는 시효가 완성되지 않는다.","src":"민법 제179조"},{"t":"재산을 관리하는 부모·후견인에 대한 제한능력자의 권리는 능력자가 되거나 후임 법정대리인이 취임한 때부터 6개월 내에 시효가 완성되지 않는다. 부부 중 한쪽의 다른 쪽에 대한 권리는 혼인관계가 종료된 때부터 6개월 내에 시효가 완성되지 않는다.","src":"민법 제180조"},{"t":"상속재산에 속한 권리나 상속재산에 대한 권리는 상속인의 확정, 관리인의 선임 또는 파산선고가 있는 때로부터 6월 내에 시효가 완성되지 않는다.","src":"민법 제181조"},{"t":"천재 기타 사변으로 시효를 중단할 수 없을 때에는 사유 종료 후 1월 내에 시효가 완성되지 않는다.","src":"민법 제182조"}]},{"머리":"소멸시효의 효과","줄":[{"t":"주된 권리의 소멸시효가 완성한 때에는 종속된 권리에도 그 효력이 미친다.","src":"민법 제183조"},{"t":"소멸시효 이익은 미리 포기하지 못한다. 시효 완성 후에는 포기할 수 있고 포기한 때부터 시효가 새로 진행한다.","src":"민법 제184조 제1항"},{"t":"소멸시효는 법률행위로 배제·연장·가중할 수 없으나 단축 또는 경감할 수 있다. 이행 청구 가능 기간을 제한하고 도과하면 채무가 소멸하는 약정은 시효 단축으로 유효하다.","src":"민법 제184조 제2항"},{"t":"본래 채권이 시효로 소멸하면 그 이행불능을 이유로 한 손해배상청구권도 허용되지 않는다.","src":"보충(원문 미확인)"},{"t":"법원은 당사자가 민법 시효기간을 주장하더라도 직권으로 상법상 시효기간을 적용할 수 있다. 소멸시효의 이익은 당사자가 원용하여야 하고 법원이 직권으로 고려하지 않는다.","src":"기출 2023-16"},{"t":"제척기간: 중단이 인정되지 않고 법원이 직권으로 조사하며, 하자담보 손해배상청구권에는 제척기간과 소멸시효가 모두 적용된다.","src":"기출 2022-12"}]}],"함정":[{"x":"원고가 제기한 소에 피고가 응소하여 적극적으로 시효중단을 주장하여 받아들여지면 원고가 소를 제기한 때에 재판상 청구로서의 효력이 발생한다.","o":"피고가 응소한 때에 재판상 청구의 효력이 발생한다.","src":"기출 2021-13"},{"x":"가압류로 인한 시효중단의 시점은 가압류의 명령이 채무자에게 고지된 때이다.","o":"가압류 신청 시로 소급한다.","src":"기출 2022-11"},{"x":"제척기간은 그 성질에 비추어 기간의 중단이 인정된다.","o":"제척기간에는 중단이 없다.","src":"기출 2022-12"},{"x":"소멸시효는 당사자의 약정으로 그 기간을 연장할 수 있다.","o":"연장은 불가하고 단축·경감만 가능하다.","src":"민법 제184조"},{"x":"법원은 제척기간 경과에 대하여 당사자의 주장이 있는 경우에만 이를 원용할 수 있다.","o":"제척기간은 직권조사 사항이다.","src":"기출 2022-12"},{"x":"가압류의 피보전채권에 관하여 본안의 승소판결이 확정된 경우 가압류에 의한 시효중단의 효력은 본안판결에 흡수되어 소멸한다.","o":"흡수되지 않고 가압류 집행보전 효력이 지속되는 동안 유지된다.","src":"기출 2022-12"},{"x":"변제기가 불확정기한인 경우에는 그 기한이 도래한 사실을 안 때로부터 소멸시효가 진행한다.","o":"기한이 객관적으로 도래한 때부터 진행한다.","src":"기출 2023-16"},{"x":"시효중단의 효력이 있는 승인에는 상대방의 권리에 관한 처분능력이 있음을 요한다.","o":"처분의 능력이나 권한이 필요 없다.","src":"민법 제177조"},{"x":"아직 현존하지 아니하는 장래의 채권에 대하여 채무자가 그 채무를 미리 승인하는 것은 소멸시효의 중단사유로서 허용된다.","o":"중단되지 않는다.","src":"기출 2024-23"},{"x":"수급인인 건설회사의 도급인에 대한 공사대금채권은 상거래에 관한 것으로 5년의 단기소멸시효에 걸린다.","o":"3년 단기시효에 걸린다.","src":"민법 제163조"},{"x":"물상보증인이 채권자에 대하여 피담보채무의 소멸을 이유로 제기한 저당권설정등기 말소청구의 소에서 그 피담보채권의 존재를 주장하며 응소한 채권자의 행위는 시효중단사유이다.","o":"시효중단사유가 아니다.","src":"기출 2026-16"},{"x":"임치인의 임치계약 해지에 따른 임치물 반환청구권의 소멸시효는 특별한 사정이 없는 한 임치계약을 해지한 때부터 진행한다.","o":"출제 오답(바른 기산점 미확인).","src":"기출 2026-17"}]},"물권법 총칙과 물권의 변동(등기·점유·물권적 청구권)":{"묶음":[{"머리":"물권의 객체와 종류","줄":[{"t":"물권은 법률 또는 관습법에 의하는 외에는 임의로 창설하지 못한다(물권법정주의).","src":"민법 제185조"},{"t":"물건 이외에 권리도 물권(권리질권 등)의 객체가 될 수 있다.","src":"기출 2022-20"},{"t":"한 필의 토지 일부에도 점유취득시효가 인정된다. 용익물권은 한 동의 건물 일부에 설정할 수 있다.","src":"기출 2022-20"},{"t":"토지소유권의 범위는 현실의 경계와 상관없이 지적공부상의 경계를 기준으로 확정하는 것이 원칙이다.","src":"기출 2022-20"},{"t":"종류·장소·수량 지정의 방법으로 특정할 수 있으면 집합물 전체에 하나의 담보권을 설정할 수 있다.","src":"기출 2022-20"}]},{"머리":"부동산 물권변동","줄":[{"t":"부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 효력이 생긴다(성립요건주의).","src":"민법 제186조"},{"t":"상속, 공용징수, 판결, 경매 기타 법률 규정에 의한 부동산 물권 취득은 등기를 요하지 않으나, 등기를 하지 않으면 처분하지 못한다.","src":"민법 제187조"},{"t":"교환계약에 의한 소유권 취득은 등기하여야 효력이 생긴다. 상속에 의한 소유권 취득은 등기가 필요 없다.","src":"기출 2021-19"},{"t":"경매에 의한 물권변동 시기는 매수인이 매각대금을 완납한 때이다(등기한 때가 아님).","src":"기출 2021-19"},{"t":"등기 없이 부동산 물권을 취득하는 경우: 관습상 법정지상권 취득, 공유물 분할 판결(형성판결) 확정. 소유권이전등기절차 이행판결 확정이나 소유권 확인 승소판결 확정만으로는 취득하지 못한다.","src":"기출 2022-21"},{"t":"미등기건물의 매수인은 등기를 하지 않는 한 불법점유자에게 직접 소유권에 기한 물권적 청구권을 행사할 수 없다.","src":"기출 2021-19, 2026-18"},{"t":"원시취득에 해당하는 것은 건물의 신축에 의한 소유권 취득이다. 증여, 매매, 상속, 포괄유증은 승계취득이다.","src":"기출 2026-8"},{"t":"점유취득시효 완성으로 인한 소유권이전등기청구권은 점유가 계속되는 한 시효로 소멸하지 않는다.","src":"기출 2021-19"},{"t":"등기의 추정력: 등기가 있으면 원인과 절차가 적법하게 경료된 것으로 추정되고 다투는 측이 무효사유를 증명하여야 한다. 원인 없이 말소된 등기의 최종명의인도 적법한 권리자로 추정된다.","src":"기출 2026-21"},{"t":"소유권보존등기 명의인이 양수 사실을 주장하는데 전 소유자가 양도 사실을 부인하면 보존등기의 추정력은 깨어진다. 점유취득시효 완성에 따른 이전등기 후 제3자가 취득시효기간 일부 동안 토지 일부를 점유한 사실만으로는 추정력이 깨어지지 않는다.","src":"기출 2026-21"}]},{"머리":"중간생략등기","줄":[{"t":"3자 간 중간생략등기 합의가 있으면 최종 매수인(丙)은 최초 매도인(甲)에게 직접 소유권이전등기를 청구할 수 있다. 중간 매수인(乙)의 甲에 대한 소유권이전등기청구권은 소멸하지 않는다.","src":"기출 2023-18, 2025-18"},{"t":"중간생략등기 합의는 효력규정 위반으로 무효가 되지 않는다(부동산등기특별조치법 위반이어도 사법상 유효).","src":"기출 2025-18, 2021-9"},{"t":"합의 후 甲과 乙이 매매대금을 인상하기로 약정한 경우 甲은 인상된 대금이 지급되지 않았음을 이유로 丙의 청구를 거절(동시이행)할 수 있다.","src":"기출 2023-18, 2025-18"},{"t":"합의가 없는 경우, 乙의 이전등기청구권을 양도받은 丙이 甲에게 대항하려면 甲의 동의가 있어야 한다. 동의가 없으면 채권양도를 원인으로 한 소유권이전등기를 청구할 수 없다.","src":"기출 2023-18, 2025-18"},{"t":"토지거래허가구역 토지에서는 丙이 중간생략등기 합의를 이유로 甲에게 직접 허가신청절차 협력을 구할 수 없다.","src":"기출 2023-18"}]},{"머리":"동산 물권변동","줄":[{"t":"동산에 관한 물권의 양도는 동산을 인도하여야 효력이 생긴다. 양수인이 이미 점유한 때는 당사자의 의사표시만으로 효력이 생긴다(간이인도).","src":"민법 제188조"},{"t":"점유개정: 양도인이 계약으로 점유를 계속하면 양수인이 인도받은 것으로 본다.","src":"민법 제189조"},{"t":"반환청구권 양도: 제3자가 점유하는 동산은 양도인이 그 제3자에 대한 반환청구권을 양수인에게 양도함으로써 인도한 것으로 본다.","src":"민법 제190조"},{"t":"혼동: 동일한 물건에 대한 소유권과 다른 물권이 동일인에게 귀속하면 다른 물권은 소멸한다. 그 물권이 제3자의 권리의 목적이면 소멸하지 않는다. 점유권에는 적용하지 않는다.","src":"민법 제191조"},{"t":"소유권유보부 매매(대금 완납 시까지 소유권을 매도인에게 유보하고 동산을 미리 인도): 물권적 합의는 매매계약 체결과 인도 때 성립하나 대금 완납을 정지조건으로 하고, 대금 완납 전에는 매수인이 인도받았어도 소유권은 매도인에게 있으며, 매도인은 제3자에게도 유보된 소유권을 주장할 수 있다.","src":"기출 2021-28"}]},{"머리":"점유권","줄":[{"t":"물건을 사실상 지배하는 자는 점유권이 있다. 사실상의 지배를 상실하면 점유권이 소멸하나, 점유회수(제204조)로 회수한 때는 그렇지 않다.","src":"민법 제192조"},{"t":"점유권은 상속인에 이전한다. 점유권의 양도는 점유물의 인도로 효력이 생긴다.","src":"민법 제193조, 제196조"},{"t":"간접점유: 지상권, 전세권, 질권, 사용대차, 임대차, 임치 기타 관계로 타인에게 물건을 점유하게 한 자는 간접점유권이 있다.","src":"민법 제194조"},{"t":"점유보조자: 가사상, 영업상 기타 유사한 관계에서 타인의 지시를 받아 물건을 사실상 지배하는 경우 그 타인만을 점유자로 한다.","src":"민법 제195조"},{"t":"점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다.","src":"민법 제197조"},{"t":"선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 제기된 때로부터 악의의 점유자로 본다(패소 확정 시가 아님).","src":"민법 제197조, 기출 2022-18, 2023-19"},{"t":"전후 양시에 점유한 사실이 있으면 점유는 계속한 것으로 추정한다.","src":"민법 제198조"},{"t":"점유의 승계인은 자기의 점유만을 주장하거나 전 점유자의 점유를 아울러 주장할 수 있다. 아울러 주장하면 전 점유의 하자도 계승한다.","src":"민법 제199조"},{"t":"점유자가 점유물에 대하여 행사하는 권리는 적법하게 보유한 것으로 추정한다.","src":"민법 제200조"},{"t":"공유자 중 일부만 건물을 점유해도 그 건물 부지는 건물 공유자 전원이 공동으로 점유한 것으로 본다.","src":"기출 2023-19"},{"t":"선의의 점유자는 점유물의 과실을 취득한다. 악의의 점유자는 수취한 과실을 반환하고, 소비·훼손·수취하지 못한 과실의 대가를 보상한다. 폭력·은비에 의한 점유자에게도 준용한다.","src":"민법 제201조"},{"t":"점유물이 점유자의 책임 있는 사유로 멸실·훼손된 경우 악의의 점유자는 손해 전부를, 선의의 점유자는 이익이 현존하는 한도에서 배상한다. 소유의 의사가 없는 점유자는 선의여도 손해 전부를 배상한다.","src":"민법 제202조"},{"t":"점유자의 상환청구권: 필요비는 상환 청구(과실을 취득한 경우 통상의 필요비는 제외). 유익비는 가액 증가가 현존한 경우에 한하여 회복자의 선택에 따라 지출액이나 증가액을 청구하며 법원은 상당한 상환기간을 허여할 수 있다.","src":"민법 제203조"}]},{"머리":"점유보호청구권과 자력구제","줄":[{"t":"점유회수: 점유의 침탈을 당한 때 물건의 반환 및 손해배상을 청구. 침탈자의 특별승계인에게는 악의인 때에 한하여 행사할 수 있다. 침탈을 당한 날부터 1년 내에 행사.","src":"민법 제204조"},{"t":"점유보유: 점유의 방해를 받은 때 방해의 제거 및 손해배상 청구. 방해가 종료한 날부터 1년 내. 공사로 인한 방해는 공사착수 후 1년을 경과하거나 공사가 완성한 때 방해제거 청구 불가.","src":"민법 제205조"},{"t":"점유보전: 방해를 받을 염려가 있을 때 방해의 예방 또는 손해배상의 담보를 청구.","src":"민법 제206조"},{"t":"간접점유자도 점유보호청구권을 행사할 수 있다. 침탈된 경우 점유자에게 반환할 것을 청구하고, 점유자가 반환받을 수 없거나 원하지 않으면 자기에게 반환을 청구할 수 있다.","src":"민법 제207조"},{"t":"점유권에 기인한 소와 본권에 기인한 소는 서로 영향을 미치지 아니한다. 점유권에 기인한 소는 본권에 관한 이유로 재판하지 못한다. 점유침탈자는 본권이 있다는 이유로 점유회수를 거부할 수 없다.","src":"민법 제208조, 기출 2023-19, 2026-18"},{"t":"자력구제: 점유를 부정히 침탈·방해하는 행위에 대해 자력으로 방위할 수 있다. 부동산은 침탈 후 직시 가해자를 배제하여 탈환, 동산은 현장에서 또는 추적하여 탈환.","src":"민법 제209조"},{"t":"재산권을 사실상 행사하는 경우(준점유)에 점유 규정을 준용한다.","src":"민법 제210조"}]},{"머리":"물권적 청구권","줄":[{"t":"소유물반환청구권: 소유자는 점유자에게 반환을 청구할 수 있으나, 점유자가 점유할 권리가 있으면 반환을 거부할 수 있다.","src":"민법 제213조"},{"t":"소유물방해제거·방해예방청구권: 소유권을 방해하는 자에게 방해의 제거를, 방해할 염려 있는 행위를 하는 자에게 예방이나 손해배상의 담보를 청구. 저당권에도 준용된다(제370조).","src":"민법 제214조, 제370조"},{"t":"소유권에 기한 방해배제청구권에서 방해란 현재에도 지속되는 침해를 의미한다.","src":"기출 2026-18"},{"t":"저당권 설정 후 소유권이 이전되면 전(前) 소유자는 방해제거청구로서 피담보채무 소멸을 이유로 저당권설정등기 말소를 청구할 수 없다.","src":"기출 2024-15"},{"t":"피담보채무가 변제된 후 양도담보권설정자가 행사하는 말소등기청구권은 시효로 소멸하지 않는다.","src":"기출 2024-15"},{"t":"계약이 합의해제되어 이미 마쳐진 소유권이전등기를 말소하는 매도인의 원상회복청구권은 소유권에 기한 물권적 청구권이다.","src":"기출 2026-18"},{"t":"타인의 토지 위에 무단 신축된 건물을 대항력 있게 임차한 점유자에게 토지소유자는 소유권에 기한 방해배제로서 퇴거를 청구할 수 있다. 대지사용권 없는 건물에 대하여 대지소유자는 건물 철거를 요구할 수 있다.","src":"기출 2026-18, 2024-17"}]}],"함정":[{"x":"경매에 의한 물권변동의 시기는 매수인이 등기를 한 때이다.","o":"매각대금을 완납한 때이다.","src":"기출 2021-19"},{"x":"선의의 점유자라도 본권에 관한 소에서 패소한 때에는 그때부터 악의의 점유자로 본다.","o":"패소한 때가 아니라 그 소가 제기된 때로부터 악의의 점유자로 본다.","src":"민법 제197조"},{"x":"한 필의 토지 일부에는 점유취득시효가 인정되지 않는다.","o":"토지 일부에도 점유취득시효가 인정된다.","src":"기출 2022-20"},{"x":"만약 X토지가 토지거래허가구역 내의 토지인 경우라면, 丙은 중간생략등기의 합의가 있음을 이유로 甲에게 직접 허가신청절차의 협력을 구할 수 있다.","o":"직접 협력을 구할 수 없다.","src":"기출 2023-18"},{"x":"선의의 점유자라도 본권에 관한 소송에서 패소한 경우, 패소가 확정된 때로부터 악의의 점유자로 본다.","o":"소가 제기된 때로부터 악의의 점유자로 본다.","src":"민법 제197조"},{"x":"저당권 설정 후 부동산 소유권이 이전된 경우, 소유권을 상실한 전(前) 소유자는 방해 제거청구로서 피담보채무의 소멸을 원인으로 저당권설정등기의 말소청구를 할 수 있다.","o":"전 소유자는 말소를 청구할 수 없다.","src":"기출 2024-15"},{"x":"X건물에 대지사용권이 없는 경우, 그 대지소유자 丁은 乙을 상대로 X건물의 철거를 요구할 수 없다.","o":"철거를 요구할 수 있다.","src":"기출 2024-17"},{"x":"타인의 토지 위에 무단으로 신축된 건물을 임차하여 점유하는 자가 건물임차권의 대항력을 갖추었다면, 토지소유자는 그 건물임차인에 대하여 소유권에 기한 방해배제로서 건물에서의 퇴거를 청구할 수 없다.","o":"대항력이 있어도 퇴거를 청구할 수 있다.","src":"기출 2026-18"},{"x":"토지에 관하여 점유취득시효 완성에 따라 소유권이전등기가 마쳐진 경우, 제3자가 그 취득시효 기간의 일부 기간 동안 토지 일부를 점유한 사실이 인정되면 등기의 추정력은 깨어진다.","o":"그 사실만으로 추정력이 깨어지지 않는다.","src":"기출 2026-21"}]},"소유권(취득·공유)":{"묶음":[{"머리":"소유권의 내용과 상린관계","줄":[{"t":"소유자는 법률의 범위 내에서 소유물을 사용, 수익, 처분할 권리가 있다. 토지의 소유권은 정당한 이익 있는 범위 내에서 토지의 상하에 미친다.","src":"민법 제211조, 제212조"},{"t":"건물의 구분소유: 수인이 한 채의 건물을 구분하여 각각 일부를 소유한 때 공용부분은 공유로 추정하며, 보존비용 기타 부담은 소유부분의 가액에 비례하여 분담한다.","src":"민법 제215조"},{"t":"인지사용청구권: 경계나 그 근방에서 담 또는 건물을 축조·수선하기 위해 필요한 범위에서 이웃 토지의 사용을 청구할 수 있다. 이웃 사람의 승낙이 없으면 주거에 들어가지 못한다. 손해를 받은 때는 보상을 청구할 수 있다.","src":"민법 제216조"},{"t":"매연·열기체·액체·음향·진동 등으로 이웃 토지의 사용을 방해하거나 이웃 거주자에게 고통을 주지 않도록 적당한 조처를 할 의무가 있다. 이웃 거주자는 통상의 용도에 적당한 것이면 인용할 의무가 있다.","src":"민법 제217조"},{"t":"수도 등 시설권: 타인의 토지를 통과하지 않으면 수도, 소수관, 가스관, 전선 등을 시설할 수 없거나 과다한 비용이 드는 경우 손해가 가장 적은 장소와 방법을 선택하여 시설할 수 있고, 요청 시 손해를 보상한다.","src":"민법 제218조"},{"t":"주위토지통행권: 토지와 공로 사이에 용도에 필요한 통로가 없는 경우 주위의 토지를 통행하거나 통로를 개설할 수 있다. 손해가 가장 적은 장소와 방법을 선택하고 통행지 소유자의 손해를 보상한다.","src":"민법 제219조"},{"t":"분할 또는 일부양도로 공로에 통하지 못하는 토지가 생기면 다른 분할자(양수인·양도인)의 토지를 통행할 수 있고 이 경우 보상의무가 없다.","src":"민법 제220조"},{"t":"자연유수의 승수의무: 토지소유자는 이웃 토지에서 자연히 흘러오는 물을 막지 못한다. 고지소유자는 저지 소유자에게 필요한 물을 정당한 사용범위를 넘어 막지 못한다.","src":"민법 제221조"},{"t":"소통공사권: 흐르는 물이 저지에서 폐색된 때 고지소유자는 자비로 소통공사를 할 수 있다. 저수·배수·인수 공작물의 파손·폐색으로 손해를 가할 염려가 있으면 타인은 보수·소통·예방을 청구할 수 있다. 비용부담 관습이 있으면 관습에 따른다.","src":"민법 제222조, 제223조, 제224조"},{"t":"토지소유자는 처마물이 이웃에 직접 낙하하지 않도록 적당한 시설을 하여야 한다.","src":"민법 제225조"},{"t":"여수소통권: 고지소유자는 침수지 건조나 가용·농·공업용의 여수 소통을 위해 공로·공류·하수도에 달하기까지 저지에 물을 통과시킬 수 있으며 손해를 보상한다. 유수용 공작물은 이익 비율로 비용을 분담하고 사용할 수 있다. 여수급여청구권은 보상하고 청구할 수 있다.","src":"민법 제226조, 제227조, 제228조"},{"t":"수류의 변경: 수류지 소유자는 대안의 토지가 타인 소유이면 수로·수류의 폭을 변경하지 못한다. 양안이 모두 자기 소유이면 변경할 수 있으나 하류는 자연의 수로와 일치하여야 한다.","src":"민법 제229조"},{"t":"언(堰)의 설치: 수류지 소유자가 필요한 때 대안에 접촉하게 할 수 있으나 손해를 보상한다. 대안 소유자는 수류지의 일부가 자기 소유이면 그 언을 사용할 수 있고 이익 비율로 비용을 분담한다.","src":"민법 제230조"},{"t":"공유하천용수권: 연안에서 농·공업을 경영하는 자는 타인의 용수를 방해하지 않는 범위에서 인수할 수 있다. 하류 연안의 용수권을 방해하면 방해제거와 손해배상을 청구할 수 있다. 용수권은 특별승계인이 승계한다.","src":"민법 제231조, 제232조, 제233조"},{"t":"공용에 속하는 원천이나 수도는 각 수요의 정도에 응하여 타인의 용수를 방해하지 않는 범위에서 용수할 수 있다. 공사로 단수·감수 등 용수에 장해가 생기면 손해배상을 청구할 수 있고 음료수 등 생활상 필요한 경우 원상회복도 청구할 수 있다.","src":"민법 제235조, 제236조"},{"t":"경계표·담: 인접 토지 소유자는 공동비용으로 통상의 경계표나 담을 설치할 수 있다. 비용은 쌍방이 절반씩 부담하고 측량비용은 면적에 비례한다. 경계에 설치된 경계표, 담, 구거 등은 상린자의 공유로 추정한다(단독비용 설치나 담이 건물의 일부이면 제외).","src":"민법 제237조, 제239조"},{"t":"담의 특수시설권: 인지소유자는 자기 비용으로 담의 재료를 양호하게 하거나 높게 하거나 방화벽 등 특수시설을 할 수 있다.","src":"민법 제238조"},{"t":"수목: 인접지의 수목가지가 경계를 넘으면 소유자에게 제거를 청구할 수 있고, 응하지 않으면 청구자가 제거할 수 있다. 뿌리가 경계를 넘으면 임의로 제거할 수 있다.","src":"민법 제240조"},{"t":"토지의 심굴금지: 인접지의 지반이 붕괴할 정도로 자기 토지를 파지 못한다(충분한 방어공사를 한 때는 제외).","src":"민법 제241조"},{"t":"경계선 부근의 건축: 특별한 관습이 없으면 경계로부터 반미터 이상 거리를 둔다. 위반 시 변경·철거를 청구할 수 있으나 착수 후 1년을 경과하거나 완성 후에는 손해배상만 청구할 수 있다.","src":"민법 제242조"},{"t":"차면시설: 경계로부터 2미터 이내에서 이웃 주택의 내부를 관망할 수 있는 창이나 마루를 설치하면 적당한 차면시설을 하여야 한다.","src":"민법 제243조"},{"t":"지하시설: 우물, 용수·하수·오물 저치 지하시설은 경계로부터 2미터 이상, 저수지·구거·지하실공사는 깊이의 반 이상 거리를 둔다. 토사 붕괴, 하수·오액이 이웃에 흐르지 않도록 적당한 조처를 한다.","src":"민법 제244조"},{"t":"상린관계 규정은 지상권자 간, 전세권자 간, 전세권자와 인지소유자·지상권자 간에 준용된다.","src":"민법 제290조, 제319조"}]},{"머리":"취득시효","줄":[{"t":"부동산 점유취득시효: 20년간 소유의 의사로 평온, 공연하게 점유하는 자는 등기함으로써 소유권을 취득한다. 소유자로 등기한 자가 10년간 소유의 의사로 평온, 공연하게 선의이며 과실 없이 점유한 때에는 소유권을 취득한다.","src":"민법 제245조"},{"t":"동산 점유취득시효: 10년간 소유의 의사로 평온, 공연하게 점유하면 소유권을 취득한다. 선의이며 과실 없이 개시된 점유는 5년.","src":"민법 제246조"},{"t":"취득시효에 의한 소유권 취득의 효력은 점유를 개시한 때에 소급한다. 소멸시효 중단 규정이 취득시효 기간에 준용된다. 소유권 이외의 재산권 취득에도 준용된다.","src":"민법 제247조, 제248조"}]},{"머리":"선의취득과 무주물·유실물·매장물","줄":[{"t":"선의취득: 평온, 공연하게 동산을 양수한 자가 선의이며 과실 없이 점유한 경우 양도인이 정당한 소유자가 아니어도 즉시 소유권을 취득한다.","src":"민법 제249조"},{"t":"도품·유실물 특례: 피해자 또는 유실자는 도난 또는 유실한 날부터 2년 내에 반환을 청구할 수 있다. 도품·유실물이 금전이면 제외.","src":"민법 제250조"},{"t":"양수인이 도품·유실물을 경매나 공개시장에서 또는 동종 물건 판매 상인에게서 선의로 매수한 때 피해자는 양수인이 지급한 대가를 변상하고 반환을 청구할 수 있다.","src":"민법 제251조"},{"t":"등록에 의해 공시되는 자동차는 선의취득의 대상이 아니다. 등기·등록으로 공시되는 동산은 원칙적으로 선의취득 대상이 아니다.","src":"기출 2021-23, 2022-19, 2026-20"},{"t":"선의취득이 성립하려면 양도인이 무권리자라는 점을 제외하고 아무 흠이 없는 유효한 거래행위가 있어야 한다. 거래행위가 무효이거나 취소된 경우에는 성립하지 않는다.","src":"기출 2021-23, 2022-19, 2026-20"},{"t":"경매에서도 선의취득이 인정된다. 동산질권도 선의취득의 대상이다.","src":"기출 2021-23, 2026-20"},{"t":"점유개정에 의한 점유취득만으로는 선의취득이 인정되지 않는다. 목적물반환청구권의 양도에 의한 인도로는 선의취득이 인정된다.","src":"기출 2022-19, 2021-23"},{"t":"선의취득을 부정하는 자가 양수인의 악의·과실을 증명하여야 하고 양수인이 선의·평온·공연·무과실을 스스로 증명할 필요는 없다(점유 추정, 제197조).","src":"기출 2022-19"},{"t":"거래행위에서 인도가 물권적 합의보다 먼저 행하여지면 물권적 합의가 성립한 때를 기준으로 양수인의 선의·무과실을 판단한다.","src":"기출 2026-20"},{"t":"유상으로 동산을 선의취득한 자는 선의취득의 효과를 거부하고 종전 소유자에게 반환하겠다고 임의로 요구할 수 없다.","src":"기출 2026-20"},{"t":"점유보조자가 점유물을 임의로 처분한 경우 도품·유실물에 관한 특칙은 적용되지 않는다.","src":"기출 2022-19"},{"t":"무주물 선점: 무주의 동산을 소유의 의사로 점유한 자는 소유권을 취득한다. 무주의 부동산은 국유. 야생동물은 무주물.","src":"민법 제252조"},{"t":"유실물은 법률에 정한 바에 따라 공고한 후 6개월 내에 소유자가 권리를 주장하지 않으면 습득자가 소유권을 취득한다. 매장물은 공고 후 1년 내 권리 주장이 없으면 발견자가 취득하되, 타인의 토지 기타 물건에서 발견한 매장물은 그 소유자와 발견자가 절반씩 취득한다.","src":"민법 제253조, 제254조"}]},{"머리":"첨부","줄":[{"t":"부동산에의 부합: 부동산의 소유자는 부합한 물건의 소유권을 취득한다. 타인의 권원에 의하여 부속된 것은 제외.","src":"민법 제256조"},{"t":"동산 간 부합: 훼손하지 않으면 분리할 수 없거나 분리에 과다한 비용이 들면 합성물의 소유권은 주된 동산의 소유자에게 속한다. 주종을 구별할 수 없으면 부합 당시 가액의 비율로 공유. 혼화에 준용.","src":"민법 제257조, 제258조"},{"t":"가공: 타인의 동산에 가공한 때 소유권은 원재료 소유자에게 속한다. 가공으로 인한 가액 증가가 원재료 가액보다 현저히 다액이면 가공자의 소유. 가공자가 재료 일부를 제공하면 그 가액은 증가액에 가산.","src":"민법 제259조"},{"t":"첨부로 동산의 소유권이 소멸하면 그 동산을 목적으로 한 다른 권리도 소멸한다. 손해를 받은 자는 부당이득 규정에 의하여 보상을 청구할 수 있다.","src":"민법 제260조, 제261조"}]},{"머리":"공유","줄":[{"t":"물건이 지분에 의하여 수인의 소유로 된 때에는 공유이다. 공유자의 지분은 균등한 것으로 추정한다.","src":"민법 제262조"},{"t":"공유자는 지분을 다른 공유자의 동의 없이 자유롭게 처분할 수 있고, 공유물 전부를 지분의 비율로 사용·수익할 수 있다.","src":"민법 제263조"},{"t":"공유물의 처분·변경에는 다른 공유자의 동의가 필요하다. 공유토지 위에 견고한 건물을 신축하려면 전원의 동의가 필요하다.","src":"민법 제264조, 기출 2024-18"},{"t":"공유물의 관리에 관한 사항은 공유자 지분의 과반수로 결정한다(인원수 과반이 아님). 공유물 임대도 지분 과반수로 결정한다. 보존행위는 각자 할 수 있다.","src":"민법 제265조, 기출 2021-21, 2025-23"},{"t":"공유자는 지분의 비율로 관리비용 기타 의무를 부담한다. 1년 이상 의무 이행을 지체하면 다른 공유자는 상당한 가액으로 지분을 매수할 수 있다.","src":"민법 제266조"},{"t":"공유자가 지분을 포기하거나 상속인 없이 사망하면 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다.","src":"민법 제267조"},{"t":"분할청구: 공유자는 분할을 청구할 수 있으나 5년 내의 기간으로 분할하지 아니할 것을 약정할 수 있다. 갱신해도 갱신한 날부터 5년을 넘지 못한다. 건물의 구분소유 공용부분(제215조)과 경계표 등(제239조)의 공유물에는 적용하지 않는다.","src":"민법 제268조"},{"t":"분할방법: 협의가 성립되지 않으면 법원에 분할을 청구한다. 현물로 분할할 수 없거나 분할로 현저히 가액이 감손될 염려가 있으면 법원은 경매를 명할 수 있다. 공유물 분할은 공유자 전원이 참여하여야 한다.","src":"민법 제269조, 기출 2026-19"},{"t":"공유자는 다른 공유자가 분할로 취득한 물건에 대하여 지분의 비율로 매도인과 동일한 담보책임을 진다.","src":"민법 제270조"},{"t":"과반수 지분권자는 공유자 간 협의 없이도 관리방법으로 공유물의 특정 부분을 배타적으로 사용·수익하게 정할 수 있다.","src":"기출 2022-23"},{"t":"지분 과반수 합의 없이 공유물의 전부·일부를 배타적으로 사용하는 공유자에게 다른 공유자는 지분 비율로 부당이득 반환을 청구할 수 있다.","src":"기출 2022-23"},{"t":"소수지분권자가 협의 없이 공유물을 독점 점유하는 경우 다른 소수지분권자는 보존행위로서 그 인도를 구할 수 없다.","src":"기출 2022-23, 2023-20"},{"t":"공유자 간 지분 교환에는 다른 공유자의 동의가 필요 없다. 공유자 1인이 상속인 없이 사망하면 그 지분은 다른 공유자에게 귀속한다. 과반수가 결정한 임대에 대해 소수 공유자는 임차인에게 반환을 청구할 수 없다. 제3자 명의 원인무효 등기는 각 공유자가 전부 말소를 구할 수 있다(보존행위).","src":"기출 2023-20"},{"t":"공유자가 다른 공유자의 지분권을 대외적으로 주장하는 것은 보존행위가 아니다. 공유물인 나대지에 건물을 신축하는 행위도 보존행위가 아니다.","src":"기출 2024-18, 2025-23"}]},{"머리":"합유와 총유","줄":[{"t":"합유: 법률 규정 또는 계약에 의하여 수인이 조합체로서 물건을 소유하는 때. 합유자의 권리는 합유물 전부에 미친다.","src":"민법 제271조"},{"t":"합유물의 처분·변경에는 합유자 전원의 동의가 필요하다. 보존행위는 각자 할 수 있다.","src":"민법 제272조"},{"t":"합유자는 전원의 동의 없이 지분을 처분하지 못하고, 합유물의 분할을 청구하지 못한다.","src":"민법 제273조"},{"t":"합유는 조합체의 해산 또는 합유물의 양도로 종료하며, 분할에는 공유물 분할 규정을 준용한다.","src":"민법 제274조"},{"t":"총유: 비법인사단의 사원이 집합체로서 물건을 소유. 관리·처분은 사원총회 결의에 의한다. 총유물의 보존행위도 구성원 각자가 할 수 없고 총회 결의 등이 필요하다.","src":"민법 제275조, 제276조, 기출 2026-19"},{"t":"총유물에 관한 사원의 권리의무는 사원의 지위를 취득·상실함으로써 취득·상실된다. 본절 규정은 소유권 이외의 재산권에 준용한다(준공동소유).","src":"민법 제277조, 제278조"}]}],"함정":[{"x":"공유자는 다른 공유자의 동의 없이 자신의 지분을 처분할 수 없다.","o":"다른 공유자의 동의 없이 지분을 처분할 수 있다.","src":"민법 제263조"},{"x":"목적물반환청구권의 양도에 의한 선의취득은 인정되지 않는다.","o":"목적물반환청구권 양도에 의한 인도로도 선의취득이 인정된다.","src":"기출 2021-23"},{"x":"선의취득을 주장하는 자는 소유의 의사로 선의, 평온, 공연하게 점유하였음을 스스로 증명하여야 한다.","o":"점유자는 선의·평온·공연이 추정되므로 이를 부정하는 자가 증명한다.","src":"민법 제197조"},{"x":"과반수 공유지분권자라도 다른 공유자와의 협의가 없는 한 공유물의 특정한 부분을 배타적으로 사용ㆍ수익할 수 없다.","o":"과반수 지분권자는 협의 없이도 관리방법으로 특정 부분을 배타적으로 사용·수익할 수 있다.","src":"기출 2022-23"},{"x":"상린자의 공유로 추정되는 경계에 설치된 경계표에 대해서도 공유물분할을 청구할 수 있다.","o":"경계표 등에는 분할청구가 허용되지 않는다.","src":"민법 제268조"},{"x":"재판에 의한 분할이 공유물 분할의 원칙적 방법이다.","o":"협의 분할이 원칙이고 협의가 안 되면 법원에 청구한다.","src":"민법 제269조"},{"x":"공유자가 다른 공유자의 지분권만을 대외적으로 주장하는 것은 공유물의 보존행위에 해당한다.","o":"보존행위에 해당하지 않는다.","src":"기출 2024-18"},{"x":"보존행위가 아닌 공유물의 관리에 관한 사항은 공유자의 과반수에 의해서만 결정된다.","o":"공유자 지분의 과반수로 결정한다(인원수 아님).","src":"민법 제265조"},{"x":"공유물의 관리에 관한 사항은 공유자 인원수의 과반수로써 결정한다.","o":"지분의 과반수로 결정한다.","src":"민법 제265조"},{"x":"공유물인 나대지에 새로이 건물을 신축하는 행위는 보존행위에 속한다.","o":"보존행위가 아니다(전원 동의가 필요한 처분·변경).","src":"기출 2025-23"},{"x":"공유자가 다른 공유자의 지분권을 대외적으로 주장하는 행위는 보존행위에 속한다.","o":"보존행위에 속하지 않는다.","src":"기출 2025-23"},{"x":"공유자는 공유물 전부를 지분의 비율로 사용, 수익할 수 있으나 자신의 지분을 처분할 수는 없다.","o":"지분을 처분할 수 있다.","src":"민법 제263조"},{"x":"공유자는 그 지분비율에 관계없이 공유물의 관리비용을 균등하게 부담한다.","o":"지분의 비율로 부담한다.","src":"민법 제266조"},{"x":"공유자는 전원의 동의없이는 공유물에 대한 지분을 처분할 수 없다.","o":"자유롭게 처분할 수 있다.","src":"민법 제263조"},{"x":"합유자의 지분은 균등한 것으로 추정한다.","o":"출제 오답(바른 문장 미확인, 합유는 민법에 지분 균등 추정 규정이 없다).","src":"기출 2026-19"},{"x":"총유물의 보존행위는 구성원 각자가 할 수 있다.","o":"사원총회 결의 등이 필요하여 구성원 각자가 할 수 없다.","src":"민법 제276조"},{"x":"거래행위에서 인도가 물권적 합의보다 먼저 행하여지면 인도된 때를 기준으로 양수인의 선의ㆍ무과실을 판단하여야 한다.","o":"물권적 합의가 성립한 때를 기준으로 한다.","src":"기출 2026-20"}]},"용익물권(지상권·전세권)":{"묶음":[{"머리":"지상권의 내용과 존속기간","줄":[{"t":"지상권: 타인의 토지에 건물 기타 공작물이나 수목을 소유하기 위하여 그 토지를 사용하는 권리.","src":"민법 제279조"},{"t":"지료의 지급은 지상권의 성립요소가 아니다(무상 지상권 가능).","src":"기출 2023-21"},{"t":"계약으로 정하는 지상권의 최단존속기간: 석조·석회조·연와조 또는 이와 유사한 견고한 건물이나 수목의 소유 목적은 30년, 그 밖의 건물은 15년, 건물 이외의 공작물은 5년. 이보다 단축한 기간을 정하면 최단기간까지 연장한다.","src":"민법 제280조"},{"t":"존속기간을 정하지 않은 때에는 최단존속기간으로 한다. 공작물의 종류와 구조를 정하지 않은 때에는 제280조 제2호(기타 건물, 15년)의 건물 소유를 목적으로 한 것으로 본다.","src":"민법 제281조"},{"t":"지상권자는 지상권을 타인에게 양도하거나 존속기간 내에서 토지를 임대할 수 있다(설정자의 동의 불필요).","src":"민법 제282조"},{"t":"갱신청구권·매수청구권: 지상권이 소멸한 경우 건물 기타 공작물이나 수목이 현존한 때에는 지상권자는 계약의 갱신을 청구할 수 있다. 설정자가 갱신을 원하지 않으면 상당한 가액으로 지상물 매수를 청구할 수 있다. 갱신 청구 없이 곧바로 매수청구를 할 수 없다.","src":"민법 제283조, 기출 2023-21"},{"t":"갱신하는 경우 존속기간은 갱신한 날부터 최단존속기간보다 단축하지 못하나 더 길게 정할 수 있다.","src":"민법 제284조"},{"t":"지상권이 소멸하면 지상권자는 지상물을 수거하여 토지를 원상회복할 의무가 있고, 설정자가 상당한 가액을 제공하여 매수를 청구하면 정당한 이유 없이 거절하지 못한다.","src":"민법 제285조"},{"t":"지료증감청구권: 조세 기타 부담의 증감이나 지가 변동으로 지료가 상당하지 않게 된 때 증감을 청구할 수 있다.","src":"민법 제286조"},{"t":"지상권소멸청구: 지상권자가 2년 이상의 지료를 지급하지 아니한 때 설정자는 소멸을 청구할 수 있다. 지상권이나 지상 건물·수목이 저당권의 목적이면 저당권자에게 통지한 후 상당한 기간이 경과해야 효력이 생긴다.","src":"민법 제287조, 제288조"},{"t":"제280조 내지 제287조에 위반하는 계약으로 지상권자에게 불리한 것은 효력이 없다(편면적 강행규정).","src":"민법 제289조"},{"t":"구분지상권: 지하 또는 지상의 공간은 상하의 범위를 정하여 건물 기타 공작물을 소유하기 위한 지상권의 목적으로 할 수 있다. 제3자가 토지를 사용·수익할 권리를 가진 때도 그 권리자 및 그 권리를 목적으로 하는 권리자 전원의 승낙이 있으면 설정할 수 있다.","src":"민법 제289조의2"},{"t":"상린관계(제216조 내지 제244조)와 소유물반환·방해제거 규정은 지상권자 간 또는 지상권자와 인지소유자 간에 준용된다.","src":"민법 제290조, 기출 2024-16"},{"t":"지상권을 목적으로 저당권을 설정한 자는 저당권자의 동의 없이 지상권을 소멸하게 하는 행위를 하지 못한다.","src":"민법 제371조, 기출 2024-16"},{"t":"지료액에 관한 약정은 등기하여야 제3자에게 대항할 수 있다.","src":"기출 2026-22"}]},{"머리":"법정지상권과 관습상 법정지상권","줄":[{"t":"저당물 경매로 토지와 지상건물이 다른 소유자에 속하게 된 때 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자의 청구에 의하여 법원이 정한다.","src":"민법 제366조"},{"t":"토지에 저당권을 설정한 후 설정자가 건물을 축조한 때 저당권자는 토지와 함께 건물도 경매를 청구할 수 있으나 건물의 경매대가에 대하여는 우선변제를 받을 권리가 없다.","src":"민법 제365조"},{"t":"저당권설정 당사자 간 특약으로 제366조의 법정지상권을 배제하는 약정을 해도 효력이 없다.","src":"기출 2024-16"},{"t":"대지와 건물이 동일한 소유자에 속한 경우 건물에 전세권을 설정한 때 대지소유권의 특별승계인은 「전세권설정자」(건물소유자)에 대하여 지상권을 설정한 것으로 본다. 전세권자가 아니다. 지료는 당사자 청구로 법원이 정한다.","src":"민법 제305조"},{"t":"관습상 법정지상권은 설정등기 없이 취득한다.","src":"기출 2023-21"},{"t":"관습상 법정지상권은 건물로서의 요건을 갖추었다면 무허가·미등기 건물에도 인정될 수 있다.","src":"기출 2024-16, 2025-20"},{"t":"관습상 법정지상권이 성립하려면 처분 당시 토지와 건물이 동일인 소유이면 족하고 원시적으로 동일인 소유일 필요는 없다.","src":"기출 2025-20"},{"t":"공유토지 위에 건물을 소유한 토지 공유자 중 1인이 토지 지분만 매도한 경우 관습상 법정지상권은 성립하지 않는다.","src":"기출 2025-20"},{"t":"관습상 법정지상권에도 지상권의 존속기간 규정이 준용된다.","src":"기출 2025-20"},{"t":"법정지상권이 있는 건물의 양수인도 대지를 점유·사용함으로써 얻은 이득을 부당이득으로 대지소유자에게 반환할 의무가 있다.","src":"기출 2026-22"},{"t":"법정지상권자가 지급할 지료를 정할 때 법정지상권이 설정된 건물이 건립되어 있어 토지소유권이 제한받는 사정은 참작·평가하지 않는다.","src":"기출 2026-22"},{"t":"법정지상권의 목적인 토지가 양도된 경우 법정지상권자는 등기 없이도 양수인에게 대항할 수 있다.","src":"기출 2026-22"},{"t":"지료 연체를 이유로 지상권이 소멸된 경우 지상권자는 지상물매수청구권을 행사할 수 없다.","src":"기출 2024-16"}]},{"머리":"전세권의 내용","줄":[{"t":"전세권자는 전세금을 지급하고 타인의 부동산을 점유하여 그 용도에 좇아 사용·수익하며, 그 부동산 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있다.","src":"민법 제303조"},{"t":"농경지는 전세권의 목적으로 하지 못한다.","src":"민법 제303조"},{"t":"전세금의 지급은 전세권의 요소이나 반드시 현실로 수수될 필요는 없고 기존의 채권으로 갈음할 수 있다.","src":"기출 2021-18, 2022-24, 2024-19"},{"t":"임차보증금반환채권을 담보할 목적으로 제3자 명의로 마쳐진 전세권설정등기도 유효하다.","src":"기출 2022-24"},{"t":"건물에 대한 전세권의 존속기간을 1년 미만으로 정한 때는 1년으로 한다.","src":"민법 제312조"},{"t":"전세권의 존속기간은 10년을 넘지 못하고, 약정기간이 10년을 넘으면 10년으로 단축한다. 갱신 기간도 10년을 넘지 못한다.","src":"민법 제312조"},{"t":"건물의 전세권설정자가 존속기간 만료 전 6월부터 1월 사이에 갱신거절 또는 조건변경 통지를 하지 않으면 전전세권과 동일한 조건으로 다시 전세권을 설정한 것으로 보고, 존속기간은 정함이 없는 것으로 본다(법정갱신).","src":"민법 제312조"},{"t":"전세금 증감청구권: 조세·공과금 기타 부담의 증감이나 경제사정의 변동으로 상당하지 않게 된 때 장래에 대하여 증감을 청구할 수 있다. 증액은 대통령령이 정하는 비율을 초과하지 못한다.","src":"민법 제312조의2"},{"t":"존속기간을 약정하지 않은 때 각 당사자는 언제든지 소멸을 통고할 수 있고 상대방이 통고를 받은 날부터 6월이 경과하면 전세권이 소멸한다.","src":"민법 제313조"},{"t":"전세권의 존속기간이 만료되면 특별한 사정이 없는 한 용익물권적 권능은 설정등기 말소 없이도 당연히 소멸한다.","src":"기출 2024-19"}]},{"머리":"전세권자의 권리와 의무","줄":[{"t":"전세권자는 전세권을 타인에게 양도 또는 담보로 제공할 수 있고 존속기간 내에서 목적물을 전전세 또는 임대할 수 있다. 설정행위로 금지하면 불가.","src":"민법 제306조"},{"t":"전세권양수인은 설정자에 대하여 전세권양도인과 동일한 권리의무가 있다.","src":"민법 제307조"},{"t":"전세권의 목적물을 전전세 또는 임대한 경우 전세권자는 그렇게 하지 않았으면 면할 수 있는 불가항력으로 인한 손해에 대해서도 책임을 진다.","src":"민법 제308조"},{"t":"전세권자는 목적물의 현상을 유지하고 통상의 관리에 속한 수선을 하여야 한다(설정자가 아니다).","src":"민법 제309조"},{"t":"유익비는 가액의 증가가 현존한 경우에 한하여 소유자의 선택에 좇아 지출액이나 증가액의 상환을 청구할 수 있고, 법원은 소유자의 청구로 상당한 상환기간을 허여할 수 있다.","src":"민법 제310조"},{"t":"정해진 용법으로 사용·수익하지 않으면 설정자는 전세권의 소멸을 청구할 수 있고, 원상회복 또는 손해배상을 청구할 수 있다.","src":"민법 제311조"},{"t":"목적물이 불가항력으로 전부 또는 일부 멸실되면 그 멸실 부분의 전세권은 소멸한다. 잔존 부분으로 목적을 달성할 수 없으면 전세권 전부의 소멸을 통고하고 전세금 반환을 청구할 수 있다.","src":"민법 제314조"},{"t":"전세권자의 책임 있는 사유로 멸실된 때에는 전세권자가 손해를 배상하고, 설정자는 전세권 소멸 후 전세금으로 손해배상에 충당하고 잉여는 반환하며 부족하면 다시 청구할 수 있다.","src":"민법 제315조"},{"t":"존속기간 만료로 소멸하면 전세권자는 원상회복하고 부속물을 수거할 수 있다. 설정자가 부속물 매수를 청구하면 정당한 이유 없이 거절하지 못한다. 설정자 동의를 얻어 부속시켰거나 설정자로부터 매수한 부속물은 전세권자가 매수를 청구할 수 있다.","src":"민법 제316조"},{"t":"전세권이 소멸한 때 설정자는 전세권자로부터 목적물의 인도 및 전세권설정등기 말소에 필요한 서류의 교부를 받는 동시에 전세금을 반환하여야 한다(동시이행).","src":"민법 제317조"},{"t":"설정자가 전세금 반환을 지체하면 전세권자는 민사집행법에 따라 목적물의 경매를 청구할 수 있다.","src":"민법 제318조"},{"t":"건물에 대한 전세권: 타인의 토지에 있는 건물에 전세권을 설정하면 전세권의 효력은 그 건물 소유를 목적으로 한 지상권 또는 임차권에 미친다. 전세권설정자는 전세권자의 동의 없이 지상권·임차권을 소멸하게 하는 행위를 하지 못한다.","src":"민법 제304조, 기출 2025-21"},{"t":"전세권자 간 또는 전세권자와 인지소유자·지상권자 간에 상린관계 규정이 준용된다.","src":"민법 제319조"},{"t":"전세권 존속 중 전세권이 소멸하여 전세금반환채권이 발생할 것을 조건으로 그 장래의 조건부 채권을 양도할 수 있다.","src":"기출 2022-24"},{"t":"전세권을 목적으로 저당권이 설정된 경우 존속기간 만료 후에는 전세권 자체에 저당권을 실행할 수 없고, 전세금반환채권에 대한 물상대위 등으로 행사한다.","src":"기출 2022-24"},{"t":"전세기간 만료 후 전세권양도계약과 전세권이전 부기등기만으로는 전세금반환채권 양도의 제3자 대항요건을 갖추지 못한다(지명채권 양도 통지·승낙 필요).","src":"기출 2024-19"},{"t":"지상권 또는 전세권을 저당권의 목적으로 설정한 자는 저당권자의 동의 없이 지상권·전세권을 소멸하게 하는 행위를 하지 못한다.","src":"민법 제371조"}]}],"함정":[{"x":"타인의 토지 위에 있는 건물에 설정된 전세권의 효력은 그 건물의 소유를 목적으로 한 지상권에 미치지 않는다.","o":"건물 소유를 목적으로 한 지상권 또는 임차권에 미친다.","src":"민법 제304조"},{"x":"대지와 건물이 동일한 소유자에 속한 경우에 건물에 전세권을 설정한 때에는 그 대지 소유권의 특별승계인은 전세권자에 대하여 지상권을 설정한 것으로 본다.","o":"전세권설정자(건물소유자)에 대하여 지상권을 설정한 것으로 본다.","src":"민법 제305조"},{"x":"전세권설정자는 목적물의 현상을 유지하고 그 통상의 관리에 속한 수선을 해야 한다.","o":"전세권자가 현상유지와 통상 수선의무를 진다.","src":"민법 제309조"},{"x":"전세권자와 인지소유자 사이에는 상린관계에 관한 규정이 적용되지 않는다.","o":"상린관계 규정이 준용된다.","src":"민법 제319조"},{"x":"전세금은 전세권의 요소이므로 전세금이 현실적으로 수수되지 않으면 전세권은 성립하지 않는다.","o":"기존 채권으로 갈음하는 등 현실 수수가 없어도 성립할 수 있다.","src":"기출 2022-24"},{"x":"건물에 대한 전세권의 존속기간을 2년 미만으로 정한 경우 그 존속기간은 2년으로 한다.","o":"1년 미만으로 정한 경우 1년으로 한다.","src":"민법 제312조"},{"x":"전세권을 목적으로 하는 저당권이 설정된 경우에 전세권의 존속기간이 만료되면 전세권 자체에 대하여 저당권을 실행할 수 있다.","o":"전세권 자체에 대한 저당권 실행은 할 수 없다.","src":"기출 2022-24"},{"x":"전세권설정계약 없이 임차보증금반환채권을 담보할 목적으로 임대인, 임차인 및 제3자 사이의 합의에 따라 제3자 명의로 마쳐진 전세권설정등기는 무효이다.","o":"유효하다.","src":"기출 2022-24"},{"x":"지상권이 존속기간 만료로 소멸되었으나 지상물이 현존하고 있다면, 지상권자는 지상권 설정계약의 갱신을 청구하지 않더라도 지상권설정자에게 지상물매수를 청구할 수 있다.","o":"먼저 갱신을 청구하고 설정자가 거절하면 매수를 청구할 수 있다.","src":"민법 제283조"},{"x":"지상권자의 지료연체를 이유로 지상권이 소멸된 경우, 지상권자는 지상물매수청구권을 행사할 수 있다.","o":"행사할 수 없다.","src":"기출 2024-16"},{"x":"전세기간 만료 이후 전세권양도계약 및 전세권이전의 부기등기가 경료된 것만으로도 전세금반환채권 양도의 제3자에 대한 대항요건은 충족된다.","o":"충족되지 않는다.","src":"기출 2024-19"},{"x":"관습법상 법정지상권은 설정등기 없이 취득하지 못한다.","o":"등기 없이 취득한다.","src":"기출 2025-20"},{"x":"미등기이거나 무허가인 건물에 대해서는 관습법상 법정지상권이 인정될 수 없다.","o":"인정될 수 있다.","src":"기출 2025-20"},{"x":"관습법상 법정지상권에 대해서는 지상권의 존속기간에 관한 민법 규정이 준용되지 않는다.","o":"지상권 존속기간 규정이 준용된다.","src":"기출 2025-20"},{"x":"관습법상 법정지상권이 성립하기 위해서는 토지와 그 지상건물이 원시적으로 동일인의 소유에 속해야 한다.","o":"처분 당시 동일인 소유이면 되고 원시적일 필요는 없다.","src":"기출 2025-20"},{"x":"전세권자는 특별한 사정이 없는 한 전세권을 타인에게 담보로 제공할 수 없다.","o":"담보로 제공할 수 있다.","src":"민법 제306조"},{"x":"대지와 건물이 동일한 소유자에 속한 경우에 건물에 전세권을 설정한 때에는 그 대지 소유권의 특별승계인은 전세권자에 대하여 지상권을 설정한 것으로 본다.","o":"전세권설정자에 대하여 지상권을 설정한 것으로 본다.","src":"민법 제305조"}]},"담보물권(유치권·질권·저당권)":{"묶음":[{"머리":"유치권","줄":[{"t":"요건: 타인의 물건 또는 유가증권을 점유한 자가 그 물건·유가증권에 관하여 생긴 채권이 변제기에 있을 것. 점유가 불법행위로 인한 경우에는 적용하지 않는다.","src":"민법 제320조"},{"t":"유치권은 점유를 상실하면 소멸한다. 채무자는 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있다.","src":"민법 제327조, 제328조"},{"t":"불가분성: 유치권자는 채권 전부의 변제를 받을 때까지 유치물 전부에 대하여 권리를 행사할 수 있다(목적물이 분할 가능하거나 수개의 물건이어도 같다).","src":"민법 제321조, 기출 2021-20"},{"t":"경매권·간이변제충당: 변제를 받기 위해 유치물을 경매할 수 있다. 정당한 이유가 있으면 감정인 평가에 의해 직접 변제에 충당할 것을 법원에 청구할 수 있고 미리 채무자에게 통지하여야 한다.","src":"민법 제322조"},{"t":"과실수취권: 유치물의 과실을 수취하여 다른 채권보다 먼저 변제에 충당할 수 있다. 과실이 금전이 아니면 경매하여야 한다. 과실은 먼저 이자에, 잉여는 원본에 충당.","src":"민법 제323조"},{"t":"유치권자는 선량한 관리자의 주의로 점유하여야 한다. 채무자의 승낙 없이 유치물의 사용, 대여, 담보제공을 하지 못하나 보존에 필요한 사용은 가능하다. 위반하면 채무자는 유치권의 소멸을 청구할 수 있다.","src":"민법 제324조"},{"t":"유치권자의 상환청구권: 필요비는 상환 청구, 유익비는 가액 증가가 현존한 경우에 한하여 소유자의 선택에 좇아 청구. 법원은 소유자 청구로 상환기간을 허여할 수 있다.","src":"민법 제325조"},{"t":"유치권의 행사는 채권의 소멸시효의 진행에 영향을 미치지 않는다(유치권 행사 중에도 시효는 진행·중단되지 않음).","src":"민법 제326조"},{"t":"유치권의 성질: 법정담보물권, 부종성, 수반성, 불가분성이 있고 물상대위성은 없다.","src":"기출 2023-22"},{"t":"유치권 배제 특약이 있으면 다른 요건이 충족되어도 유치권이 발생하지 않으며, 그 특약의 효력은 특약 상대방이 아닌 제3자도 주장할 수 있다.","src":"기출 2021-20, 2024-20, 2026-23"},{"t":"채권자가 채무자의 직접점유를 통해 간접점유하는 경우, 또는 유치물의 직접점유자가 채무자인 경우에는 유치권이 성립하지 않는다.","src":"기출 2021-20, 2026-23"},{"t":"독립한 건물로 볼 수 없는 정착물을 토지에 설치한 상태에서 공사가 중단된 경우 그 정착물에 대하여 유치권을 행사할 수 없다.","src":"기출 2021-20, 2026-23"},{"t":"유치권자는 보존에 필요한 범위에서 유치물을 사용할 수 있고, 보존행위로서 사용하는 경우 불법사용으로 인한 손해배상책임이 없다. 유치권자가 스스로 주택에 거주하는 것이 보존행위에 해당하면 소멸청구를 할 수 없다.","src":"기출 2021-20, 2024-20, 2026-23"},{"t":"유치권자는 채무자의 승낙 없이 목적물을 제3자에게 임대할 처분 권한이 없다.","src":"기출 2026-23"},{"t":"점유가 불법행위로 개시된 경우 유치권은 성립하지 않으며 그 불법행위가 아님의 증명책임은 유치권을 부정하는 쪽에 있다(유치권자가 증명할 필요가 없다).","src":"민법 제320조, 기출 2024-20, 2025-24"},{"t":"임대차보증금반환채권을 피담보채권으로 하는 유치권은 행사할 수 없다.","src":"기출 2025-24"},{"t":"유치물의 공정한 가격을 쉽게 알 수 없다는 사정은 간이변제충당의 정당한 이유가 되지 않는다.","src":"기출 2024-20"}]},{"머리":"질권","줄":[{"t":"동산질권: 채권의 담보로 채무자 또는 제3자가 제공한 동산을 점유하고 다른 채권자보다 자기채권의 우선변제를 받는 권리.","src":"민법 제329조"},{"t":"질권의 설정은 질권자에게 목적물을 인도함으로써 효력이 생긴다(요물계약). 질권자는 설정자로 하여금 질물의 점유를 하게 하지 못한다.","src":"민법 제330조, 제332조"},{"t":"질권은 양도할 수 없는 물건을 목적으로 하지 못한다. 수개의 질권의 순위는 설정의 선후에 의한다.","src":"민법 제331조, 제333조"},{"t":"피담보채권의 범위: 원본, 이자, 위약금, 질권실행의 비용, 질물보존의 비용 및 채무불이행 또는 질물의 하자로 인한 손해배상채권. 다른 약정이 있으면 그에 따른다.","src":"민법 제334조"},{"t":"질권자는 피담보채권을 변제받을 때까지 질물을 유치할 수 있으나 우선권 있는 채권자에게 대항하지 못한다.","src":"민법 제335조"},{"t":"전질: 질권자는 그 권리의 범위 내에서 자기 책임으로 질물을 전질할 수 있고, 전질하지 않았으면 면할 수 있는 불가항력 손해에 대해서도 책임을 진다. 채무자에게 통지하거나 채무자가 승낙하지 않으면 전질로 채무자·보증인·설정자 및 그 승계인에게 대항하지 못한다.","src":"민법 제336조, 제337조"},{"t":"질권자는 변제를 받기 위해 질물을 경매할 수 있고, 정당한 이유가 있으면 감정인 평가에 의해 직접 변제에 충당할 것을 법원에 청구할 수 있다(미리 채무자 및 설정자에게 통지).","src":"민법 제338조, 기출 2023-23, 2025-19"},{"t":"유질계약의 금지: 질권설정자는 채무변제기 전의 계약으로 질권자에게 변제에 갈음하여 질물 소유권을 취득하게 하거나 법률에 정한 방법에 의하지 않고 질물을 처분할 것을 약정하지 못한다.","src":"민법 제339조"},{"t":"질권자는 질물로 변제받지 못한 부분에 한하여 채무자의 다른 재산에서 변제받을 수 있다. 물상보증인은 변제하거나 질물 소유권을 잃은 때 구상권이 있다. 질권은 질물의 멸실·훼손·공용징수로 설정자가 받을 금전 기타 물건에도 행사할 수 있고 지급·인도 전에 압류하여야 한다(물상대위).","src":"민법 제340조, 제341조, 제342조"},{"t":"동산질권에는 선의취득(제249조 내지 제251조), 유치권의 불가분성·과실수취·선관의무·상환청구(제321조 내지 제325조)가 준용된다. 질권은 선의취득의 대상이다.","src":"민법 제343조, 기출 2023-23, 2025-19"},{"t":"권리질권: 재산권을 목적으로 할 수 있으나 부동산의 사용·수익을 목적으로 하는 권리는 제외. 설정방법은 권리의 양도방법에 의한다. 채권증서가 있는 채권질권은 증서의 교부로 효력이 생긴다.","src":"민법 제345조, 제346조, 제347조"},{"t":"저당권부 채권을 질권의 목적으로 하면 저당권등기에 질권의 부기등기를 하여야 효력이 저당권에 미친다.","src":"민법 제348조"},{"t":"지명채권 질권은 설정자가 제3채무자에게 통지하거나 제3채무자가 승낙하여야 제3자에게 대항할 수 있다. 지시채권은 증서에 배서하여 교부, 무기명채권은 증서 교부로 설정한다.","src":"민법 제349조, 제350조, 제351조"},{"t":"질권자는 질권의 목적이 된 채권을 직접 청구할 수 있고, 금전채권이면 자기채권의 한도에서 청구한다. 변제기가 질권자 채권보다 먼저 도래하면 제3채무자에게 변제금액의 공탁을 청구할 수 있다.","src":"민법 제353조"}]},{"머리":"저당권","줄":[{"t":"저당권: 채무자 또는 제3자가 점유를 이전하지 않고 채무의 담보로 제공한 부동산에 대하여 다른 채권자보다 자기채권의 우선변제를 받을 권리.","src":"민법 제356조"},{"t":"근저당: 담보할 채무의 최고액만을 정하고 채무의 확정을 장래에 보류하여 설정할 수 있다. 이자는 최고액 중에 산입한 것으로 본다.","src":"민법 제357조"},{"t":"장래의 조건부 채권, 금전채권의 일부도 저당권의 피담보채권이 될 수 있다.","src":"기출 2021-22, 2023-24"},{"t":"효력의 범위: 저당부동산에 부합된 물건과 종물에 미친다(설정 후에 부속된 것 포함). 법률의 특별 규정 또는 설정행위의 다른 약정이 있으면 제외.","src":"민법 제358조, 기출 2022-25"},{"t":"저당부동산에 대한 압류가 있은 후 설정자가 수취한 과실 또는 수취할 수 있는 과실에도 미친다. 제3취득자에게는 압류 사실을 통지한 후가 아니면 대항하지 못한다.","src":"민법 제359조"},{"t":"피담보채권의 범위: 원본, 이자, 위약금, 채무불이행으로 인한 손해배상, 저당권 실행비용. 지연배상은 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다.","src":"민법 제360조"},{"t":"저당권은 담보한 채권과 분리하여 타인에게 양도하거나 다른 채권의 담보로 하지 못한다(수반성·부종성).","src":"민법 제361조, 기출 2021-22, 2023-24"},{"t":"저당물의 보충: 설정자의 책임 있는 사유로 저당물의 가액이 현저히 감소된 때 원상회복 또는 상당한 담보제공을 청구할 수 있다.","src":"민법 제362조"},{"t":"저당권자는 변제를 받기 위해 저당물의 경매를 청구할 수 있고, 저당물의 소유권을 취득한 제3자도 경매인이 될 수 있다.","src":"민법 제363조"},{"t":"제3취득자: 소유권, 지상권, 전세권을 취득한 제3자는 담보된 채권을 변제하고 저당권의 소멸을 청구할 수 있다. 필요비·유익비를 지출한 때 경매대가에서 우선상환을 받을 수 있다.","src":"민법 제364조, 제367조"},{"t":"공동저당: 동일한 채권의 담보로 수개의 부동산에 저당권을 설정한 경우, 동시배당이면 경매대가에 비례하여 채권 분담. 일부만 먼저 배당하면 그 대가에서 채권 전부를 변제받을 수 있고, 그 부동산의 차순위저당권자는 선순위자가 다른 부동산에서 변제받을 수 있는 금액 한도에서 대위하여 저당권을 행사할 수 있다.","src":"민법 제368조"},{"t":"저당권으로 담보한 채권이 시효 완성 기타 사유로 소멸하면 저당권도 소멸한다. 변제로 피담보채권이 소멸하면 말소등기가 없어도 저당권은 소멸한다.","src":"민법 제369조, 기출 2023-24"},{"t":"저당권에는 방해제거·방해예방(제214조), 유치권의 불가분성(제321조), 질권의 순위(제333조), 질물 이외 재산으로부터의 변제(제340조), 물상보증인 구상권(제341조), 물상대위(제342조)가 준용된다.","src":"민법 제370조"},{"t":"지상권·전세권도 저당권의 목적이 될 수 있다.","src":"민법 제371조, 기출 2023-24"},{"t":"저당권의 물상대위성이 인정된다. 저당권자가 물상대위권을 행사하지 않아 다른 채권자가 수용 보상금 등을 수령한 경우 저당권자는 그 채권자에게 부당이득 반환을 청구할 수 없다.","src":"기출 2021-22, 2022-25"},{"t":"건물 저당권의 효력은 특별한 사정이 없는 한 그 건물의 대지이용권인 지상권에 미친다.","src":"기출 2022-25"},{"t":"저당부동산의 등기부가 멸실되어도 저당권의 효력은 당연히 소멸하지 않는다.","src":"기출 2023-24"},{"t":"후순위 근저당권자의 신청으로 경매가 진행된 경우에도 선순위 근저당권의 피담보채권액은 매수인이 매각대금을 완납한 때 확정된다.","src":"기출 2025-22"}]}],"함정":[{"x":"유치권의 불가분성은 그 목적물이 분할 가능하거나 수개의 물건인 경우에는 적용되지 않는다.","o":"분할 가능하거나 수개의 물건이어도 불가분성이 적용된다.","src":"민법 제321조"},{"x":"장래에 발생할 특정의 조건부 채권을 담보하기 위하여 저당권을 설정할 수 없다.","o":"설정할 수 있다.","src":"기출 2021-22"},{"x":"저당권의 효력은 특별한 사정이 없는 한 저당부동산에 부합한 물건과 종물에 미치지 않는다.","o":"부합물과 종물에 미친다.","src":"민법 제358조"},{"x":"저당물의 소유권을 취득한 제3자는 그 저당물의 경매인이 될 수 없다.","o":"경매인이 될 수 있다.","src":"민법 제363조"},{"x":"저당권은 그 담보한 채권과 분리하여 타인에게 양도하거나 다른 채권의 담보로 할 수 있다.","o":"분리하여 양도하거나 담보로 할 수 없다.","src":"민법 제361조"},{"x":"저당권자가 물상대위권을 행사하지 않아 다른 채권자가 저당 부동산 수용으로 인한 보상금이나 변제공탁금을 수령하여 이득을 얻은 경우, 저당권자는 이를 부당이득으로 반환청구할 수 있다.","o":"부당이득으로 반환청구할 수 없다.","src":"기출 2022-25"},{"x":"질권자는 원칙적으로 전질(轉質)할 수 없다.","o":"자기 책임으로 전질할 수 있다.","src":"민법 제336조"},{"x":"질권자는 피담보채권을 변제받기 위하여 질물을 경매할 수 없다.","o":"경매할 수 있다.","src":"민법 제338조"},{"x":"질권자에게는 정당한 이유가 있더라도 간이변제충당권이 인정될 수 없다.","o":"정당한 이유가 있으면 법원에 청구하여 간이변제충당을 할 수 있다.","src":"민법 제338조"},{"x":"질권자는 원칙적으로 질권설정자에게 질물을 점유하게 할 수 있다.","o":"설정자로 하여금 점유하게 하지 못한다.","src":"민법 제332조"},{"x":"금전채권의 일부는 저당권의 피담보채권이 될 수 없음이 원칙이다.","o":"일부 채권도 피담보채권이 될 수 있다.","src":"기출 2023-24"},{"x":"저당권이 설정된 부동산의 등기부가 멸실하면 그 저당권의 효력은 당연히 소멸한다.","o":"등기부가 멸실해도 저당권은 당연히 소멸하지 않는다.","src":"기출 2023-24"},{"x":"피담보채권이 변제로 소멸하였더라도 저당권말소등기가 되지 않았다면 저당권의 효력은 유지된다.","o":"부종성에 의해 피담보채권이 소멸하면 저당권도 소멸한다.","src":"민법 제369조"},{"x":"저당권은 원칙적으로 피담보채권과 분리하여 타인에게 양도할 수 있다.","o":"분리하여 양도할 수 없다.","src":"민법 제361조"},{"x":"질권자에게는 정당한 이유가 있더라도 간이변제충당권이 인정되지 않는다.","o":"정당한 이유가 있으면 인정된다.","src":"민법 제338조"},{"x":"건물의 신축공사를 도급받은 수급인이 사회통념상 독립한 건물로 볼 수 없는 정착물 을 토지에 설치한 상태에서 공사가 중단된 경우, 그 정착물에 대하여 유치권을 행사 할 수 있다.","o":"독립한 건물이 아닌 정착물에는 유치권을 행사할 수 없다.","src":"기출 2026-23"}]},"계약총론(성립·동시이행·위험부담·제3자를 위한 계약·해제)":{"묶음":[{"머리":"계약의 종류","줄":[{"t":"민법의 전형계약(15종): 증여, 매매, 교환, 소비대차, 사용대차, 임대차, 고용, 도급, 여행, 현상광고, 위임, 임치, 조합, 종신정기금, 화해. 소비자계약과 중개계약은 민법상 전형계약이 아니다.","src":"기출 2025-27, 2026-29"},{"t":"쌍무계약: 매매, 교환, 임대차, 고용, 도급, 여행 등. 증여(부담 없는 증여)는 쌍무계약이 아니고, 현상광고는 편무계약이다.","src":"기출 2023-25, 2024-39"}]},{"머리":"계약의 성립: 청약과 승낙","줄":[{"t":"계약의 청약은 철회하지 못한다(구속력). 청약의 의사표시가 도달하기 전에 청약철회의 의사표시가 먼저 도달하면 청약은 철회된다.","src":"민법 제527조, 기출 2024-38"},{"t":"청약에는 계약의 내용을 결정할 수 있을 정도의 사항이 포함되어야 하고 청약 당시 상대방이 반드시 특정되어 있을 필요는 없다.","src":"기출 2021-26, 2024-38, 2022-26"},{"t":"청약의 의사표시는 상대방에게 도달한 때에 효력이 생기며, 청약자가 통지 발송 후 사망하거나 제한능력자가 되어도 효력을 잃지 않는다.","src":"민법 제111조, 기출 2022-26"},{"t":"광고는 원칙적으로 청약의 유인에 불과하나 내용이 명확·확정적이고 광고주가 광고내용대로 구속되려는 의사가 명백하면 청약으로 볼 수 있다.","src":"기출 2024-38"},{"t":"승낙기간을 정한 청약은 청약자가 그 기간 내에 승낙의 통지를 받지 못한 때 효력을 잃는다. 승낙이 기간 후에 도달해도 보통 그 기간 내에 도달할 수 있는 발송이었으면 청약자는 지체없이 연착 통지를 해야 하고, 하지 않으면 연착되지 않은 것으로 보아 계약이 성립한다.","src":"민법 제528조"},{"t":"승낙기간을 정하지 않은 청약은 청약자가 상당한 기간 내에 승낙의 통지를 받지 못한 때 효력을 잃는다. 연착된 승낙은 청약자가 새 청약으로 볼 수 있다.","src":"민법 제529조, 제530조"},{"t":"격지자 간의 계약은 승낙의 통지를 발송한 때에 성립한다(발신주의).","src":"민법 제531조"},{"t":"청약자의 의사표시나 관습에 의하여 승낙의 통지가 필요하지 않은 경우 계약은 승낙의 의사표시로 인정되는 사실이 있는 때에 성립한다(의사실현).","src":"민법 제532조"},{"t":"교차청약: 당사자 간에 동일한 내용의 청약이 상호 교차된 경우 양 청약이 상대방에게 도달한 때에 계약이 성립한다.","src":"민법 제533조"},{"t":"승낙자가 청약에 조건을 붙이거나 변경을 가하여 승낙하면 그 청약의 거절과 동시에 새로 청약한 것으로 본다(종전 청약은 효력을 잃는다).","src":"민법 제534조"},{"t":"당사자가 의사의 합치가 있어야 한다고 표시한 사항에 합의가 이루어지지 않으면 특별한 사정이 없는 한 계약은 성립하지 않는다. 계약 당사자(매도인·매수인)가 특정되어야 매매계약이 성립한다.","src":"기출 2021-26, 2026-24"},{"t":"분양계약은 낙성계약이므로 계약서 작성일자가 불분명하거나 소급 작성되었다는 사유만으로 성립이 부정되지 않는다.","src":"기출 2026-24"},{"t":"계약체결상의 과실: 목적이 불능한 계약을 체결할 때 그 불능을 알았거나 알 수 있었던 자는 상대방이 계약의 유효를 믿었음으로 인하여 받은 손해(신뢰이익)를 배상한다. 배상액은 이행이익을 넘지 못한다. 상대방이 그 불능을 알았거나 알 수 있었으면 적용하지 않는다.","src":"민법 제535조"}]},{"머리":"동시이행의 항변권","줄":[{"t":"쌍무계약의 당사자 일방은 상대방이 채무이행을 제공할 때까지 자기의 채무이행을 거절할 수 있다. 상대방의 채무가 변제기에 있지 않으면 거절할 수 없다.","src":"민법 제536조"},{"t":"먼저 이행할 의무가 있는 당사자도 상대방의 이행이 곤란할 현저한 사유가 있으면 동시이행 항변을 할 수 있다. 선이행의무자가 이행하지 않는 동안 상대방 채무의 변제기가 도래하면 동시이행 항변을 할 수 있다.","src":"민법 제536조, 기출 2021-27"},{"t":"동시이행의 항변권을 포기할 수 있다. 항변권이 있는 채무자는 이행기에 이행하지 않아도 이행지체 책임을 지지 않는다.","src":"기출 2021-27"},{"t":"수령지체에 빠진 당사자도 그 후 상대방이 이행제공을 다시 하지 않고 이행을 청구하면 동시이행 항변권을 행사할 수 있다.","src":"기출 2021-27"},{"t":"동시이행 관계가 인정되는 것: 계약 해제로 인한 당사자 쌍방의 원상회복의무(제549조), 계약이 무효·취소된 경우의 상호 급부 반환의무, 임대차 종료 후 목적물 반환의무와 연체차임 등을 공제한 보증금 반환의무, 전세권 소멸 시 목적물 인도·등기 말소서류 교부와 전세금 반환(제317조), 변제와 영수증 교부, 구분소유적 공유관계 해소 시 지분이전등기의무 상호간, 수급인의 하자보수·손해배상의무와 도급인의 보수지급의무, 근저당권이 등기된 부동산 매매에서 매도인의 이전등기·근저당 말소의무와 매수인의 대금지급의무, 이행기가 같은 상대부담 있는 증여에서 증여이행과 부담이행.","src":"기출 2022-27, 2023-26, 2024-36, 2026-27"},{"t":"동시이행 관계가 아닌 것: 피담보채무의 변제와 저당권설정등기 말소(변제가 선이행), 채권증서 반환과 변제, 공사도급계약상 도급인의 공사대금 지급채무와 수급인의 지체상금 지급채무.","src":"기출 2022-27, 2023-26, 2024-36, 2026-27"},{"t":"동시이행 관계가 아닌 것(2025-26): 토지거래허가 신청절차 협력의무와 매매대금 지급의무, 임차목적물 반환의무와 권리금 회수방해 손해배상의무, 임차권등기명령에 의한 등기 말소의무와 임대차보증금 반환의무, 경매 무효로 인한 배당금 반환채무와 낙찰자의 소유권이전등기 말소의무.","src":"기출 2025-26"}]},{"머리":"위험부담","줄":[{"t":"채무자위험부담주의: 쌍무계약의 일방 채무가 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때 채무자는 상대방의 이행(반대급부)을 청구하지 못한다.","src":"민법 제537조"},{"t":"채권자의 책임 있는 사유로 이행할 수 없게 된 때, 또는 채권자의 수령지체 중 쌍방의 책임 없는 사유로 이행할 수 없게 된 때에는 채무자는 반대급부를 청구할 수 있다. 채무자가 자기 채무를 면함으로써 얻은 이익은 채권자에게 상환한다.","src":"민법 제538조"},{"t":"2023-27 정리: 쌍방 무책 불능(ㄱ)은 반대급부 청구 불가, 채권자 책임 불능(ㄴ)은 청구 가능, 수령지체 중 쌍방 무책 불능(ㄷ)은 청구 가능. 정답 4.","src":"기출 2023-27"},{"t":"매수인의 수령지체 중 목적물이 소실되어도 매도인은 매수인에게 매매대금의 지급을 청구할 수 있다. 매수인은 잔금을 모두 지급하면 매도인이 받는 화재보험금에 대해 대상청구권을 행사할 수 있다.","src":"기출 2025-25"}]},{"머리":"제3자를 위한 계약","줄":[{"t":"계약에 의하여 당사자 일방이 제3자에게 이행할 것을 약정하면 제3자는 채무자(낙약자)에게 직접 이행을 청구할 수 있다. 제3자의 권리는 그 제3자가 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때에 생긴다.","src":"민법 제539조"},{"t":"채무자는 상당한 기간을 정하여 제3자에게 향수 여부의 확답을 최고할 수 있고, 확답을 받지 못하면 제3자가 거절한 것으로 본다.","src":"민법 제540조"},{"t":"제3자의 권리가 생긴 후에는 당사자는 이를 변경·소멸시키지 못한다(권리 발생 전 소멸 가능 특약이 있으면 발생 후에도 가능).","src":"민법 제541조, 기출 2024-31"},{"t":"채무자(낙약자)는 계약(요약자와의 보상관계)에 기한 항변으로 제3자에게 대항할 수 있으나, 요약자와 제3자 사이의 법률관계(대가관계)에 기한 항변으로는 대항하지 못한다.","src":"민법 제542조, 기출 2021-25"},{"t":"요약자는 제3자의 동의 없이 낙약자의 채무불이행을 이유로 계약을 해제할 수 있고, 수익의 의사표시 후에도 해제할 수 있다. 제3자(수익자)는 해제권이 없다.","src":"기출 2021-25, 2024-31, 2026-26, 2025-28"},{"t":"낙약자의 요약자에 대한 행위 자체가 불법행위인 경우 수익자는 그 불법행위를 이유로 손해배상을 청구할 수 없다.","src":"기출 2024-31, 2026-26"},{"t":"제3자에게 대금을 모두 지급한 후 계약이 해제되면 특별한 사정이 없는 한 요약자는 제3자를 상대로 원상회복을 청구할 수 없다.","src":"기출 2025-28"},{"t":"채무자와 인수인 사이의 중첩적(병존적) 채무인수는 제3자를 위한 계약이다. 계약당사자의 채권에 관하여 제3자의 채무를 면제하는 계약도 제3자를 위한 계약에 준한다.","src":"기출 2021-25, 2026-26"}]},{"머리":"채무인수","줄":[{"t":"채권자와 제3자의 계약에 의한 채무인수: 제3자는 채권자와의 계약으로 채무를 인수하여 채무자의 채무를 면하게 할 수 있다. 채무의 성질이 인수를 허용하지 않으면 제외. 이해관계 없는 제3자는 채무자의 의사에 반하여 인수하지 못한다.","src":"민법 제453조"},{"t":"채무자와 제3자의 계약에 의한 채무인수는 채권자의 승낙에 의하여 효력이 생긴다. 승낙·거절의 상대방은 채무자나 제3자이다.","src":"민법 제454조"},{"t":"제3자나 채무자는 상당한 기간을 정하여 승낙 여부의 확답을 최고할 수 있고, 채권자가 기간 내 확답을 발송하지 않으면 거절한 것으로 본다.","src":"민법 제455조"},{"t":"채권자의 승낙이 있을 때까지 당사자는 채무인수를 철회·변경할 수 있다. 승낙은 다른 의사표시가 없으면 채무를 인수한 때에 소급하되 제3자의 권리를 침해하지 못한다.","src":"민법 제456조, 제457조"},{"t":"인수인은 전채무자의 항변사유로 채권자에게 대항할 수 있다. 전채무자의 채무에 대한 보증이나 제3자가 제공한 담보는 채무인수로 소멸하나 보증인·제3자가 동의한 때는 제외.","src":"민법 제458조, 제459조"}]},{"머리":"계약의 해제·해지","줄":[{"t":"해제·해지는 상대방에 대한 의사표시로 하며 철회하지 못한다.","src":"민법 제543조"},{"t":"이행지체와 해제: 상당한 기간을 정하여 이행을 최고하고 그 기간 내에 이행하지 않으면 해제할 수 있다. 채무자가 미리 이행하지 않을 의사를 표시한 경우(이행거절)에는 최고가 필요 없다.","src":"민법 제544조"},{"t":"정기행위: 일정한 시일·기간 내에 이행하지 않으면 계약의 목적을 달성할 수 없는 경우 그 시기에 이행하지 않으면 최고 없이 해제할 수 있다.","src":"민법 제545조"},{"t":"이행불능: 채무자의 책임 있는 사유로 이행이 불능하게 되면 채권자는 최고 없이 계약을 해제할 수 있다(경과실로 인한 불능도 포함).","src":"민법 제546조, 기출 2023-29"},{"t":"일부 이행불능에서 나머지 부분만으로 계약의 목적을 달성할 수 있으면 그 불능 부분에 대한 일부해제가 가능하다.","src":"기출 2022-22"},{"t":"당사자 일방 또는 쌍방이 수인인 경우 해제·해지는 전원으로부터 또는 전원에 대하여 하여야 한다. 해제권이 당사자 1인에 대하여 소멸하면 다른 당사자에 대하여도 소멸한다.","src":"민법 제547조"},{"t":"해제의 효과: 각 당사자는 상대방에 대하여 원상회복의무가 있으나 제3자의 권리를 해하지 못한다. 반환할 금전에는 받은 날부터 이자를 가산한다(매도인이 선의여도 마찬가지).","src":"민법 제548조, 기출 2022-22"},{"t":"해제의 소급효로부터 보호되는 제3자는 해제 전에 새로운 이해관계를 맺고 등기·인도 등으로 완전한 권리를 취득한 자이다. 압류채권자, 대항요건을 갖춘 임차인, 저당권설정등기를 한 자, 소유권이전청구권 보전 가등기를 한 자는 보호되고, 아직 등기하지 않은 매수인은 보호되지 않는다.","src":"기출 2022-22, 2023-28"},{"t":"원상회복의무에는 동시이행 규정을 준용한다.","src":"민법 제549조"},{"t":"해지는 계약을 장래에 대하여 실효시킨다. 해지·해제는 손해배상 청구에 영향을 미치지 않는다.","src":"민법 제550조, 제551조"},{"t":"해제권 행사의 기간을 정하지 않은 때 상대방은 상당한 기간을 정하여 해제권 행사 여부의 확답을 최고할 수 있고, 기간 내에 해제통지를 받지 못하면 해제권은 소멸한다(해제된 것으로 보는 것이 아님).","src":"민법 제552조"},{"t":"해제권자의 고의·과실로 목적물이 현저히 훼손되거나 반환할 수 없게 된 때, 가공·개조로 다른 종류의 물건이 된 때에는 해제권이 소멸한다.","src":"민법 제553조"},{"t":"합의해제의 경우 특별한 사정이 없는 한 채무불이행으로 인한 손해배상을 청구할 수 없고, 별도 약정이 없으면 받은 대금에 이자를 가산할 필요가 없다. 합의해제 후 목적물을 선의로 매수해 이전등기를 한 제3자는 보호된다.","src":"기출 2022-22, 2025-29"},{"t":"소를 제기하여 해제권을 행사한 후 소를 취하하더라도 이미 도달한 해제의 효력은 소멸하지 않는다.","src":"민법 제543조, 기출 2021-24"}]}],"함정":[{"x":"소제기로 해제권을 행사한 후 그 소송을 취하하면 해제권 행사의 효력은 소멸한다.","o":"해제는 철회할 수 없어 효력이 소멸하지 않는다.","src":"민법 제543조"},{"x":"채무자와 인수인 사이의 계약으로 체결되는 병존적 채무인수는 제3자를 위한 계약이 아니다.","o":"제3자를 위한 계약이다.","src":"기출 2021-25"},{"x":"수익의 의사표시를 한 제3자는 낙약자에게 직접 그 이행을 청구할 수 없다.","o":"직접 이행을 청구할 수 있다.","src":"민법 제539조"},{"x":"제3자의 수익의 의사표시 후에 낙약자의 채무불이행이 있으면 요약자는 계약을 해제 할 수 없다.","o":"요약자는 해제할 수 있다.","src":"기출 2021-25"},{"x":"낙약자는 요약자와 제3자 사이의 법률관계에 기한 항변으로 제3자에게 대항할 수 있다.","o":"대가관계의 항변으로는 대항하지 못한다.","src":"민법 제542조"},{"x":"당사자 간에 동일한 내용의 청약이 상호교차된 경우에는 양 청약이 발송된 때에 계약이 성립한다.","o":"양 청약이 상대방에게 도달한 때 성립한다.","src":"민법 제533조"},{"x":"수령지체에 빠진 당사자는 그 후 상대방이 이행제공을 다시 하지 않고 이행을 청구한 경우에 동시이행의 항변권을 행사할 수 없다.","o":"행사할 수 있다.","src":"기출 2021-27"},{"x":"매매계약이 채무불이행을 이유로 해제된 경우, 매도인이 선의인 때에는 수령한 매매대금 반환시 이자를 가산할 필요가 없다.","o":"선의여도 받은 날부터 이자를 가산한다.","src":"민법 제548조"},{"x":"청약은 상대방 있는 의사표시이므로 청약 당시에 상대방이 특정되어 있어야 한다.","o":"청약 당시 상대방이 특정되어 있을 필요는 없다.","src":"기출 2022-26"},{"x":"청약의 의사표시는 상대방에게 발송한 때에 효력이 생긴다.","o":"상대방에게 도달한 때에 효력이 생긴다.","src":"민법 제111조"},{"x":"청약자가 그 통지를 발송한 후 사망하거나 제한능력자가 되면 그 의사표시는 효력을 잃는다.","o":"효력에 영향이 없다.","src":"민법 제111조"},{"x":"격지자 간 계약의 성립시기는 승낙의 통지가 상대방에게 도달한 때이다.","o":"승낙의 통지를 발송한 때이다.","src":"민법 제531조"},{"x":"계약 당시 甲이 분할할 수 없다는 사실을 알고 있었다면, 乙은 그 사실에 관하여 악의이더라도 甲에 대하여 민법 제535조의 계약체결상의 과실책임을 물을 수 있다.","o":"상대방이 불능을 알았거나 알 수 있었으면 제535조가 적용되지 않는다.","src":"민법 제535조"},{"x":"甲이 민법 제535조의 계약체결상의 과실책임을 부담하는 경우, 乙은 甲에 대하여 이행이익을 초과하는 손해도 청구할 수 있다.","o":"배상액은 이행이익(계약이 유효함으로 생길 이익액)을 넘지 못한다.","src":"민법 제535조"},{"x":"제3자를 위한 계약이 유상ㆍ쌍무계약인 경우, 요약자는 낙약자의 채무불이행을 이유로 제3자의 동의없이 계약을 해제할 수 없다.","o":"제3자의 동의 없이 해제할 수 있다.","src":"기출 2026-26"},{"x":"해제권의 행사기간을 정하지 아니한 경우, 상대방이 해제권자에게 상당한 기간을 정하여 최고하였으나 그 기간 내에 해제통지를 받지 못하면 해제된 것으로 본다.","o":"해제권이 소멸한다.","src":"민법 제552조"},{"x":"청약에 대하여 변경을 가하여 승낙하면, 청약을 거절한 것이고 그 승낙의 의사표시를 새로운 청약으로 볼 수 없다.","o":"청약의 거절과 동시에 새로운 청약으로 본다.","src":"민법 제534조"},{"x":"乙의 수령지체 중에 X가 소실된 경우라도 甲은 乙에게 매매대금의 지급을 청구할 수 없다.","o":"청구할 수 있다.","src":"민법 제538조"},{"x":"만약 乙이 잔금 전액을 甲에게 지급하더라도 甲이 화재사고로 인해 지급받게 되는 화재보험금에 대해서는 대상청구권을 행사할 수 없다.","o":"대상청구권을 행사할 수 있다.","src":"기출 2025-25"},{"x":"乙의 귀책사유로 매매대금의 지급이 지체된 경우, 丙은 乙에게 이행을 최고한 후 매매계약을 해제할 수 있다.","o":"해제권은 요약자 甲이 가지며 수익자 丙은 해제할 수 없다.","src":"기출 2025-28"},{"x":"매매계약 체결 당시에 매매계약의 당사자인 매도인과 매수인이 누구인지가 구체적으로 특정되지 않더라도 특별한 사정이 없는 한 매매계약이 성립할 수 있다.","o":"당사자가 특정되어야 성립한다.","src":"기출 2026-24"},{"x":"제3자를 위한 계약에 있어서 낙약자의 행위자체가 요약자에게 불법행위가 되는 경우에는 특별한 사정이 없는 한 수익자는 손해배상의 청구를 할 수 있다.","o":"수익자는 손해배상을 청구할 수 없다.","src":"기출 2024-31, 2026-26"}]},"매매·교환":{"묶음":[{"머리":"매매의 성립과 일방예약","줄":[{"t":"매매: 당사자 일방이 재산권을 상대방에게 이전할 것을 약정하고 상대방이 그 대금을 지급할 것을 약정함으로써 효력이 생긴다(낙성·쌍무·유상·불요식 계약).","src":"민법 제563조"},{"t":"매매의 일방예약은 상대방(예약권리자)이 매매를 완결할 의사를 표시하는 때에 매매의 효력이 생긴다. 예약완결권은 형성권이다.","src":"민법 제564조, 기출 2021-30"},{"t":"완결의 의사표시 기간을 정하지 않은 때 예약자는 상당한 기간을 정하여 완결 여부의 확답을 상대방에게 최고할 수 있고, 그 기간 내에 확답을 받지 못하면 예약은 효력을 잃는다.","src":"민법 제564조"},{"t":"예약완결권의 행사기간은 제척기간이다. 당사자가 기간을 약정하지 않았으면 예약이 성립한 때부터 10년 내에 행사하여야 하고(1년이 아님), 약정한 기간이 10년을 넘어도 그 약정이 유효하다. 제척기간 도과 여부는 법원의 직권조사 사항이다.","src":"기출 2021-30, 2023-31"},{"t":"매매의 예약은 장래 본계약 체결을 내용으로 하는 계약이며, 예약 성립 후 본계약 성립 전에는 일방이 예약의 주요내용을 변경할 수 없다. 예약 성립 후 완결의 의사표시 전에 목적물이 멸실되어 이전할 수 없으면 예약완결권을 행사할 수 없다.","src":"기출 2023-31, 2021-30"}]},{"머리":"계약금과 해약금","줄":[{"t":"해약금: 매매 당사자 일방이 계약 당시 금전 기타 물건을 계약금, 보증금 등의 명목으로 교부한 때, 다른 약정이 없으면 당사자 일방이 이행에 착수할 때까지 교부자는 이를 포기하고 수령자는 그 배액을 상환하여 계약을 해제할 수 있다. 제551조(해제와 손해배상)는 적용하지 않는다.","src":"민법 제565조"},{"t":"해약금 해제는 상대방에게 손해배상을 청구할 수 없다.","src":"민법 제565조, 기출 2023-32, 2025-30"},{"t":"계약금 포기에 의한 해제권은 당사자의 합의로 배제할 수 있다.","src":"기출 2023-32"},{"t":"이행의 착수란 단순한 이행 준비로는 부족하나 계약내용에 들어맞는 이행제공의 정도에 이를 필요는 없다. 중도금 지급 외에 이행에 필요한 전제행위도 포함될 수 있다.","src":"기출 2026-25, 2022-29"},{"t":"당사자 일방이 이행에 착수하면 그 상대방은 물론 이행에 착수한 당사자 본인도 해약금으로 해제할 수 없다(매수인이 중도금을 지급한 경우 매수인도 해제 불가).","src":"기출 2023-32, 2024-33, 2026-25"},{"t":"매도인이 해약금 해제 의사표시를 하고 배액을 수령할 것을 고지하면 매수인은 이행기 전이라도 이행에 착수하여 해제권을 소멸시킬 수 없다. 배액을 현실로 제공하면 족하고 상대방이 수령하지 않아도 공탁은 필요 없다.","src":"기출 2022-29"},{"t":"계약금 일부만 지급된 경우 매도인이 해약금으로 해제하려면 실제 받은 금액이 아니라 약정 계약금의 배액을 상환하여야 한다(1천만원 약정에 300만원 수령 시 2천만원).","src":"기출 2024-33"},{"t":"토지거래허가를 받지 않아 유동적 무효인 계약에서도 계약금계약에 기한 해제권을 행사할 수 있다.","src":"기출 2022-29"},{"t":"계약금은 위약금 특약이 없으면 당연히 손해배상액의 예정이 아니다. 「대금불입 불이행 시 계약은 자동무효, 이미 불입된 금액은 반환하지 않는다」고 합의한 경우 계약금은 위약금의 성질을 가진다.","src":"기출 2026-25, 2022-29"},{"t":"계약이 매수인의 귀책사유로 해제되어도 위약금 특약이 없으면 계약금은 당연히 매도인에게 귀속되지 않는다.","src":"기출 2024-33"}]},{"머리":"매매의 효력","줄":[{"t":"매도인은 매매 목적 권리를 이전하여야 하고 매수인은 대금을 지급하여야 한다. 쌍방의무는 특별한 약정이나 관습이 없으면 동시에 이행하여야 한다.","src":"민법 제568조"},{"t":"매매계약에 관한 비용은 당사자 쌍방이 균분하여 부담한다. 다른 유상계약에 준용한다.","src":"민법 제566조, 제567조"},{"t":"매매 당사자 일방에 대한 의무이행의 기한이 있는 때 상대방의 의무이행에 대하여도 동일한 기한이 있는 것으로 추정한다.","src":"민법 제585조"},{"t":"목적물 인도와 동시에 대금을 지급할 경우 그 인도장소에서 지급하여야 한다(채권자 주소지가 아님).","src":"민법 제586조"},{"t":"과실의 귀속: 매매계약 후에도 인도하지 않은 목적물에서 생긴 과실은 매도인에게 속한다. 매수인은 목적물을 인도받은 날부터 대금의 이자를 지급하여야 한다(대금 지급에 기한이 있으면 제외). 이행기가 도래하고 매수인이 대금을 완납하면 인도 전이라도 그 이후의 과실은 매수인에게 귀속한다.","src":"민법 제587조, 기출 2026-28"},{"t":"권리주장자가 있어 매수인이 권리의 전부나 일부를 잃을 염려가 있으면 매수인은 그 위험의 한도에서 대금 지급을 거절할 수 있다. 매도인이 상당한 담보를 제공하면 거절할 수 없다. 매도인은 대금의 공탁을 청구할 수 있다.","src":"민법 제588조, 제589조"},{"t":"매도인이 말소할 의무를 지는 근저당권을 말소하지 못하고 있으면 매수인은 그 위험의 한도에서 대금 지급을 거절할 수 있다.","src":"기출 2026-28"},{"t":"소유권이전등기청구권 보전의 가등기를 해 준 것만으로는 매도인이 권리이전의무를 전부 이행한 것이 아니다.","src":"기출 2026-28"}]},{"머리":"매도인의 담보책임","줄":[{"t":"타인 권리의 매매: 매도인은 그 권리를 취득하여 매수인에게 이전하여야 한다. 매매계약은 유효하다(원시적 불능으로 무효가 아님).","src":"민법 제569조, 기출 2024-40"},{"t":"이전할 수 없는 때 매수인은 계약을 해제할 수 있다. 계약 당시 권리가 매도인에게 속하지 않음을 안 매수인은 손해배상을 청구하지 못한다.","src":"민법 제570조"},{"t":"선의의 매도인은 손해를 배상하고 계약을 해제할 수 있다. 매수인이 악의이면 매도인은 이전할 수 없음을 통지하고 해제할 수 있다. 계약 당시 권리가 자기에게 속하지 않음을 알고 있던 악의 매도인은 해제할 수 없다.","src":"민법 제571조, 기출 2024-40"},{"t":"권리의 일부가 타인에게 속한 경우: 매수인은 그 부분의 비율로 대금 감액을 청구할 수 있고, 잔존 부분만이면 매수하지 않았을 선의의 매수인은 계약 전부를 해제할 수 있으며, 선의의 매수인은 손해배상도 청구할 수 있다. 권리 행사 기간은 선의 매수인은 사실을 안 날부터, 악의 매수인은 계약한 날부터 1년.","src":"민법 제572조, 제573조"},{"t":"수량을 지정한 매매의 목적물 부족, 매매목적물 일부가 계약 당시 이미 멸실된 경우, 매수인이 그 부족 또는 멸실을 알지 못한 때 제572조·제573조를 준용한다.","src":"민법 제574조"},{"t":"제한물권이 있는 경우(지상권, 지역권, 전세권, 질권, 유치권): 매수인이 알지 못한 때 계약의 목적을 달성할 수 없는 경우에 한하여 해제할 수 있고 기타의 경우에는 손해배상만 청구한다. 매수인이 안 날부터 1년 내 행사.","src":"민법 제575조"},{"t":"저당권·전세권의 행사로 매수인이 소유권을 취득할 수 없거나 잃은 때 매수인은 계약을 해제할 수 있다. 출재로 소유권을 보존한 때 상환을 청구하고 손해배상도 청구할 수 있다.","src":"민법 제576조"},{"t":"경매: 경락인은 채무자에게 계약의 해제 또는 대금감액을 청구할 수 있고, 채무자가 무자력이면 배당받은 채권자에게 대금의 반환을 청구할 수 있다. 권리의 하자에 대해서만 담보책임이 있고 물건의 하자에는 적용하지 않는다.","src":"민법 제578조, 제580조"},{"t":"채권 매매: 채권의 매도인이 채무자의 자력을 담보한 때 계약 당시의 자력을 담보한 것으로 추정. 변제기 미도래 채권은 변제기의 자력을 담보한 것으로 추정.","src":"민법 제579조"},{"t":"하자담보책임(제580조): 목적물에 하자가 있는 때 제575조 제1항을 준용한다. 매수인이 하자 있음을 알았거나 과실로 알지 못한 때는 제외.","src":"민법 제580조"},{"t":"종류매매: 종류로 지정한 경우에도 특정된 목적물에 하자가 있으면 제580조를 준용하며 매수인은 해제·손해배상 대신 하자 없는 물건(완전물급부)을 청구할 수 있다.","src":"민법 제581조"},{"t":"하자담보 권리는 매수인이 그 사실을 안 날부터 6월 내에 행사하여야 한다(해제·손해배상).","src":"민법 제582조"},{"t":"담보책임과 동시이행: 제572조 내지 제575조, 제580조, 제581조의 경우 제536조를 준용한다. 매도인의 완전물급부의무와 매수인의 하자 있는 물건 반환의무는 동시이행 관계이다.","src":"민법 제583조, 기출 2022-28"},{"t":"담보책임 면제 특약을 해도 매도인이 알고 고지하지 아니한 사실과 제3자에게 권리를 설정 또는 양도한 행위는 책임을 면하지 못한다. 담보책임 규정은 임의규정이다.","src":"민법 제584조, 기출 2022-30"},{"t":"하자담보책임은 채무불이행책임과 달리 무과실책임이다. 건축 목적 매수 토지가 법적 제한으로 건축허가를 받을 수 없으면 하자에 해당한다. 하자로 인한 확대손해 배상은 매도인의 귀책사유가 필요하다.","src":"기출 2022-28, 2023-33"},{"t":"하자담보에 기한 매수인의 손해배상청구권도 소멸시효의 대상이 되며, 매수인이 과실로 하자를 알지 못한 경우 매도인은 책임을 지지 않는다. 경매에서는 물건의 하자에 대한 담보책임을 물을 수 없다.","src":"기출 2023-33, 2022-30"},{"t":"매목적물의 하자가 법률행위 내용 중요부분의 착오에 해당하면 하자담보책임 성립과 상관없이 착오 취소가 가능하다.","src":"기출 2022-30"}]},{"머리":"환매","줄":[{"t":"환매: 매도인이 매매계약과 동시에 환매할 권리를 보류한 때 영수한 대금과 매수인이 부담한 매매비용을 반환하고 목적물을 환매할 수 있다. 환매대금에 특약이 있으면 그에 따른다.","src":"민법 제590조"},{"t":"목적물의 과실과 대금의 이자는 특별한 약정이 없으면 상계한 것으로 본다.","src":"민법 제590조"},{"t":"환매기간: 부동산 5년, 동산 3년을 넘지 못한다. 환매기간을 정한 때는 다시 연장하지 못한다. 정하지 않으면 부동산 5년, 동산 3년.","src":"민법 제591조"},{"t":"매매의 목적물이 부동산인 경우 매매등기와 동시에 환매권 보류를 등기하면 제3자에 대하여 효력이 있다.","src":"민법 제592조"},{"t":"매도인의 채권자가 매도인을 대위하여 환매하려는 때 매수인은 법원이 선정한 감정인의 평가액에서 매도인이 반환할 금액을 공제한 잔액으로 매도인의 채무를 변제하고 잉여를 매도인에게 지급하여 환매권을 소멸시킬 수 있다.","src":"민법 제593조"},{"t":"매도인이 기간 내에 대금과 매매비용을 제공하지 않으면 환매할 권리를 잃는다. 매수인·전득자가 목적물에 비용을 지출한 때 매도인은 제203조에 의해 상환한다.","src":"민법 제594조"},{"t":"공유지분의 환매: 공유자 1인이 환매권을 보류하고 지분을 매도한 후 분할이나 경매가 있으면 매도인은 매수인이 받은 또는 받을 부분이나 대금에 대하여 환매권을 행사할 수 있다. 통지하지 않은 매수인은 분할·경매로 매도인에게 대항하지 못한다.","src":"민법 제595조"}]},{"머리":"교환","줄":[{"t":"교환: 당사자 쌍방이 금전 이외의 재산권을 상호 이전할 것을 약정함으로써 효력이 생긴다(낙성·불요식 계약).","src":"민법 제596조"},{"t":"보충금: 재산권 이전과 금전의 보충지급을 약정한 때 그 금전에는 매매대금 규정을 준용한다.","src":"민법 제597조"},{"t":"교환에는 매매 규정이 준용되어 타인 권리를 교환한 당사자는 그 권리를 취득하여 이전하여야 하고, 쌍방 의무는 동시에 이행하며, 비용은 균분하여 부담한다.","src":"민법 제567조, 기출 2022-32"}]}],"함정":[{"x":"매수인이 대금을 전부 변제하였더라도 목적물이 인도되지 않았다면 그 변제시점 이후의 과실은 매도인에게 귀속된다.","o":"대금 완납 후의 과실은 매수인에게 귀속된다.","src":"기출 2026-28"},{"x":"물건의 하자로 인한 확대손해의 배상책임은 매도인의 귀책사유를 요하지 않는다.","o":"확대손해 배상책임에는 매도인의 귀책사유가 필요하다.","src":"기출 2022-28"},{"x":"“대금불입 불이행시 계약은 자동무효가 되고 이미 불입된 금액은 일체 반환하지 않는다” 고 합의된 경우 계약금은 위약금의 성질을 갖지 못한다.","o":"위약금의 성질을 가진다.","src":"기출 2022-29"},{"x":"甲이 계약금계약에 기해 해제의 의사를 표시하고 계약금의 배액을 수령할 것을 고지한 경우, 乙은 이행기 전이라도 이행에 착수하여 매도인의 해제권을 소멸시킬 수 있다.","o":"이행기 전의 이행착수로 소멸시킬 수 없다.","src":"기출 2022-29"},{"x":"甲이 계약금의 배액에 대한 이행을 제공하였으나 乙이 이를 수령하지 않는 경우, 甲은 공탁하지 않으면 계약을 해제할 수 없다.","o":"공탁하지 않아도 해제할 수 있다.","src":"기출 2022-29"},{"x":"乙의 이행의 착수는 중도금의 지급과 같이 채무 자체가 일부 또는 전부 이행되는 경우만을 의미한다.","o":"이행에 필요한 전제행위도 이행의 착수에 포함될 수 있다.","src":"기출 2022-29"},{"x":"매도인의 담보책임에 관한 규정은 강행규정으로 당사자는 합의를 통하여 이를 배제하지 못한다.","o":"임의규정이어서 특약으로 배제할 수 있다(제584조의 예외 있음).","src":"민법 제584조"},{"x":"교환은 당사자 쌍방이 금전 이외의 재산권을 서로 이전할 것을 내용으로 하므로 요식 계약이다.","o":"불요식·낙성계약이다.","src":"민법 제596조"},{"x":"당사자 사이에 약정한 매매예약완결권의 행사기간이 12년인 경우, 그 매매예약완결권은 10년의 제척기간의 경과로 소멸한다.","o":"약정한 12년이 적용된다.","src":"기출 2023-31"},{"x":"경매목적물에 법률상의 장애가 있는 경우, 매도인은 매수인에 대하여 하자담보책임을 진다.","o":"경매에서는 물건의 하자에 대한 담보책임이 없다.","src":"민법 제580조"},{"x":"매매대금을 목적물의 인도와 동시에 지급해야 하는 경우, 매매대금 채권자의 주소지에서 대금을 지급하여야 한다.","o":"인도장소에서 지급한다.","src":"민법 제586조"},{"x":"해약금 약정에 따라 매매계약이 해제된 경우에도 그 해제로 인한 손해배상을 청구할 수 있다.","o":"손해배상을 청구할 수 없다.","src":"민법 제565조"},{"x":"수량지정 매매에 있어서 매도인의 담보책임에 기한 매수인의 대금감액청구권은 매수인이 악의인 경우에는 인정되지 않는다.","o":"출제 오답(바른 문장 미확인, 제574조는 매수인이 부족을 알지 못한 때를 전제로 한다).","src":"기출 2026-28"},{"x":"부동산의 환매기간을 5년으로 정한 경우, 당사자는 그 기간을 연장할 수 있다.","o":"환매기간은 다시 연장하지 못한다.","src":"민법 제591조"}]},"증여":{"묶음":[{"머리":"증여의 성립","줄":[{"t":"증여: 당사자 일방이 무상으로 재산을 상대방에 수여하는 의사를 표시하고 상대방이 이를 승낙함으로써 효력이 생긴다(낙성·무상·편무·불요식 계약). 상대방의 승낙이 필요하다.","src":"민법 제554조"},{"t":"증여계약서가 작성되어야 성립하는 것이 아니다. 서면이 없으면 해제할 수 있을 뿐이다.","src":"기출 2023-30"},{"t":"타인 소유의 부동산도 증여의 목적이 될 수 있다.","src":"기출 2021-33"},{"t":"서면상 형식은 매매계약이어도 경위상 증여의 의사를 표시한 것이면 서면에 의한 증여로 인정된다. 증여 의사가 표시된 서면은 증여계약 존속 중 작성하면 그때부터 서면에 의한 증여가 된다.","src":"기출 2022-31, 2021-33"}]},{"머리":"증여의 해제","줄":[{"t":"서면에 의하지 아니한 증여: 증여의 의사가 서면으로 표시되지 아니한 경우 각 당사자는 이를 해제할 수 있다.","src":"민법 제555조"},{"t":"수증자의 행위: 증여자 또는 그 배우자나 직계혈족에 대한 범죄행위가 있는 때, 증여자에 대하여 부양의무가 있는데 이행하지 않는 때 증여자는 해제할 수 있다. 해제원인을 안 날부터 6월을 경과하거나 증여자가 수증자에 대하여 용서의 의사를 표시한 때에는 해제권이 소멸한다.","src":"민법 제556조"},{"t":"증여자의 재산상태 변경: 증여계약 후 증여자의 재산상태가 현저히 변경되고 그 이행으로 생계에 중대한 영향을 미칠 경우 증여자는 해제할 수 있다.","src":"민법 제557조"},{"t":"위 세 가지 해제는 이미 이행한 부분에 대하여는 영향을 미치지 아니한다(이미 이행한 부분은 반환 청구 불가).","src":"민법 제558조"},{"t":"서면에 의하지 않은 증여라도 이행이 완료된 부분은 해제할 수 없다. 서면에 의하지 않음을 이유로 한 해제권에는 제척기간이 적용되지 않는다.","src":"민법 제558조, 기출 2024-35, 2025-31"}]},{"머리":"증여자의 담보책임과 특수 증여","줄":[{"t":"증여자는 목적물 또는 권리의 하자나 흠결에 대하여 책임을 지지 않는다. 증여자가 하자나 흠결을 알고 수증자에게 고지하지 아니한 때에는 책임을 진다.","src":"민법 제559조"},{"t":"상대부담 있는 증여는 증여자가 그 부담의 한도에서 매도인과 같은 담보책임이 있다.","src":"민법 제559조"},{"t":"정기증여: 정기의 급여를 목적으로 한 증여는 증여자 또는 수증자의 사망으로 인하여 효력을 잃는다.","src":"민법 제560조"},{"t":"부담부증여: 상대부담 있는 증여에는 증여 규정 외에 쌍무계약에 관한 규정(동시이행, 위험부담, 해제)을 적용한다. 수증자가 부담을 이행하지 않으면 이미 이행한 증여 부분도 해제하고 원상회복을 구할 수 있다. 수증자가 부담의 이행을 완료한 경우 증여자는 서면에 의하지 않음을 이유로 해제할 수 없다.","src":"민법 제561조, 기출 2021-33, 2024-35, 2025-31"},{"t":"사인증여: 증여자의 사망으로 인하여 효력이 생길 증여에는 유증에 관한 규정을 준용한다.","src":"민법 제562조"}]}],"함정":[{"x":"부담부 증여에서 부담의무의 불이행을 이유로 증여계약을 해제한 경우, 이미 이행한 부분에 대해서는 영향을 미치지 않는다.","o":"부담 불이행 해제는 쌍무계약 규정에 의하므로 원상회복의무가 생긴다.","src":"민법 제561조"},{"x":"수증자가 직계존속인 증여자에 대하여 범죄행위를 한 경우, 증여자가 용서의 의사를 표시하여도 해제권은 소멸하지 않는다.","o":"용서의 의사표시를 하면 해제권이 소멸한다.","src":"민법 제556조"},{"x":"증여계약 이후에 증여자의 재산상태가 현저히 변경되고 그 이행으로 인하여 생계에 중대한 영향을 미칠 경우에는 증여자는 증여를 해제하고 이미 이행한 부분의 반환을 청구할 수 있다.","o":"이미 이행한 부분에는 영향을 미치지 않는다.","src":"민법 제558조"},{"x":"증여는 상대방의 승낙을 필요로 하지 아니한다.","o":"상대방의 승낙으로 효력이 생긴다.","src":"민법 제554조"},{"x":"상대부담있는 증여의 증여자는 목적물의 하자나 흠결을 알고 수증자에게 고지하지 않은 때에만 매도인과 같은 담보책임을 부담한다.","o":"부담의 한도에서 매도인과 같은 담보책임을 진다.","src":"민법 제559조"},{"x":"증여의 의사가 서면으로 표시되지 않은 경우, 그 증여의 이행이 전부 완료되었더라도 수증자는 해제할 수 있다.","o":"이행이 완료된 부분은 해제할 수 없다.","src":"민법 제558조"},{"x":"‘서면에 의하지 않은 것’을 이유로 하는 증여에서의 해제권은 제척기간의 적용을 받는다.","o":"제척기간의 적용을 받지 않는다.","src":"기출 2024-35"},{"x":"부담부증여의 경우, 상대방이 자신의 의무를 이행하지 아니하더라도 이미 증여계약의 이행이 완료되었으면 증여자는 해제할 수 없다.","o":"쌍무계약 규정에 의해 부담 불이행 시 해제할 수 있다.","src":"민법 제561조"},{"x":"서면에 의하지 않은 부담부증여의 경우, 수증자가 부담의 이행을 완료하였더라도 증여자는 ‘서면에 의하지 않은 증여’임을 이유로 해제할 수 있다.","o":"수증자가 부담 이행을 완료하면 서면 없음을 이유로 해제할 수 없다.","src":"기출 2024-35"},{"x":"증여계약의 성립에는 상대방의 승낙을 필요로 하지 아니한다.","o":"상대방의 승낙이 필요하다.","src":"민법 제554조"},{"x":"부담부 증여에서 수증자가 부담의 이행을 완료한 경우, 증여자의 증여 의무 이행이 완료되지 않았다면 증여자는 특별한 사정이 없는 한 증여계약을 해제할 수 있다.","o":"수증자가 부담을 이행했다면 해제할 수 없다.","src":"기출 2025-31"},{"x":"서면에 의하지 않았음을 이유로 하는 증여계약의 해제권은 형성권으로서 제척기간의 적용을 받는다.","o":"제척기간의 적용을 받지 않는다.","src":"기출 2025-31"},{"x":"수증자가 직계존속인 증여자에 대하여 범죄행위를 한 경우, 증여자가 용서의 의사를 표시하여도 해제권은 소멸하지 않는다.","o":"용서의 의사를 표시하면 해제권이 소멸한다.","src":"민법 제556조"}]},"대차형 계약(소비대차·사용대차)":{"묶음":[{"머리":"소비대차","줄":[{"t":"소비대차: 당사자 일방이 금전 기타 대체물의 소유권을 상대방에게 이전할 것을 약정하고 상대방은 같은 종류, 품질 및 수량으로 반환할 것을 약정함으로써 효력이 생긴다(낙성계약, 무이자 원칙).","src":"민법 제598조"},{"t":"이자나 변제기에 대한 합의가 없어도 소비대차는 성립한다. 차주가 현실로 목적물을 수수해야만 성립하는 요물계약이 아니다.","src":"민법 제598조, 기출 2022-34, 2025-36"},{"t":"대주가 목적물을 인도하기 전에 당사자 일방이 파산선고를 받으면 소비대차는 효력을 잃는다.","src":"민법 제599조"},{"t":"이자 있는 소비대차는 차주가 목적물을 인도받은 때부터 이자를 계산한다. 차주가 책임 있는 사유로 수령을 지체하면 대주가 이행을 제공한 때부터 계산한다.","src":"민법 제600조"},{"t":"이자 없는 소비대차의 당사자는 목적물을 인도하기 전에는 언제든지 계약을 해제할 수 있으나, 상대방에게 생긴 손해가 있으면 배상하여야 한다. 인도 후에는 해제할 수 없다.","src":"민법 제601조"},{"t":"대주의 담보책임: 이자 있는 소비대차는 매도인의 하자담보 규정(제580조 내지 제582조)을 준용한다. 이자 없는 소비대차는 차주가 하자 있는 물건의 가액으로 반환할 수 있다. 대주가 하자를 알고 차주에게 고지하지 않은 때에는 이자 있는 소비대차와 같이 담보책임을 진다.","src":"민법 제602조"},{"t":"반환시기: 차주는 약정시기에 같은 종류, 품질, 수량의 물건을 반환하여야 한다. 약정이 없으면 대주는 상당한 기간을 정하여 반환을 최고하여야 하나 차주는 언제든지 반환할 수 있다.","src":"민법 제603조"},{"t":"차주가 같은 종류·품질·수량의 물건을 반환할 수 없는 때에는 그때의 시가로 상환한다. 특정 외화 채무에서 그 외화가 강제통용력을 잃으면 그 나라의 다른 통화로 변제할 수 있다(제376조, 제377조 제2항).","src":"민법 제604조, 기출 2024-24"},{"t":"준소비대차: 당사자 쌍방이 소비대차에 의하지 아니하고 금전 기타 대체물을 지급할 의무가 있는 경우에 그 목적물을 소비대차의 목적으로 하기로 약정하면 소비대차의 효력이 생긴다. 구채무가 소비대차인 경우에도 성립할 수 있다.","src":"민법 제605조, 기출 2022-34, 2025-36"},{"t":"대물대차: 금전대차에서 차주가 금전에 갈음하여 유가증권 기타 물건의 인도를 받은 때에는 그 인도시의 가액으로써 차용액으로 한다.","src":"민법 제606조"},{"t":"대물반환의 예약: 차용물의 반환에 관하여 차주가 차용물에 갈음하여 다른 재산권을 이전할 것을 예약한 경우 그 재산의 예약당시 가액이 차용액 및 이에 붙인 이자의 합산액을 넘지 못한다. 위반한 약정으로 차주에게 불리한 것은 환매 기타 어떤 명목이라도 효력이 없다.","src":"민법 제607조, 제608조"}]},{"머리":"사용대차","줄":[{"t":"사용대차: 당사자 일방이 상대방에게 무상으로 사용, 수익하게 하기 위하여 목적물을 인도할 것을 약정하고 상대방은 이를 사용·수익한 후 반환할 것을 약정함으로써 효력이 생긴다(낙성·무상·편무계약).","src":"민법 제609조"},{"t":"차주는 계약 또는 목적물의 성질에 의하여 정하여진 용법으로 사용·수익하여야 한다. 대주의 승낙이 없으면 제3자에게 사용·수익하게 하지 못하고, 위반하면 대주는 계약을 해지할 수 있다. 해지하지 않고도 제3자에게 목적물 인도를 청구할 수 있다.","src":"민법 제610조, 기출 2022-33"},{"t":"비용 부담: 차주는 차용물의 통상의 필요비를 부담하므로 대주에게 상환을 청구할 수 없다. 기타 비용(유익비 등)은 제594조 제2항(제203조)에 따라 가액 증가가 현존하는 경우 상환을 청구할 수 있다.","src":"민법 제611조, 기출 2021-34, 2022-33"},{"t":"사용대차에는 증여자의 담보책임(제559조)과 이자 없는 소비대차의 해제(제601조)가 준용된다. 대주는 하자를 알고 고지하지 않은 경우에만 담보책임을 진다. 대주가 목적물을 인도하기 전에는 당사자 누구든 계약을 해제할 수 있고 손해가 있으면 배상한다.","src":"민법 제612조, 기출 2021-34, 2025-37"},{"t":"반환시기: 약정시기에 반환. 약정이 없으면 계약 또는 목적물의 성질에 의한 사용·수익이 종료한 때. 사용·수익에 족한 기간이 경과한 때 대주는 언제든지 해지할 수 있다.","src":"민법 제613조"},{"t":"차주가 사망하거나 파산선고를 받은 때 대주는 계약을 해지할 수 있다.","src":"민법 제614조"},{"t":"차주는 반환 시 원상회복하여야 하고 부속시킨 물건은 철거할 수 있다.","src":"민법 제615조"},{"t":"수인이 공동하여 물건을 차용한 때에는 연대하여 의무를 부담한다.","src":"민법 제616조"},{"t":"계약 또는 목적물의 성질에 위반한 사용·수익으로 생긴 손해배상 청구와 차주가 지출한 비용의 상환청구는 대주가 물건의 반환을 받은 날부터 6월 내에 하여야 한다.","src":"민법 제617조"},{"t":"차주는 선량한 관리자의 주의로 차용물을 보관하여야 하고 차주는 소유자인 대주의 처분을 금지시킬 수 없다(채권적 권리).","src":"기출 2022-33"}]}],"함정":[{"x":"차주는 대주에게 차용물의 통상의 필요비의 상환을 청구할 수 있다.","o":"통상의 필요비는 차주가 부담한다.","src":"민법 제611조"},{"x":"차주는 유익비를 지출하여 가액 증가가 현존하는 경우에도 그 상환을 청구할 수 없다.","o":"가액 증가가 현존하면 상환을 청구할 수 있다.","src":"민법 제611조"},{"x":"차주는 자신의 사용ㆍ수익을 위하여 소유자인 사용대주가 목적물을 처분하는 것을 금지시킬 수 있다.","o":"사용대차는 채권이므로 처분을 금지시킬 수 없다.","src":"기출 2022-33"},{"x":"수인이 공동으로 물건을 차용한 때에는 그 수인은 균등한 비율로 분할된 채권과 채무를 부담한다.","o":"연대하여 의무를 부담한다.","src":"민법 제616조"},{"x":"차주는 자기 재산과 동일한 주의로 차용물을 보관하여야 한다.","o":"선량한 관리자의 주의로 보관한다.","src":"기출 2022-33"},{"x":"이자 없는 소비대차의 당사자는 목적물의 인도 후라도 상대방의 손해를 배상하면 언제든지 계약을 해제할 수 있다.","o":"목적물 인도 전에만 해제할 수 있다.","src":"민법 제601조"},{"x":"이자 없는 소비대차의 경우에는 대주가 목적물에 하자가 있음을 알면서 이를 차주에게 고지하지 않았더라도 당사자 사이에 특약이 없는 한 이자 있는 소비대차에서와 동일한 담보책임을 지지 않는다.","o":"하자를 알고 고지하지 않았으면 담보책임을 진다.","src":"민법 제602조"},{"x":"차주가 어느 나라의 특정한 종류의 외화로 반환해야 하는 경우, 그 종류의 외화가 강제통용력을 잃어 이를 반환할 수 없는 때에는 그 나라의 반환할 수 있는 다른 통화로는 변제할 수 없다.","o":"다른 통화로 변제할 수 있다.","src":"기출 2024-24"},{"x":"소비대차계약은 요물계약이다.","o":"낙성계약이다.","src":"민법 제598조"},{"x":"대여금에 대한 이자나 변제기에 대한 합의가 없다면 소비대차는 성립할 수 없다.","o":"합의가 없어도 성립한다.","src":"민법 제598조"},{"x":"금전대차의 경우에 차주가 약정금액에 갈음하여 유가증권 기타 물건의 인도를 받았더라도 그 인도시의 가액이 아니라 약정금액을 차용액으로 한다.","o":"인도시의 가액이 차용액이다.","src":"민법 제606조"},{"x":"준소비대차는 구채무가 소비대차인 경우에는 이를 기초로 성립할 수 없다.","o":"구채무가 소비대차인 경우에도 성립할 수 있다.","src":"기출 2025-36"},{"x":"사용대차는 낙성·유상계약이다.","o":"낙성·무상계약이다.","src":"민법 제609조"},{"x":"차주는 대주의 승낙이 없더라도 제3자에게 차용물을 사용ㆍ수익하게 할 수 있다.","o":"대주의 승낙이 있어야 한다.","src":"민법 제610조"},{"x":"계약 성립 후 아직 대주가 목적물을 인도하기 전이라면 대주는 차주가 입은 손해를 배상하지 않고 언제든지 계약을 해제할 수 있다.","o":"손해가 있으면 배상하여야 한다.","src":"민법 제601조"},{"x":"이자없는 소비대차의 당사자는 목적물의 인도전에는 언제든지 계약을 해제할 수 있으며, 이로 인해 상대방에게 손해가 발생하더라도 배상할 책임이 없다.","o":"상대방에게 생긴 손해는 배상하여야 한다.","src":"민법 제601조"},{"x":"차주는 특별한 사정이 없는 한 차용물의 통상의 필요비를 부담하지 않는다.","o":"차주가 통상의 필요비를 부담한다.","src":"민법 제611조"},{"x":"차주가 차용물을 반환하는 경우, 이에 부속시킨 물건은 철거할 수 없다.","o":"철거할 수 있다.","src":"민법 제615조"},{"x":"계약에 위반한 사용ㆍ수익으로 인한 손해의 배상은 대주가 물건의 반환을 받은 날로부터 6개월이 지났지만, 3년이 지나기 전에는 청구할 수 있다.","o":"반환받은 날부터 6월 내에 청구하여야 한다.","src":"민법 제617조"},{"x":"차주는 대주의 승낙이 없어도 제3자에게 차용물을 사용ㆍ수익하게 할 수 있다.","o":"대주의 승낙이 있어야 한다.","src":"민법 제610조"}]},"임대차":{"묶음":[{"머리":"임대차의 성립과 존속기간","줄":[{"t":"임대차: 당사자 일방이 상대방에게 목적물을 사용, 수익하게 할 것을 약정하고 상대방이 이에 대하여 차임을 지급할 것을 약정함으로써 효력이 생긴다.","src":"민법 제618조"},{"t":"임대차보증금의 수수는 임대차계약의 성립요건이 아니다.","src":"기출 2023-37"},{"t":"처분의 능력 또는 권한 없는 자의 단기임대차 기간 상한: 식목·채염 또는 석조·석회조·연와조 건축을 목적으로 한 토지 10년, 기타 토지 5년, 건물 기타 공작물 3년, 동산 6월. 갱신은 기간만료 전 토지 1년, 건물·공작물 3월, 동산 1월 내.","src":"민법 제619조, 제620조"},{"t":"부동산임차인은 반대약정이 없으면 임대인에게 임대차등기절차에 협력할 것을 청구할 수 있고, 등기한 때부터 제3자에 대하여 효력이 생긴다.","src":"민법 제621조"},{"t":"건물 소유를 목적으로 한 토지임대차는 등기하지 않아도 임차인이 지상건물을 등기하면 제3자에 대하여 효력이 생기나, 건물이 임대차기간 만료 전에 멸실 또는 후폐하면 효력을 잃는다.","src":"민법 제622조"}]},{"머리":"임대인·임차인의 권리의무","줄":[{"t":"임대인은 목적물을 임차인에게 인도하고 계약존속 중 사용·수익에 필요한 상태를 유지하게 할 의무가 있다.","src":"민법 제623조"},{"t":"임대인이 임대물의 보존에 필요한 행위를 하는 때 임차인은 거절하지 못한다. 임차인의 의사에 반하는 보존행위로 임차의 목적을 달성할 수 없는 때에만 계약을 해지할 수 있다.","src":"민법 제624조, 제625조"},{"t":"필요비 상환청구: 임차인이 임차물의 보존에 관한 필요비를 지출한 때 임대인에게 즉시 상환을 청구할 수 있다. 유익비는 임대차 종료시에 가액의 증가가 현존한 때에 한하여 임대인의 선택에 따라 지출액이나 증가액을 상환하며 법원은 상환기간을 허여할 수 있다.","src":"민법 제626조"},{"t":"임차인이 비용상환청구권을 포기하거나 유익비상환청구 포기 대신 원상회복의무를 지지 않기로 하는 합의는 유효하다.","src":"기출 2023-35, 2022-39"},{"t":"일부멸실: 임차물의 일부가 임차인의 과실 없이 멸실 기타 사유로 사용·수익할 수 없는 때 임차인은 그 부분의 비율에 의한 차임 감액을 청구할 수 있다. 잔존 부분으로 임차 목적을 달성할 수 없는 때 계약을 해지할 수 있다.","src":"민법 제627조"},{"t":"차임증감청구: 공과부담의 증감 기타 경제사정의 변동으로 약정한 차임이 상당하지 않게 된 때 장래에 대하여 증감을 청구할 수 있다.","src":"민법 제628조"},{"t":"차임지급시기: 동산·건물·대지는 매월말, 기타 토지는 매년말, 수확기 있는 것은 수확 후 지체없이.","src":"민법 제633조"},{"t":"임차인의 통지의무: 임차물의 수리를 요하거나 임차물에 대하여 권리를 주장하는 자가 있는 때 지체 없이 임대인에게 통지하여야 한다(임대인이 이미 안 때는 제외).","src":"민법 제634조"},{"t":"임대차보증금 반환의무와 임차목적물 반환의무는 동시이행이다. 연체차임은 목적물 반환 시까지 보증금에서 당연 공제되고, 차임채권이 양도되어도 임차인은 공제를 주장할 수 있다. 임차인은 보증금반환채권으로 유치권을 주장할 수 없다.","src":"기출 2023-37"}]},{"머리":"임차권의 양도·전대","줄":[{"t":"임차인은 임대인의 동의 없이 임차권을 양도하거나 임차물을 전대하지 못한다. 위반하면 임대인은 계약을 해지할 수 있다. 동의 없는 전대차계약 자체는 유효하다.","src":"민법 제629조, 기출 2023-36"},{"t":"임대인의 동의를 얻은 전대: 전차인은 직접 임대인에 대하여 의무를 부담하고 전대인에 대한 차임 지급으로 임대인에게 대항하지 못한다(차임 선급은 전대차계약상 차임지급시기를 기준). 임대인의 임차인에 대한 권리행사는 영향받지 않는다.","src":"민법 제630조, 기출 2023-36"},{"t":"임대인의 동의를 얻어 전대한 경우 임대인과 임차인의 합의로 계약을 종료한 때에도 전차인의 권리는 소멸하지 않는다.","src":"민법 제631조"},{"t":"건물의 임차인이 건물의 소부분을 타인에게 사용하게 하는 경우에는 임대인의 동의가 필요 없다(제630조 내지 제631조 적용 없음).","src":"민법 제632조"},{"t":"임대인의 동의 없이 전대하여도 임대차가 존속하는 동안 임대인은 전차인에게 불법점유를 이유로 차임 상당 손해배상을 청구할 수 없다.","src":"기출 2023-36"}]},{"머리":"임대차의 종료","줄":[{"t":"기간의 약정이 없는 임대차는 당사자가 언제든지 해지통고를 할 수 있고, 상대방이 통고를 받은 날부터 토지·건물 기타 공작물은 임대인 통고 6월, 임차인 통고 1월, 동산은 5일이 경과하면 효력이 생긴다.","src":"민법 제635조"},{"t":"기간의 약정이 있어도 당사자 일방 또는 쌍방이 그 기간 내에 해지할 권리를 보류한 때에는 제635조를 준용한다. 전차인이 해지권을 보류한 경우도 같다.","src":"민법 제636조"},{"t":"임차인이 파산선고를 받은 경우 기간의 약정이 있어도 임대인 또는 파산관재인은 제635조에 의해 해지통고를 할 수 있으나, 각 당사자는 해지로 인한 손해배상을 청구하지 못한다.","src":"민법 제637조"},{"t":"해지통고로 종료된 경우 임대물이 적법하게 전대되었으면 임대인은 전차인에게 그 사유를 통지하여야 해지로 전차인에게 대항할 수 있고, 통지를 받은 전차인에게는 제635조 제2항(6월·1월·5일)을 준용한다.","src":"민법 제638조"},{"t":"묵시의 갱신: 기간 만료 후 임차인이 사용·수익을 계속하고 임대인이 상당한 기간 내에 이의를 하지 않으면 전임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 당사자는 제635조에 의해 언제든 해지통고를 할 수 있다. 전임대차에 대하여 제3자가 제공한 담보는 기간의 만료로 소멸한다.","src":"민법 제639조"},{"t":"차임연체와 해지: 건물 기타 공작물의 임대차에서 차임연체액이 2기의 차임액에 달하는 때 임대인은 최고 없이 해지할 수 있다. 건물·공작물의 소유 또는 식목·채염·목축을 목적으로 한 토지임대차에도 준용한다.","src":"민법 제640조, 제641조"},{"t":"지상건물 등이 담보물권의 목적인 때에는 담보물권자에게 통지한 후 상당한 기간이 경과해야 해지 효력이 생긴다(제288조 준용).","src":"민법 제642조"}]},{"머리":"토지임차인의 권리와 부속물매수청구","줄":[{"t":"갱신청구권·지상물매수청구권: 건물 기타 공작물의 소유 또는 식목·채염·목축을 목적으로 한 토지임대차의 기간이 만료한 경우 지상시설이 현존하면 임차인은 갱신을 청구할 수 있고, 임대인이 갱신을 원하지 않으면 상당한 가액으로 매수를 청구할 수 있다.","src":"민법 제643조"},{"t":"기간의 약정이 없는 토지임대차에서 임대인이 해지통고를 한 경우, 임차인은 계약갱신의 청구 없이 바로 지상물매수를 청구할 수 있다.","src":"기출 2021-35"},{"t":"임차인이 건물을 타인에게 양도한 후에는 건물매수청구권을 행사할 수 없다. 임차인 채무불이행(차임연체 등)으로 해지된 경우에는 지상물매수청구권을 행사할 수 없다. 건축허가를 받지 않은 건물도 매수청구 대상이 될 수 있다.","src":"기출 2023-35, 2025-32"},{"t":"임차 토지와 타인 토지에 걸쳐 건립된 건물은 임차지 부분만 따로 매수청구할 수 없다.","src":"기출 2025-32"},{"t":"전차인의 임대청구권·매수청구권: 토지임차인이 적법하게 전대하고 임대차·전대차 기간이 동시에 만료되며 지상시설이 현존하는 때 전차인은 임대인에게 전전대차와 동일한 조건으로 임대할 것을 청구할 수 있고, 임대인이 원하지 않으면 매수를 청구할 수 있다. 지상권자가 토지를 임대한 경우에도 준용.","src":"민법 제644조, 제645조"},{"t":"부속물매수청구권: 건물 기타 공작물의 임차인이 사용의 편익을 위하여 임대인의 동의를 얻어 부속한 물건이 있는 때 임대차 종료시에 매수를 청구할 수 있다. 임대인으로부터 매수한 부속물도 같다.","src":"민법 제646조"},{"t":"전차인의 부속물매수청구권: 적법한 전대의 전차인이 사용의 편익을 위하여 임대인의 동의를 얻어 부속한 물건, 또는 임대인으로부터 매수하였거나 그 동의를 얻어 임차인으로부터 매수한 부속물은 전대차 종료시 임대인에게 매수를 청구할 수 있다.","src":"민법 제647조"},{"t":"부속물매수청구권은 건물 기타 공작물의 임차인의 권리이다(토지임차인은 지상물매수청구권). 부속물이 임차물의 구성부분이 되어 독립성을 잃으면 대상이 되지 않고, 임차인 채무불이행으로 해지된 경우에는 행사할 수 없다.","src":"기출 2025-38, 2021-35, 2023-35"}]},{"머리":"법정담보권과 강행규정","줄":[{"t":"토지임대인이 임대차에 관한 채권으로 임차지에 부속·사용 편익에 공용된 임차인 소유 동산 및 토지의 과실을 압류한 때 질권과 동일한 효력이 있다. 건물 기타 공작물의 임대인이 임대차에 관한 채권으로 부속한 임차인 소유 동산을 압류한 때에도 같다.","src":"민법 제648조, 제650조"},{"t":"토지임대인이 변제기를 경과한 최후 2년의 차임채권으로 지상의 임차인 소유 건물을 압류한 때 저당권과 동일한 효력이 있다.","src":"민법 제649조"},{"t":"강행규정(임차인·전차인에게 불리한 약정은 무효): 제627조, 제628조, 제631조, 제635조, 제638조, 제640조, 제641조, 제643조 내지 제647조.","src":"민법 제652조"},{"t":"일시사용을 위한 임대차 또는 전대차임이 명백한 경우 제628조(차임증감), 제638조, 제640조, 제646조 내지 제648조, 제650조, 제652조는 적용하지 않는다.","src":"민법 제653조"},{"t":"사용대차의 용법 준수(제610조 제1항)와 원상회복·철거(제615조 내지 제617조)는 임대차에 준용한다.","src":"민법 제654조"}]}],"함정":[{"x":"임차인이 임차물에 부속한 물건이 임차물의 구성부분으로 되면 부속물매수청구권의 대상이 된다.","o":"독립성을 잃고 구성부분이 된 물건은 대상이 아니다.","src":"기출 2021-35"},{"x":"임차인이 유익비를 지출한 때에는 임대인에 대하여 계약 종료 전이라도 즉시 그 상환을 청구할 수 있다.","o":"유익비는 임대차 종료시에 청구할 수 있다(필요비만 즉시 청구).","src":"민법 제626조"},{"x":"임차인이 적법하게 전대한 경우, 전차인이 그 사용의 편익을 위하여 임대인의 동의 없이 임차인으로부터 매수한 부속물의 매수를 임대인에게 청구할 수 있다.","o":"임대인 동의를 얻어 임차인으로부터 매수한 부속물이어야 한다.","src":"민법 제647조"},{"x":"임차인이 파산선고를 받은 경우, 임대차기간의 약정이 있더라도 임대인은 계약해지의 통고를 할 수 있으며 해지로 인한 손해의 배상을 청구할 수 있다.","o":"해지통고는 할 수 있으나 손해배상은 청구하지 못한다.","src":"민법 제637조"},{"x":"전차인이 그 사용의 편익을 위하여 전대인인 임차인의 동의를 얻어 부속한 물건이 있는 때에는 전대차의 종료시에 임대인에 대하여 부속물매수청구권이 있다.","o":"임대인의 동의를 얻어야 한다.","src":"민법 제647조"},{"x":"임대인의 동의 없는 임차인의 전대차계약은 무효이다.","o":"유효하나 임대인은 해지할 수 있다.","src":"민법 제629조"},{"x":"건물임차인이 임대인의 동의 없이 건물의 소부분을 전대한 경우에도 임대인은 임대차계약을 해지할 수 있다.","o":"소부분 전대는 동의가 필요 없어 해지할 수 없다.","src":"민법 제632조"},{"x":"임대인의 동의 있는 전대차의 경우, 임대인은 원칙적으로 임차인에게 임대차계약상의 권리를 행사할 수 없다.","o":"임대인은 임차인에 대한 권리를 행사할 수 있다.","src":"민법 제630조"},{"x":"임차인이 임대인의 동의를 받지 않고 제3자에게 임차물을 전대하여 이를 사용ㆍ수익하게 한 경우, 임대인은 임대차계약이 존속하더라도 제3자에게 불법점유를 이유로 한 차임상당의 손해배상을 청구할 수 있다.","o":"임대차가 존속하는 동안은 청구할 수 없다.","src":"기출 2023-36"},{"x":"임대차계약의 존속 중에는 임대인은 임차인의 임대차보증금반환채권을 수동채권으로 하여 상계적상에 있는 자신의 임차인에 대한 대여금채권과 상계할 수 없다.","o":"상계할 수 있다.","src":"기출 2023-37"},{"x":"부동산임대차 계약을 체결한 후에 이를 등기한 때에는 계약을 체결한 때로부터 제3자에 대하여 효력이 생긴다.","o":"등기한 때부터 효력이 생긴다.","src":"민법 제621조"},{"x":"건물의 소유를 목적으로 한 토지임대차가 등기되지는 아니하였으나 그 지상건물이 등기된 경우, 그 후 건물이 임대차기간 만료 전에 멸실한 때에도 임대차는 계속 제3자에 대하여 효력이 있다.","o":"건물이 멸실하면 대항력을 잃는다.","src":"민법 제622조"},{"x":"임차물의 일부가 임차인의 과실 없이 멸실로 인하여 사용, 수익할 수 없게 되었으나 그 잔존부분으로 임차목적을 달성할 수 있는 경우, 임차인은 그 부분의 비율에 의한 차임의 감액을 청구할 수 없다.","o":"감액을 청구할 수 있다.","src":"민법 제627조"},{"x":"일시사용을 위한 임대차에서 임대물에 대한 공과부담의 증감으로 인하여 약정한 차임이 상당하지 않게 된 경우, 당사자는 장래에 대한 차임의 증감을 청구할 수 있다.","o":"일시사용 임대차에는 제628조가 적용되지 않는다.","src":"민법 제653조"},{"x":"임대차기간이 만료한 후 임대차의 묵시적 갱신이 인정되는 경우, 전(前) 임대차에 대하여 제3자가 제공한 담보는 기간만료로 인하여 소멸하지 아니한다.","o":"기간 만료로 소멸한다.","src":"민법 제639조"},{"x":"Y가 X와 丙 소유의 Z토지 위에 걸쳐서 건립된 경우, 甲은 Y 전체에 대한 매수청구를 할 수 있다.","o":"임차지 위의 부분만 해당하여 전체 매수청구를 할 수 없다.","src":"기출 2025-32"},{"x":"甲과 乙의 임대차계약이 甲의 채무불이행을 이유로 해지되었다 하더라도 甲은 매수청구를 할 수 있다.","o":"채무불이행 해지 시에는 매수청구를 할 수 없다.","src":"기출 2025-32"},{"x":"甲과 乙이 기간의 정함이 없는 임대차계약을 체결한 경우, 乙의 해지통고에 의하여 甲의 임차권이 소멸한 때에는 甲은 매수청구권을 행사할 수 없다.","o":"해지통고로 소멸한 때에도 매수를 청구할 수 있다.","src":"민법 제643조"},{"x":"석조 건축을 목적으로 한 토지의 임대차기간은 20년으로 정할 수 있다.","o":"처분능력·권한 없는 자의 임대차는 10년을 넘지 못한다.","src":"민법 제619조"},{"x":"乙이 X건물에 대한 임차권을 등기한 때에는 그 익일부터 제3자에 대하여 효력이 생긴다.","o":"등기한 때부터 효력이 생긴다.","src":"민법 제621조"},{"x":"甲이 乙의 의사에 반하여 보존행위를 하는 경우, 이로 인하여 임차의 목적을 달성할 수 있더라도 乙은 그 보존행위를 이유로 甲과의 임대차계약을 해지할 수 있다.","o":"임차의 목적을 달성할 수 없는 때에만 해지할 수 있다.","src":"민법 제625조"},{"x":"甲은 丙에게 임대인의 권리를 행사할 수 있지만, 乙에게는 임대인의 권리를 행사할 수 없다.","o":"임대인은 전차인 丙에게도, 임차인 乙에게도 권리를 행사할 수 있다.","src":"민법 제630조"}]},"노무제공형 계약(고용·도급·현상광고)":{"묶음":[{"머리":"고용","줄":[{"t":"고용: 당사자 일방이 상대방에 대하여 노무를 제공할 것을 약정하고 상대방이 이에 대하여 보수를 지급할 것을 약정함으로써 효력이 생긴다.","src":"민법 제655조"},{"t":"보수 또는 보수액의 약정이 없으면 관습에 의한다. 보수는 약정한 시기에 지급하고, 약정이 없으면 관습, 관습이 없으면 노무를 종료한 후 지체없이 지급한다.","src":"민법 제656조"},{"t":"권리의무의 전속성: 사용자는 노무자의 동의 없이 그 권리를 제3자에게 양도하지 못한다. 노무자는 사용자의 동의 없이 제3자로 하여금 자기에 갈음하여 노무를 제공하게 하지 못한다. 위반하면 상대방은 계약을 해지할 수 있다.","src":"민법 제657조"},{"t":"노무의 내용과 해지권: 사용자가 약정하지 않은 노무의 제공을 요구한 때 노무자가 해지할 수 있다. 약정한 노무가 특수한 기능을 요하는데 노무자에게 그 기능이 없으면 사용자가 해지할 수 있다.","src":"민법 제658조"},{"t":"고용의 약정기간이 3년을 넘거나 당사자 일방 또는 제3자의 종신까지로 된 때 각 당사자는 3년을 경과한 후 언제든지 해지통고를 할 수 있고, 상대방이 통고를 받은 날부터 3월이 경과하면 효력이 생긴다.","src":"민법 제659조"},{"t":"기간의 약정이 없는 고용은 당사자가 언제든지 해지통고를 할 수 있고 상대방이 통고를 받은 날부터 1월이 경과하면 효력이 생긴다. 기간으로 보수를 정한 때는 해지통고를 받은 당기 후의 일기를 경과함으로써 효력이 생긴다.","src":"민법 제660조"},{"t":"기간의 약정이 있어도 부득이한 사유가 있으면 각 당사자는 해지할 수 있다. 사유가 당사자 일방의 과실로 생긴 때에는 상대방에게 손해를 배상한다.","src":"민법 제661조"},{"t":"묵시의 갱신: 기간 만료 후 노무자가 계속 노무를 제공하고 사용자가 상당한 기간 내에 이의하지 않으면 전고용과 동일한 조건으로 다시 고용한 것으로 본다. 제660조에 의한 해지통고는 가능하고, 제3자가 제공한 담보는 기간 만료로 소멸한다.","src":"민법 제662조"},{"t":"사용자가 파산선고를 받은 경우 고용기간의 약정이 있어도 노무자 또는 파산관재인은 해지할 수 있고, 각 당사자는 해지로 인한 손해배상을 청구하지 못한다.","src":"민법 제663조"},{"t":"민법은 노무자 보호를 위한 해고의 제한에 관한 규정을 두고 있지 않다(근로기준법 영역).","src":"기출 2023-38"}]},{"머리":"도급","줄":[{"t":"도급: 당사자 일방이 어느 일을 완성할 것을 약정하고 상대방이 그 일의 결과에 대하여 보수를 지급할 것을 약정함으로써 효력이 생긴다.","src":"민법 제664조"},{"t":"보수는 완성된 목적물의 인도와 동시에 지급한다. 목적물의 인도를 요하지 않는 경우에는 일을 완성한 후 지체없이 지급한다. 시기의 약정이 있으면 약정에 따르고, 약정이 없으면 관습에 따른다.","src":"민법 제665조, 제656조"},{"t":"부동산공사의 수급인은 보수채권을 담보하기 위하여 그 부동산을 목적으로 한 저당권의 설정을 청구할 수 있다.","src":"민법 제666조"},{"t":"수급인의 담보책임(제667조): 완성된 목적물 또는 완성 전의 성취된 부분에 하자가 있으면 도급인은 상당한 기간을 정하여 보수를 청구할 수 있다. 하자가 중요하지 아니한 경우에 보수에 과다한 비용을 요하면 보수를 청구할 수 없다.","src":"민법 제667조"},{"t":"도급인은 하자의 보수에 갈음하여 또는 보수와 함께 손해배상을 청구할 수 있고, 이 경우 동시이행 규정(제536조)을 준용한다. 보수에 갈음하는 손해배상과 도급인의 보수지급의무도 동시이행 관계이다.","src":"민법 제667조, 기출 2025-33"},{"t":"하자가 중요하지 않고 보수에 과다한 비용이 드는 경우에는 하자보수에 갈음하는 손해배상(보수비용 상당)을 청구할 수 없다는 것이 기출의 정답 기준이다. 하자가 중요하면 보수 비용이 과다해도 보수를 청구할 수 있다.","src":"기출 2021-31, 2022-40, 2025-33"},{"t":"해제: 완성된 목적물의 하자로 계약의 목적을 달성할 수 없는 때 도급인은 해제할 수 있다. 건물 기타 토지의 공작물은 제외(해제 불가, 손해배상만).","src":"민법 제668조"},{"t":"도급인이 제공한 재료의 성질 또는 지시에 기인한 하자는 제667조·제668조를 적용하지 않는다. 수급인이 재료·지시의 부적당함을 알고 고지하지 아니한 때에는 책임이 있다.","src":"민법 제669조"},{"t":"담보책임 존속기간: 하자의 보수, 손해배상, 해제는 목적물의 인도를 받은 날(인도를 요하지 않으면 일의 종료일)부터 1년 내. 토지·건물 기타 공작물의 수급인은 인도 후 5년, 석조·석회조·연와조·금속 기타 유사 재료이면 10년. 하자로 목적물이 멸실·훼손되면 그 날부터 1년 내 행사.","src":"민법 제670조, 제671조"},{"t":"담보책임 면제 특약이 있어도 수급인이 알고 고지하지 아니한 사실에 대하여는 책임을 면하지 못한다.","src":"민법 제672조"},{"t":"수급인이 일을 완성하기 전에는 도급인은 손해를 배상하고 계약을 해제할 수 있다.","src":"민법 제673조"},{"t":"도급인이 파산선고를 받으면 수급인 또는 파산관재인이 계약을 해제할 수 있다. 수급인은 완성된 부분의 보수와 비용에 대하여 파산재단의 배당에 가입할 수 있고, 각 당사자는 해제로 인한 손해배상을 청구하지 못한다.","src":"민법 제674조"},{"t":"천재지변으로 목적물이 멸실되어 일의 완성이 불가능하면 수급인은 보수지급을 청구할 수 없다(수급인 위험부담).","src":"기출 2021-31"},{"t":"신축건물의 소유권은 자기의 노력과 재료를 들여 건축한 사람(수급인)이 원시취득한다. 도급인이 재료의 주요부분을 공급한 경우에는 도급인이 원시취득한다.","src":"기출 2022-40, 2023-39, 2024-30"},{"t":"수급인의 하자담보책임과 채무불이행책임은 경합적으로 인정된다.","src":"기출 2023-39"}]},{"머리":"여행계약","줄":[{"t":"여행계약: 당사자 한쪽이 상대방에게 운송, 숙박, 관광 또는 그 밖의 여행 관련 용역을 결합하여 제공하기로 약정하고 상대방이 그 대금을 지급하기로 약정함으로써 효력이 생긴다.","src":"민법 제674조의2"},{"t":"여행자는 여행을 시작하기 전에는 언제든지 계약을 해제할 수 있으나 상대방에게 발생한 손해를 배상하여야 한다.","src":"민법 제674조의3"},{"t":"부득이한 사유가 있으면 각 당사자는 계약을 해지할 수 있다. 그 사유가 당사자 한쪽의 과실로 생긴 경우 상대방에게 손해를 배상한다. 해지되어도 계약상 귀환운송 의무가 있는 여행주최자는 여행자를 귀환운송하여야 한다. 해지로 인한 추가 비용은 그 사유가 속하는 당사자가, 누구의 사정에도 속하지 않으면 각 당사자가 절반씩 부담한다.","src":"민법 제674조의4"},{"t":"여행자는 약정한 시기에 대금을 지급하여야 하고, 약정이 없으면 관습, 관습이 없으면 여행 종료 후 지체없이 지급한다.","src":"민법 제674조의5"},{"t":"여행주최자의 담보책임: 여행에 하자가 있는 경우 여행자는 하자의 시정 또는 대금의 감액을 청구할 수 있다. 시정에 지나치게 많은 비용이 들거나 시정을 합리적으로 기대할 수 없으면 시정을 청구할 수 없다.","src":"민법 제674조의6"},{"t":"시정 청구는 상당한 기간을 정하여 하여야 한다(즉시 시정이 필요한 경우 제외). 감액 청구에는 상당한 기간을 정할 필요가 없다. 여행자는 시정·감액 청구를 갈음하거나 이와 함께 손해배상을 청구할 수 있다.","src":"민법 제674조의6"},{"t":"여행에 중대한 하자가 있고 시정이 이루어지지 않거나 계약 내용에 따른 이행을 기대할 수 없으면 여행자는 계약을 해지할 수 있다. 해지되면 여행주최자는 대금청구권을 상실하나, 여행자가 실행된 여행으로 이익을 얻은 경우 그 이익을 상환한다.","src":"민법 제674조의7"},{"t":"여행주최자는 해지로 필요하게 된 조치를 할 의무가 있고 귀환운송 의무가 있으면 귀환운송하여야 하며, 상당한 이유가 있으면 비용의 일부를 청구할 수 있다.","src":"민법 제674조의7"},{"t":"담보책임에 기한 권리는 여행 기간 중에도 행사할 수 있고 계약에서 정한 여행 종료일부터 6개월 내에 행사하여야 한다.","src":"민법 제674조의8"},{"t":"제674조의3, 제674조의4, 제674조의6 내지 제674조의8을 위반하는 약정으로 여행자에게 불리한 것은 무효이다(편면적 강행규정).","src":"민법 제674조의9"}]},{"머리":"현상광고","줄":[{"t":"현상광고: 광고자가 어느 행위를 한 자에게 일정한 보수를 지급할 의사를 표시하고 이에 응한 자가 광고에 정한 행위를 완료함으로써 효력이 생긴다(편무계약).","src":"민법 제675조"},{"t":"지정행위의 완료에 조건을 붙일 수 있다.","src":"기출 2024-27"},{"t":"광고에 정한 행위를 완료한 자가 수인인 때 먼저 완료한 자가 보수를 받을 권리가 있다. 동시에 완료한 때는 균등한 비율로 보수를 받으나, 성질상 분할할 수 없거나 광고에 1인만이 보수를 받을 것으로 정한 때는 추첨으로 결정한다.","src":"민법 제676조"},{"t":"광고 있음을 알지 못하고 광고에 정한 행위를 완료한 자도 보수를 받을 권리가 있다.","src":"민법 제677조"},{"t":"우수현상광고: 우수한 자에 한하여 보수를 지급하기로 정하는 때에는 광고에 응모기간을 정한 때에 한하여 효력이 생긴다(응모기간이 없으면 무효).","src":"민법 제678조"},{"t":"우수의 판정은 광고 중에 정한 자가 하고, 정하지 않았으면 광고자가 한다. 우수한 자가 없다는 판정은 할 수 없으나 광고 중에 다른 의사표시가 있거나 성질상 판정의 표준이 정해져 있으면 할 수 있다.","src":"민법 제678조"},{"t":"응모자는 우수 판정에 대하여 이의를 하지 못한다. 수인의 행위가 동등으로 판정된 때에는 제676조 제2항을 준용한다.","src":"민법 제678조"},{"t":"현상광고의 철회: 지정행위의 완료기간을 정한 때는 기간 만료 전에 철회하지 못한다. 기간을 정하지 않은 때는 행위를 완료한 자가 있기 전에 그 광고와 동일한 방법으로 철회할 수 있고, 동일한 방법이 불가능하면 유사한 방법으로 철회하되 철회한 것을 안 자에게만 효력이 있다.","src":"민법 제679조"}]}],"함정":[{"x":"완성된 목적물에 하자가 중요하지 않고 동시에 그 보수에 과다한 비용을 요할 경우, 도급인은 하자보수에 갈음하는 손해배상을 청구할 수 있다.","o":"이 경우 보수 비용 상당의 손해배상은 청구할 수 없다(기출 정답 기준).","src":"기출 2021-31"},{"x":"광고 있음을 모르고 지정행위를 완료한 자는 보수를 청구할 수 없다.","o":"광고를 몰라도 보수를 청구할 수 있다.","src":"민법 제677조"},{"x":"광고에서 정한 행위의 완료에 조건을 붙일 수 없다.","o":"조건을 붙일 수 있다.","src":"기출 2024-27"},{"x":"광고에 그 지정한 행위의 완료기간을 정한 경우, 그 광고와 동일한 방법으로 광고를 철회할 수 있다.","o":"완료기간을 정했으면 기간 만료 전에 철회하지 못한다.","src":"민법 제679조"},{"x":"우수현상광고에서 응모자는 우수의 판정에 대하여 이의를 제기할 수 있다.","o":"이의를 하지 못한다.","src":"민법 제678조"},{"x":"우수현상광고는 응모기간을 정하지 아니하여도 유효하다.","o":"응모기간을 정하지 않으면 효력이 없다.","src":"민법 제678조"},{"x":"민법은 노무자 보호를 위해 해고의 제한에 관한 규정을 두고 있다.","o":"민법에는 해고 제한 규정이 없다.","src":"기출 2023-38"},{"x":"완성된 건물의 하자로 인하여 계약의 목적을 달성할 수 없는 때에는 도급인은 계약을 해제할 수 있다.","o":"건물 기타 토지의 공작물은 해제할 수 없고 손해배상만 청구한다.","src":"민법 제668조"},{"x":"도급인이 재료의 주요부분을 공급하는 경우, 다른 약정이 없으면 완성된 부동산의 소유권은 원시적으로 수급인에게 귀속한다.","o":"도급인에게 귀속한다.","src":"기출 2024-30"},{"x":"고용기간의 약정이 없는 경우에 당사자는 언제든지 계약해지를 통고할 수 있으며, 그 해지의 효력은 상대방이 해지의 통고를 받은 날로부터 3개월이 경과하면 생긴다.","o":"1월이 경과하면 효력이 생긴다.","src":"민법 제660조"},{"x":"목적물의 하자가 도급인의 지시에 기인한 경우, 그 지시의 부적당함을 알고 도급인에게 고지하지 않은 수급인은 그 하자에 대해 담보책임을 지지 않는다.","o":"알고 고지하지 않았으면 담보책임을 진다.","src":"민법 제669조"},{"x":"광고에 정한 행위를 완료한 자가 수인인 경우에 그 우수한 자에 한하여 보수를 지급할 것을 정한 때에는 그 광고에 응모기간을 정하지 않은 경우에도 그 효력이 생긴다.","o":"응모기간을 정하지 않으면 효력이 없다.","src":"민법 제678조"},{"x":"여행자가 여행의 하자를 이유로 여행주최자에게 대금감액을 청구하기 위해서는 상당한 기간을 정해서 하여야 한다.","o":"상당한 기간을 정해야 하는 것은 시정 청구이다.","src":"민법 제674조의6"}]},"위임·임치와 기타 전형계약(여행계약·종신정기금·화해)":{"묶음":[{"머리":"위임","줄":[{"t":"위임: 당사자 일방이 상대방에 대하여 사무의 처리를 위탁하고 상대방이 이를 승낙함으로써 효력이 생긴다. 수임인은 위임의 본지에 따라 선량한 관리자의 주의로 처리하여야 한다(무상위임도 같다).","src":"민법 제680조, 제681조"},{"t":"복임권의 제한: 수임인은 위임인의 승낙이나 부득이한 사유 없이 제3자로 하여금 자기에 갈음하여 위임사무를 처리하게 하지 못한다. 제3자를 선임한 경우 제121조, 제123조(복대리인 선임 책임)를 준용한다. 위임인의 지명에 따른 선임은 부적임·불성실을 알고 통지나 해임을 태만한 때만 책임.","src":"민법 제682조"},{"t":"수임인은 위임인의 청구가 있으면 처리상황을 보고하고 위임이 종료하면 지체없이 전말을 보고하여야 한다.","src":"민법 제683조"},{"t":"수임인이 위임인의 지시를 따르는 것이 위임인에게 불이익한 때에는 그 사실을 통지하고 지시의 변경을 요청하여야 한다.","src":"기출 2024-29"},{"t":"수임인은 위임사무 처리로 받은 금전 기타 물건과 과실을 인도하여야 하고, 위임인을 위하여 자기 명의로 취득한 권리는 위임인에게 이전하여야 한다.","src":"민법 제684조"},{"t":"수임인이 위임인에게 인도할 금전 또는 위임인의 이익을 위해 사용할 금전을 자기를 위해 소비한 때에는 소비한 날 이후의 이자를 지급하고 그 외의 손해를 배상한다.","src":"민법 제685조"},{"t":"보수: 수임인은 특별한 약정이 없으면 보수를 청구하지 못한다(무보수 원칙). 보수는 위임사무 완료 후 청구하되 기간으로 정한 때에는 기간 경과 후 청구할 수 있다. 수임인의 책임 없는 사유로 위임이 종료된 때에는 이미 처리한 사무의 비율에 따른 보수를 청구할 수 있다.","src":"민법 제686조"},{"t":"비용선급: 위임사무의 처리에 비용을 요하는 때 위임인은 수임인의 청구에 의하여 선급하여야 한다.","src":"민법 제687조"},{"t":"수임인은 필요비를 지출한 때 지출한 날 이후의 이자를 청구할 수 있고, 필요한 채무를 부담하면 위임인에게 자기에 갈음하여 변제하게 하거나 변제기 전이면 상당한 담보를 제공하게 할 수 있으며, 과실 없이 손해를 받으면 그 배상을 청구할 수 있다.","src":"민법 제688조"},{"t":"위임은 각 당사자가 언제든지 해지할 수 있다(유상위임도 같다). 부득이한 사유 없이 상대방의 불리한 시기에 해지한 때에는 손해를 배상하여야 한다.","src":"민법 제689조"},{"t":"위임의 종료: 당사자 한쪽의 사망 또는 파산. 수임인이 성년후견개시 심판을 받은 경우도 같다.","src":"민법 제690조"},{"t":"위임종료 시 급박한 사정이 있으면 수임인·상속인·법정대리인은 위임인 쪽이 사무를 처리할 수 있을 때까지 계속 처리하여야 한다(위임 존속과 동일한 효력). 종료사유는 상대방에게 통지하거나 상대방이 안 때가 아니면 대항하지 못한다.","src":"민법 제691조, 제692조"}]},{"머리":"임치","줄":[{"t":"임치: 당사자 일방이 상대방에 대하여 금전이나 유가증권 기타 물건의 보관을 위탁하고 상대방이 이를 승낙함으로써 효력이 생긴다.","src":"민법 제693조"},{"t":"수치인은 임치인의 동의 없이 임치물을 사용하지 못한다(유상·무상 모두).","src":"민법 제694조"},{"t":"보수 없이 임치를 받은 자(무상수치인)는 임치물을 자기재산과 동일한 주의로 보관한다. 유상수치인은 선량한 관리자의 주의로 보관한다.","src":"민법 제695조"},{"t":"수치인의 통지의무: 임치물에 대한 권리를 주장하는 제3자가 수치인에 대하여 소를 제기하거나 압류한 때 지체없이 임치인에게 통지(무상수치인 포함).","src":"민법 제696조"},{"t":"임치인은 임치물의 성질 또는 하자로 생긴 손해를 수치인에게 배상하여야 하나, 수치인이 그 성질 또는 하자를 안 때에는 배상하지 않는다.","src":"민법 제697조"},{"t":"임치기간의 약정이 있으면 수치인은 부득이한 사유 없이 기간 만료 전에 해지하지 못하나, 임치인은 언제든지 해지할 수 있다. 약정이 없으면 각 당사자가 언제든지 해지할 수 있다.","src":"민법 제698조, 제699조"},{"t":"임치물은 그 보관한 장소에서 반환하여야 한다. 수치인이 정당한 사유로 전치한 때에는 현존하는 장소에서 반환할 수 있다.","src":"민법 제700조"},{"t":"임치에는 위임의 복임권 제한(제682조), 취득물 인도(제684조), 금전소비 책임(제685조), 보수청구(제686조), 비용선급(제687조), 필요비 이자·채무 변제(제688조 제1항·제2항)를 준용한다. 그래서 무상수치인도 비용 선급을 청구하고 필요비 지출일 이후의 이자를 청구할 수 있다.","src":"민법 제701조"},{"t":"소비임치: 수치인이 계약으로 임치물을 소비할 수 있는 경우 소비대차 규정을 준용하되, 반환시기의 약정이 없으면 임치인은 언제든지 반환을 청구할 수 있다.","src":"민법 제702조"}]},{"머리":"종신정기금","줄":[{"t":"종신정기금계약: 당사자 일방이 자기, 상대방 또는 제3자의 종신까지 정기로 금전 기타 물건을 상대방 또는 제3자에게 지급할 것을 약정함으로써 효력이 생긴다. 제3자도 정기금채권자가 될 수 있고 대체물도 목적이 될 수 있다.","src":"민법 제725조, 기출 2021-36"},{"t":"종신정기금은 일수로 계산한다.","src":"민법 제726조"},{"t":"정기금채무자가 원본을 받은 경우 지급을 해태하거나 기타 의무를 이행하지 않으면 정기금채권자는 원본의 반환을 청구(해제)할 수 있다. 이미 지급받은 채무액에서 원본의 이자를 공제한 잔액을 채무자에게 반환한다. 손해배상 청구에 영향이 없고 동시이행 규정이 준용된다.","src":"민법 제727조, 제728조"},{"t":"사망이 정기금채무자의 책임 있는 사유로 인한 때 법원은 정기금채권자 또는 상속인의 청구로 상당한 기간 채권의 존속을 선고할 수 있다. 유증에 의한 종신정기금채권에도 준용한다.","src":"민법 제729조, 제730조"}]},{"머리":"화해","줄":[{"t":"화해: 당사자가 상호 양보하여 당사자간의 분쟁을 종지할 것을 약정함으로써 효력이 생긴다.","src":"민법 제731조"},{"t":"화해의 창설적 효력: 당사자 일방이 양보한 권리는 소멸하고 상대방이 화해로 인하여 그 권리를 취득한다. 화해 전의 법률관계는 소멸하고 그에 기초한 담보도 소멸한다.","src":"민법 제732조, 기출 2021-37, 2025-35"},{"t":"화해계약은 착오를 이유로 취소하지 못한다. 다만 화해당사자의 자격 또는 화해의 목적인 분쟁 이외의 사항에 착오가 있는 때에는 취소할 수 있다. 분쟁의 대상인 법률관계 자체에 관한 착오는 취소 사유가 되지 않는다.","src":"민법 제733조, 기출 2025-35"},{"t":"화해계약이 사기·강박으로 이루어진 경우에는 취소할 수 있다. 당사자가 임의로 처분할 수 없는 법률관계에 관한 화해계약은 효력이 없다.","src":"기출 2021-37, 2025-35"}]}],"함정":[{"x":"제3자는 정기금채권자가 될 수 없다.","o":"제3자도 정기금채권자가 될 수 있다.","src":"민법 제725조"},{"x":"여행자가 여행의 하자를 이유로 여행주최자에게 대금감액을 청구하기 위해서는 상당한 기간을 정해서 하여야 한다.","o":"상당한 기간을 정하는 것은 시정 청구이다.","src":"민법 제674조의6"},{"x":"무상수치인은 임치인에 대하여 임치물의 보관에 필요한 비용의 선급을 청구할 수 없다.","o":"선급을 청구할 수 있다(제701조, 제687조).","src":"민법 제701조"},{"x":"임치인의 승낙으로 임치물을 제3자에게 보관하게 한 무상수치인은 임치인에 대하여 그 제3자의 선임ㆍ감독에 관한 책임을 지지 않는다.","o":"제682조, 제121조에 따라 선임·감독 책임을 진다.","src":"민법 제701조"},{"x":"임치인은 수치인이 임치물의 하자를 알고 있더라도 그 하자로 인해 발생한 손해를 배상하여야 한다.","o":"수치인이 하자를 안 때에는 배상하지 않는다.","src":"민법 제697조"},{"x":"유상수치인은 자기재산과 동일한 주의로 임치물을 보관하여야 한다.","o":"선량한 관리자의 주의로 보관한다.","src":"민법 제695조"},{"x":"당사자는 부득이한 사유 없이 상대방이 불리한 시기에 위임계약을 해지할 수 없다.","o":"언제든지 해지할 수 있으나 불리한 시기에 부득이한 사유 없이 해지하면 손해를 배상한다.","src":"민법 제689조"},{"x":"수치인이 정당한 사유로 다른 장소에 임치물을 전치하였더라도 그 임치물은 원래의 보관 장소에서 반환하여야 한다.","o":"현존하는 장소에서 반환할 수 있다.","src":"민법 제700조"},{"x":"유상임치인은 자기 재산과 동일한 주의로 임치물을 보관하여야 한다.","o":"유상수치인은 선량한 관리자의 주의로 보관한다.","src":"민법 제695조"},{"x":"유상수치인은 임치인의 동의가 없어도 임치물을 사용할 수 있다.","o":"임치인의 동의 없이 사용하지 못한다.","src":"민법 제694조"},{"x":"수치인이 정당한 사유로 인하여 임치물을 다른 곳으로 옮긴 때에 그 물건의 반환장소는 현존하는 장소에서 반환할 수 없다.","o":"현존하는 장소에서 반환할 수 있다.","src":"민법 제700조"},{"x":"수치인은 임치기간의 약정의 유무와 관계없이 언제든지 임치를 해지할 수 있다.","o":"기간 약정이 있으면 부득이한 사유 없이 기간 만료 전에 해지하지 못한다.","src":"민법 제698조"},{"x":"수임인이 성년후견개시의 심판을 받은 경우, 위임은 종료되지 아니한다.","o":"위임이 종료된다.","src":"민법 제690조"},{"x":"유상위임의 경우, 위임인은 특별한 이유 없이 위임계약을 해지할 수 없다.","o":"언제든지 해지할 수 있다.","src":"민법 제689조"},{"x":"화해계약이 성립되더라도 화해 전 법률관계에 기초한 담보는 특별한 사정이 없는 한 그대로 존속한다.","o":"창설적 효력으로 화해 전 법률관계는 소멸한다.","src":"민법 제732조"},{"x":"수치인은 임치물을 임치인의 주소지에서 반환하여야 한다.","o":"그 보관한 장소에서 반환한다.","src":"민법 제700조"}]},"조합":{"묶음":[{"머리":"조합의 성립과 재산","줄":[{"t":"조합: 2인 이상이 상호출자하여 공동사업을 경영할 것을 약정함으로써 효력이 생긴다. 출자는 금전 기타 재산 또는 노무로 할 수 있다.","src":"민법 제703조"},{"t":"조합원의 출자 기타 조합재산은 조합원의 합유로 한다.","src":"민법 제704조"},{"t":"금전을 출자의 목적으로 한 조합원이 출자시기를 지체하면 연체이자를 지급하는 외에 손해를 배상하여야 한다.","src":"민법 제705조"},{"t":"이익을 조합원 일부에게만 분배하고 다른 조합원은 분배에서 완전히 제외하기로 한 약정은 조합의 본질에 반하여, 그 경우 조합관계가 유효하다고 할 수 없다.","src":"기출 2025-40"},{"t":"부동산 소유자가 조합계약으로 부동산을 출자하기로 하였으나 아직 조합원 합유로 등기되지 않았다면, 그는 제3자에 대하여 그 부동산의 소유권을 행사할 수 있다.","src":"기출 2021-40"}]},{"머리":"업무집행","줄":[{"t":"조합계약으로 업무집행자를 정하지 않으면 조합원의 3분의 2 이상의 찬성으로 선임한다.","src":"민법 제706조"},{"t":"조합의 업무집행은 조합원의 과반수로 결정하고, 업무집행자가 수인이면 그 과반수로 결정한다.","src":"민법 제706조"},{"t":"통상사무는 각 조합원 또는 각 업무집행자가 전행할 수 있으나 사무의 완료 전에 다른 조합원·업무집행자의 이의가 있으면 즉시 중지하여야 한다.","src":"민법 제706조"},{"t":"업무집행 조합원에게는 위임 규정(제681조 내지 제688조)을 준용한다. 업무집행자인 조합원은 정당한 사유 없이 사임하지 못하고 다른 조합원 전원의 일치가 아니면 해임하지 못한다.","src":"민법 제707조, 제708조"},{"t":"업무집행 조합원은 업무집행의 대리권이 있는 것으로 추정한다. 각 조합원은 언제든지 조합의 업무 및 재산상태를 검사할 수 있다.","src":"민법 제709조, 제710조"}]},{"머리":"손익분배와 채무","줄":[{"t":"손익분배 비율을 정하지 않으면 각 조합원의 출자가액에 비례하여 정한다. 이익 또는 손실의 어느 한쪽에만 분배비율을 정한 때에도 그 비율은 이익과 손실에 공통된 것으로 추정한다.","src":"민법 제711조"},{"t":"조합채권자는 채권 발생 당시 조합원의 손실부담 비율을 알지 못한 때 각 조합원에게 균분하여 권리를 행사할 수 있다.","src":"민법 제712조"},{"t":"조합원 중 변제할 자력이 없는 자가 있으면 그 변제할 수 없는 부분은 다른 조합원이 균분하여 변제할 책임이 있다(출자가액 비례가 아님).","src":"민법 제713조"},{"t":"조합원의 지분에 대한 압류는 그 조합원의 장래의 이익배당 및 지분의 반환을 받을 권리에 대하여 효력이 있다. 조합원 개인의 채권자는 조합의 채권에 대해 그 조합원 개인을 집행채무자로 하여 강제집행을 할 수 없다.","src":"민법 제714조, 기출 2023-40"},{"t":"조합의 채무자는 그 채무와 조합원에 대한 채권으로 상계하지 못한다.","src":"민법 제715조"}]},{"머리":"탈퇴·해산·청산","줄":[{"t":"임의탈퇴: 조합 존속기간을 정하지 않았거나 조합원의 종신까지 존속할 것을 정한 때 각 조합원은 언제든지 탈퇴할 수 있으나 부득이한 사유 없이 조합에 불리한 시기에 탈퇴하지 못한다. 존속기간을 정한 때에도 부득이한 사유가 있으면 탈퇴할 수 있다.","src":"민법 제716조"},{"t":"비임의 탈퇴 사유: 사망, 파산, 성년후견의 개시, 제명.","src":"민법 제717조"},{"t":"제명은 정당한 사유가 있는 때에 한하여 다른 조합원의 일치로 결정하고, 제명된 조합원에게 통지하지 않으면 대항하지 못한다.","src":"민법 제718조"},{"t":"탈퇴한 조합원과 다른 조합원 간의 계산은 탈퇴 당시의 조합재산상태에 의한다. 탈퇴 조합원의 지분은 출자의 종류에 불구하고 금전으로 반환할 수 있다. 탈퇴 당시 완결되지 않은 사항은 완결 후에 계산할 수 있다.","src":"민법 제719조"},{"t":"2인으로 이루어진 조합에서 1인이 탈퇴해도 특별한 사정이 없는 한 조합은 해산되지 않고, 조합원 1인의 사망으로도 해산되지 않는다.","src":"기출 2021-40, 2023-40, 2025-40"},{"t":"부득이한 사유가 있는 때 각 조합원은 조합의 해산을 청구할 수 있다. 조합은 계약의 해제로는 소멸하지 않고, 출자를 이행한 조합원이 다른 조합원의 채무불이행을 이유로 조합계약을 해제하여 원상회복을 구할 수 없다.","src":"민법 제720조, 기출 2025-40"},{"t":"청산: 조합이 해산한 때 총조합원 공동으로 또는 그들이 선임한 자가 사무를 집행한다. 청산인 선임은 조합원 과반수로 결정한다. 조합원 중에서 청산인을 정한 때 제708조를 준용한다.","src":"민법 제721조, 제722조, 제723조"},{"t":"청산인의 직무·권한은 제87조(법인 청산인)를 준용하고, 잔여재산은 각 조합원의 출자가액에 비례하여 분배한다.","src":"민법 제724조"}]}],"함정":[{"x":"업무집행자가 아닌 조합원의 과반수의 찬성으로 업무집행자인 조합원을 해임할 수 있다.","o":"다른 조합원 전원의 일치가 있어야 해임할 수 있다.","src":"민법 제708조"},{"x":"조합의 통상사무의 완료 전에 다른 조합원의 이의가 있어도 각 조합원은 그 사무를 중지하지 아니하고 계속 전행할 수 있다.","o":"이의가 있으면 즉시 중지하여야 한다.","src":"민법 제706조"}]}};
